(window.GIM_TS=window.GIM_TS||{})["Niddah.1"]={"from":24,"a":[["משום חשש יציאת זרע כתוצאה מחימום האיבר הנגרם על ידי חיכוכו, כהנים \u0003רוכבי גמלים אסורין לאכול בתרומה\u0004 שודאי נטמאים בעת הרכיבה. ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנינו\u0006 ברייתא \u0005גם כן כך]\u0006 כדברי אביי: \u0003רוכבי גמלים\u0004 — \u0003כולם רשעים,\u0004 מפני שחשודים על הוצאת זרע בשל חיכוך האיבר בבשר הגמל בשעת הרכיבה. \u0003הספנים\u0004 — \u0003כולם צדיקים,\u0004 שכיון ששרויים הם בסכנה מתמדת בהיותם בים, ליבם נתון תמיד בתחינה לפני הקדוש ברוך הוא.","\u0003החמרים\u0004 (הרוכבים על חמורים) — \u0003מהן רשעים מהן צדיקים.\u0004 ובהסבר הבחנה זו בין חמרים רשעים לצדיקים, \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כך: \u0003הא\u0004 \u0005[זה]\u0006 החמר שהוא צדיק — \u0003דמכף\u0004 \u0005[שיש אוכף\u0006 על החמור\u0005]\u0006 ולכן אין מתחכך איבר הרוכב עליו בו. ואילו \u0003הא\u0004 \u0005[זה]\u0006 החמר שהוא רשע — שהחמור \u0003לא מכף\u0004 \u0005[מאוכף],\u0006 ומתחכך איברו של הרוכב בבשר החמור, ובא בכך לידי הוצאת זרע. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 הבדל אחר: \u0003הא\u0004 \u0005[זה]\u0006 החמר שהוא רשע — \u0003דמטרטין\u0004 \u0005[שפוסק]\u0006 שני ירכיו משני צידי החמור, ונמצא איברו מתחכך ישירות בגוף החמור. ואילו \u0003הא\u0004 \u0005[זה]\u0006 החמר שהוא צדיק — ש\u0003לא מטרטין\u0004 \u0005[לא פוסק]\u0006 ירכיו לשני צדדים, אלא רוכב כאשר שתי רגליו פונות לצד אחד של החמור, ואז אין איברו מתחכך בגוף החמור.","ועוד בענין זהירות מהנהגה העשויה להביא ליציאת זרע, נמסר ש\u0003ר' יהושע בן לוי לייט אמאן דגני אפרקיד\u0004 \u0005[היה מקלל\u0006 את \u0005מי ששוכב פרקדן,\u0006 כשפניו למעלה\u0005],\u0006 שכן בכך יכול לבוא לראיית זרע. ושואלים: \u0003איני\u0004 \u0005[האמנם כך הוא]\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יוסף:\u0004 השוכב \u0003פרקדן לא יקרא קרית\u0004 (קריאת) \u0003שמע,\u0004 ומכאן נדייק: \u0003קרית שמע הוא\u0004 ש\u0003לא יקרא\u0004 בעודו שוכב כך, \u0003הא מגנא\u0004 \u0005[הרי\u0006 שעצם \u0005השכיבה]\u0006 פרקדן — \u0003שפיר דמי\u0004 \u0005[נחשבת ראויה]!\u0006","ומשיבים: \u0003ל\u0004עצם \u0003ענין\u0004 \u0003מגנא\u0004 \u0005[שכיבת\u0006 פרקדן\u0005],\u0006 \u0003כי מצלי\u0004 \u0005[כאשר\u0006 היא נעשית \u0005בהטיית מועטה\u0006 של הגוף\u0005]\u0006 — \u0003שפיר דמי\u0004 \u0005[נחשבת ראויה],\u0006 ואולם \u0003לענין קריאת שמע\u0004 בשכיבת פרקדן, אף \u0003כי מצלי\u0004 \u0005[כאשר מוטה מעט]\u0006 גוף השוכב — \u0003אסור\u0004 הדבר. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יוחנן מצלי וקרי\u0004 \u0005[היה שוכב\u0006 פרקדן \u0005בהטייה מועטה\u0006 של הגוף, \u0005וקורא\u0006 כך\u0005]\u0006 \u0003קריאת שמע!\u0004 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 הוא דינו של \u0003ר' יוחנן\u0004 שכן \u0003בעל בשר הוה\u0004 \u0005[היה],\u0006 ולא יכול היה להטות גופו אלא מעט.","\u0003דרך\u0004 (מנהג) \u0003בנות ישראל\u0004 שהן \u0003משמשות\u0004 (בתשמיש המיטה) עם בעליהן \u0003בשני עדים\u0004 (פיסות בד לבדיקה): \u0003אחד לו\u0004 לבעלה שיבדוק בו לאחר תשמיש אם נמצא עליו מדמה, \u0003ואחד לה\u0004 עצמה. \u0003ו\u0004אילו הנשים \u0003הצנועות\u0004 המוסיפות בטהרתן מתקנות להן עד נוסף, \u0003שלישי,\u0004 כדי \u0003לתקן\u0004 בו בבדיקה \u0003את הבית\u0004 (בית הערווה) לפני התשמיש.","ומעתה, אם \u0003נמצא\u0004 דם \u0003על\u0004 עד הבדיקה \u0003שלו,\u0004 לאחר התשמיש — האשה והבעל שניהם \u0003טמאין\u0004 טומאת שבעה, כדין הנדה והבא על הנדה, \u0003וחייבין\u0004 על כך \u0003קרבן\u0004 חטאת, כדין הבא על הנדה בשוגג. ואם \u0003נמצא\u0004 דם \u0003על\u0004 עד הבדיקה \u0003שלה,\u0004 יש להבחין בדין אימתי נמצא הדם: אם נמצא \u0003אותיום\u0004 (מיד) לאחר התשמיש — הבעל והאשה שניהם \u0003טמאין\u0004 טומאת שבעה בוודאי, \u0003וחייבין בקרבן\u0004 חטאת. ואולם אם \u0003נמצא\u0004 הדם \u0003על\u0004 עד הבדיקה \u0003שלה לאחר זמן\u0004 — אפשר שדם זה נראה רק לאחר התשמיש ולכן שניהם \u0003טמאין\u0004 טומאת שבעה \u0003מספק, ופטורין מן הקרבן\u0004 (חטאת).","ובהגדרת פרק זמן זה, \u0003איזהו אחר זמן?\u0004 — שיעור זמן שיש בו \u0003כדי\u0004 שתוכל האשה \u0003שתרד מן המטה ותדיח פניה\u0004 (שלמטה, כלומר, בית הערווה). \u0003ו\u0004אם נמצא דם על עד הבדיקה שלה \u0003אחר כך,\u0004 יותר משיעור זמן זה — האשה עצמה \u0003מטמאה\u0004 למפרע טהרות שנגעה בהן במשך כל \u0003מעת לעת, ואינה מטמאה את בועלה\u0004 טומאת שבעה, ואינו אלא כנוגע בנדה הנטמא טומאת ערב בלבד. \u0003ר' עקיבא אומר: אף\u0004 המוצאת דם על עד הבדיקה לאחר זמן מהתשמיש, \u0003מטמאה את בועלה\u0004 טומאת שבעה.","ו\u0003מודים חכמים לר' עקיבא ב\u0004אשה ה\u0003רואה כתם שמטמאה את בועלה\u0004 אם בא עליה לאחר מכן, אף שגם טומאה זו מדברי חכמים.","שנינו במשנה שאם נמצא דם על עד הבדיקה של הבעל לאחר התשמיש, הרי הבעל והאשה טמאים טומאת ודאי. ושואלים: \u0003וניחוש דלמא\u0004 \u0005[ונחשוש שמא]\u0006 \u0003דם מאכולת\u0004 (כינה) \u0003הוא,\u0004 שאפשר היתה כינה בבית הערווה של האשה, ובשעת תשמיש נמעכה, ועבר דמה לאיבר הבעל, ולא תהא זו אלא טומאת ספק! \u0003אמר ר'\u0004 \u0003זירא:\u0004 אין חוששים לכך, משום ש\u0003אותו מקום\u0004 (בית הערווה) של האשה \u0003בדוק הוא אצל\u0004 (לענין) שתימצא בו \u0003מאכולת,\u0004 וברור הוא שלא היתה שם כינה. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בגירסה שונה את דברי ר' זירא: אותו מקום \u0003דחוק\u0004 (צר) \u0003הוא אצל\u0004 (לענין) שתיכנס בו \u0003מאכולת\u0004 ולכן אין לחשוש לכך.","ומבררים: \u0003מאי בינייהו\u0004 \u0005[מה,\u0006 איזה הבדל להלכה יש \u0005ביניהם,\u0006 בין שתי גירסות אלו\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל במקרה \u0003דאשתכח\u0004 \u0005[שנמצאה]\u0006 \u0003מאכולת רצופה\u0004 (מעוכה) על עד הבדיקה של הבעל, ובריחוק מה מהמקום בו נמצא הדם בעד זה. ומעתה, \u0003להך לישנא דאמר\u0004 \u0005[ללשון זו שאמרה]\u0006 שאותו מקום \u0003בדוק הוא\u0004 אצל מאכולת — צריך לומר כי ודאי \u0003הא מעלמא אתאי\u0004 \u0005[\u0006מאכולת \u0005זו מהעולם,\u0006 מהחוץ, \u0005באה],\u0006 ואילו הדם שנמצא על עד הבדיקה של הבעל הוא מן האשה, ולכן טמאים הם טומאת ודאי. ואולם \u0003להך לישנא דאמר\u0004 \u0005[ללשון זו שאמרה]\u0006 שאותו מקום \u0003דחוק הוא\u0004 אצל מאכולת — \u0003אימא\u0004 \u0005[\u0006יש לחשוש \u0005ולומר]\u0006 כי ה\u0003שמש\u0004 (איבר התשמיש של האיש) הוא ש\u0003רצפה\u0004 (מעכה) תוך כדי התשמיש, וממנה בא הדם אל עד הבדיקה של הבעל, והם טמאים רק מספק.","ועוד בענין זה, \u0003אתמר\u0004 \u0005[נאמר]:\u0006 \u0003בדקה\u0004 האשה \u0003בעד הבדוק לה\u0004 שהוא נקי מדם, ולאחר הבדיקה \u0003טחתו\u0004 (דחפתו) \u0003בירכה, ולמחר מצאה עליה,\u0004 על הירך, \u0003דם.\u0004 \u0003אמר רב:\u0004 במקרה כזה הריהי \u0003טמאה\u0004 טומאת \u0003נדה\u0004 ודאית. שכיון שברור שהעד היה נקי מדם קודם הבדיקה, ודאי הדם שנמצא על הירך מן הבדיקה הוא, ועבר אל הירך אחר שהטיחה בו את עד הבדיקה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שימי בר חייא\u0004 לרב: \u0003והא\u0004 \u0005[והרי]\u0006 בדינה של אשה זו \u0003\"חוששת\u0004 לטומאה\" \u0003אמרת לן\u0004 \u0005[לנו],\u0006 והרי שלדעתך אינה טמאה ודאי אלא מספק!","ובענין זה \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 שכך \u0003אמר שמואל:\u0004 אשה זו \u0003טמאה\u0004 טומאת \u0003נדה\u0004 ודאית. \u0003וכן מורין\u0004 הלכה למעשה ב\u0003בי מדרשא\u0004 \u0005[בית המדרש]\u0006 שהאשה \u0003טמאה\u0004 טומאת \u0003נדה\u0004 בוודאי.","ועוד בענין מציאת דם על עד הבדיקה \u0003אתמר\u0004 \u0005[נאמר]:\u0006 \u0003בדקה\u0004 האשה \u0003בעד שאינו בדוק לה,\u0004 שלא בדקה קודם לכן שאין בו דם, \u0003והניחתו בקופסא, ולמחר מצאה עליו\u0004 על העד הזה \u0003דם.\u0004 וספק אם דם זה היה בעד לפני הבדיקה, ואין האשה טמאה, או שדם זה הינו מן הבדיקה והריהי טמאה. ובענין זה \u0003אמר רב יוסף: כל ימיו של ר'\u0004 \u0003חייא טימא\u0004 במקרה שכזה, \u0003ולעת זקנתו טיהר.\u0004","ובדיוק מסורת הלכתית זו של רב יוסף \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לבני בית המדרש\u0005],\u0006 \u0003היכי קאמר\u0004 \u0005[איך\u0006 בדיוק \u0005אמר]\u0006 רב יוסף, האם אמר ש\u0003כל ימיו\u0004 של ר' חייא \u0003טימא משום נדה\u0004 טומאה ודאית ששורפים עליה תרומה, \u0003ולעת זקנתו\u0004 — \u0003טיהר משום\u0004 טומאה ודאית של \u0003נדה,\u0004 \u0003ו\u0004אולם \u0003טימא משום כתם\u0004 שהיא טומאת ספק, והתרומה שנגעה בה אינה נאכלת ואינה נשרפת,","\u0003או דלמא\u0004 \u0005[שמא]\u0006 כך הם דברי רב יוסף: \u0003כל ימיו\u0004 של ר' חייא טימא משום כתם טומאת ספק, \u0003ולעת זקנתו טיהר מולא כלום\u0004 (מכל וכל), והריהי טהורה לגמרי?","ומביאים פתרון לשאלה זו ממה ששנינו בברייתא: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בדקה\u0004 אשה \u0003בעד שאינו בדוק לה והניחתו בקופסא, ולמחר מצאה עליו דם, רבי אומר: טמאה משום נדה\u0004 טומאה ודאית, \u0003ור' חייא אמר: טמאה משום כתם,\u0004 והרי זו טומאת ספק."],["\u0003אמר לו ר' חייא\u0004 לרבי: האם \u0003אי\u0004 (אין) \u0003אתה מודה ש\u0004על מנת להיטמא במקרה זה \u0003צריכה\u0004 היא שתראה על עד הבדיקה שבקופסא דם בשיעור של \u0003כגריס\u0004 של פול \u0003ועוד?\u0004 שבפחות משיעור זה יש לתלות את מקור הדם בכינה שנמעכה. \u0003אמר לו\u0004 רבי: \u0003אבל\u0004 (אכן כן). \u0003אמר לו\u0004 ר' חייא: אם כן, (אתה) \u0003אף אתה עשיתו\u0004 (נוהג בדם זה הנמצא בעד שבקופסה) כ\u0003כתם,\u0004 ואין טומאתו של כתם אלא טומאת ספק. שהרי אם ודאי שמגופה בא הדם די היה בשיעור של כחרדל.","ומעירים: \u0003ורבי\u0004 המטמא את האשה במקרה זה בטומאת ודאי, \u0003סבר\u0004 \u0005[סבור]:\u0006 אמנם \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיעור זה של \u0003כגריס ועוד,\u0004 ואולם זהו רק כדי \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 לשלול\u0005]\u0006 את האפשרות שמא דם זה הוא \u0003מדם מאכולת, וכיון דנפק\u0004 \u0005[שיצא]\u0006 \u0003לה מ\u0004האפשרות ש\u0003דם מאכולת\u0004 הוא — \u0003ודאי מגופה אתא\u0004 \u0005[בא],\u0006 ולכן טמאה בוודאי.","ומעתה נדון בדברי ר' חייא אלו, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003בזקנותו קאי\u0004 \u0005[היה עומד],\u0006 שהרי הוא חולק על רבי שהיה רבו, ובוודאי לא היה חולק עליו אלא כשהיה כבר זקן, ואם בזקנותו, טימא במקרה זה את האשה טומאת ספק, \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003בילדותו\u0004 — \u0003טימא משום נדה\u0004 טומאת ודאי! ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא.","ועוד בענין זה, מסופר כי \u0003משתבח ליה\u0004 \u0005[אומר היה דברי שבח]\u0006 \u0003רבי לר' ישמעאל בר' יוסי\u0004 אודות \u0003ר' חמא בר ביסא\u0004 ש\u0003אדם גדול הוא.\u0004 \u0003אמר לו\u0004 ר' ישמעאל בר' יוסי לרבי: \u0003לכשיבא לידך\u0004 (אליך) \u0003הביאהו לידי\u0004 (אלי).","ומסופר: \u0003כי אתא\u0004 \u0005[כאשר בא],\u0006 ר' חמא בר ביסא אצל ר' ישמעאל בר' יוסי, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ישמעאל בר' יוסי לר' חמא בר ביסא: \u0003בעי מינאי מילתא\u0004 \u0005[שאל ממני,\u0006 אותי \u0005דבר\u0006 בהלכה\u0005].\u0006 \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 ר' חמא בר ביסא: \u0003בדקה\u0004 האשה \u0003בעד שאינו בדוק לה, והניחתו בקופסא, ולמחר מצאה עליו דם, מהו\u0004 הדין בכגון זה?","\u0003אמר לו\u0004 ר' ישמעאל בר' יוסי: כשיטת מי רוצה אתה שאשיבך, האם \u0003כדברי אבא\u0004 (ר' יוסי) \u0003אימא\u0004 \u0005[אומר]\u0006 \u0003לך, או כדברי רבי אימא\u0004 \u0005[אומר]\u0006 \u0003לך? אמר ליה\u0004 \u0005[לו]\u0006 ר' חמא בר ביסא: \u0003כדברי רבי אימא\u0004 \u0005[אמור]\u0006 \u0003לי.\u0004","\u0003אמר ר'\u0004 \u0003ישמעאל: זהו שאומרין עליו\u0004 ש\u0003אדם גדול הוא? היאך מניחין דברי הרב\u0004 שהוא ר' יוסי, \u0003ושומעין דברי התלמיד\u0004 שהוא רבי!","\u0003ו\u0004מסבירים מה טעם נהג כך \u0003ר' חמא בר ביסא,\u0004 משום שהוא \u0003סבר\u0004 \u0005[היה סבור]\u0006 שיש להעדיף את שיטת \u0003רבי,\u0004 שכן \u0003ריש מתיבתא\u0004 \u0005[ראש ישיבה]\u0006 \u0003הוא, ושכיחי רבנן קמיה\u0004 \u0005[ומצויים חכמים לפניו],\u0006 \u0003ו\u0004משום כך \u0003מחדדי שמעתתיה\u0004 \u0005[מחודדות,\u0006 מדוייקות יותר, \u0005שמועותיו]\u0006 משל ר' יוסי, אף שר' יוסי היה רבו.","ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 היא אותה שיטת \u0003רבי ומאי\u0004 \u0005[ומה]\u0006 היא אותה שיטת \u0003ר' יוסי\u0004 שרמזן ר' ישמעאל בר' יוסי בדבריו? \u0003אמר רב אדא בר מתנא, תנא\u0004 \u0005[שנה]:\u0006 במקרה זה, \u0003רבי\u0004 — \u0003מטמא, ור' יוסי\u0004 — \u0003מטהר.\u0004","\u0003ואמר ר'\u0004 \u0003זירא\u0004 בהסבר מחלוקת זו: \u0003כשטימא רבי\u0004 — \u0003כ\u0004שיטת \u0003ר' מאיר\u0004 פסק, \u0003וכשטיהר ר'\u0004 \u0003יוסי\u0004 — \u0003לעצמו\u0004 (כשיטתו שלו) \u0003טיהר.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת נדה\u0005]:\u0006 \u0003האשה שהיתה עושה צרכיה\u0004 (הטילה מים), \u0003וראתה\u0004 עם מי רגליה \u0003דם, ר'\u0004 \u0003מאיר אומר: אם\u0004 הטילה מים כשהיא \u0003עומדת\u0004 — הריהי \u0003טמאה,\u0004 שכן באופן זה, שמטילה היא מימיה במאמץ, אפשר שאגב כך מי הרגלים שבו לאחור אל המקור, וחזרו ויצאו עם הדם. ואולם \u0003אם\u0004 הטילה את מימיה כשהיא \u0003יושבת\u0004 — \u0003טהורה\u0004 היא, שיש לומר שבא הדם מפצע כלשהו, ולא ממקורה.","ואילו ר' יוסי אומר: בין כך ובין \u0003כך,\u0004 בין שהטילה מים כשהיא עומדת ובין כשהיא יושבת — \u0003טהורה.\u0004 הרי שאף כשהיא עומדת יש אולי בא הדם שלא מן המקור, ור' מאיר מטמא משום שמסתבר הדבר שבא הדם מן המקור. ואף רבי מטמא אם נמצא הדם על העד שבקופסה, אף שיש מקום לספק אולי היה הדם בעד הבדיקה קודם שבדקה בו. ואילו ר' יוסי סבור שכל שיש ספק בדבר, אין האשה טמאה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר'\u0004 \u0003יוסי בר' חנינא: כשטימא ר'\u0004 \u0003מאיר\u0004 בנמצא דם במי רגליה, אף שיש מקום לספק, \u0003לא טימא אלא משום כתם,\u0004 שהוא טומאת ספק, \u0003ואילו רבי\u0004 המטמא בנמצא על עד בדיקה שלא היה בדוק קודם לכן, \u0003משום נדה קאמר\u0004 \u0005[הוא אומר],\u0006 שהיא טומאת ודאי, ואין אם כן לתלות את שיטת רבי בשיטת ר' מאיר! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אנן הכי קאמרינן\u0004 \u0005[אנו כך אנו אומרים]:\u0006 \u0003כי איתמר ההיא\u0004 \u0005[כאשר נאמרה אותה]\u0006 הלכה של ר' יוסי בר' חנינא בהסבר שיטת ר' מאיר — \u0003משום נדה איתמר\u0004 \u0005[נאמר]\u0006 שמטמא ר' מאיר טומאת ודאי, ולא משום כתם שהיא טומאת ספק.","שנינו במשנתנו שאם \u0003נמצא\u0004 דם \u0003על\u0004 עד הבדיקה \u0003שלה,\u0004 של האשה, \u0003אותיום\u0004 (מיד) לאחר התשמיש, הרי שניהם, הבעל והאשה \u0003טמאין\u0004 טומאת שבעה וחייבים קרבן חטאת. ובדבר זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו שיעור וסת\u0004 (שהוא שיעור \"אותיום\")? — \u0003משל לשמש\u0004 \u0003ועד שעומדין בצד המשקוף,\u0004 \u0003ביציאת שמש נכנס עד.\u0004 שהוא משל לשמש (אבר הזכר) והעד (עד הבדיקה) שנמצאים בפתח הרחם (\"בצד המשקוף\") כשהאבר נמצא בפנים, ומיד עם הוצאתו האשה מכניסה את העד.","ומגדירים: \u0003הוי\u0004 \u0005[הריהו]\u0006 שיעור \u0003וסת שאמרו\u0004 חכמים שאם תמצא דם על העד ייטמאו שניהם ויתחייבו חטאת, אינו אלא \u0003ל\u0004ענין ה\u0003קינוח\u0004 בעד הבדיקה שלאחר התשמיש, שצריך שייעשה בשיעור זמן זה, כדי לדעת אם היה הדם בשעת התשמיש, \u0003אבל לא\u0004 נאמר שיעור זמן זה \u0003ל\u0004ענין ה\u0003בדיקה\u0004 בפנים, שהרי אם תבדוק עצמה בפנים כראוי, נמצא עובר זמן רב מדי מן התשמיש, ואף אם תמצא דם, אין בכך כדי לטמאם טומאת ודאי.","עוד שנינו במשנתנו שאם \u0003נמצא\u0004 דם \u0003על\u0004 עד הבדיקה \u0003שלה לאחר זמן\u0004 מאז התשמיש, הרי הבעל והאשה טמאים מספק, ופטורים מן הקרבן. ובענין זה \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: פטורים הם מקרבן חטאת, שהחטאת באה על איסור הנעשה בשוגג (שעונשו כרת אם נעשה במזיד) שבוודאי נעשה, ולא על הספק, כעין משנתנו, \u0003ו\u0004אולם \u0003חייבין\u0004 הם בקרבן \u0003אשם תלוי\u0004 הבא על ספק עשיית איסור שעונשו (אם נעשה במזיד) כרת. \u0003ותנא דידן\u0004 \u0005[והתנא שלנו]\u0006 שפטר אותם מקרבן, ובכלל זה אף מקרבן אשם תלוי, \u0003מאי טעמא\u0004 \u0005[מה טעם]?\u0006","— סבור הוא כי כדי לחייב קרבן אשם תלוי על הספק \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיה הספק קיים כעין \u0003חתיכה\u0004 אחת האסורה באכילה באיסור כרת \u0003מ\u0004תוך \u0003שתי חתיכות\u0004 שהאחרת מותרת באכילה, ואכל אחת מהן ואינו יודע איזו אכל, שדווקא בכגון זה חייב קרבן אשם תלוי. ואילו במקרה שבמשנתנו אין הספק אלא כגון חתיכה אחת שספק אם היא מותרת או אסורה, שהרי נמצא הדם על עד הבדיקה שלה, ואין הספק אלא אם נראה הדם לאחר תשמיש (ולא היתה זו בעילת נדה) או לפני התשמיש (ונעשה איסור זה).","עוד שנינו במשנתנו: \u0003איזהו\u0004 שיעור זמן זה המכונה \u0003\"אחר זמן\",\u0004 שדינו שאם נמצא דם בזמן זה על עד הבדיקה שלה, הבעל והאשה טמאים מספק — כדי שתרד האשה מן המיטה ותדיח את בית הערווה. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ששנינו, \u0003איזהו\u0004 שיעור של \"\u0003אחר זמן\"\u0004\u0003? פירש ר' אליעזר בר' צדוק:\u0004 משך זמן \u0003כדי שתושיט\u0004 האשה את \u0003ידה\u0004 אל מ\u0003תחת הכר או\u0004 מתחת \u0003הכסת ותטול עד ותבדוק בו,\u0004 והרי שיעור זה קצר יותר מהזמן הנדרש לרדת מהמיטה ולהדיח את בית הערווה!","\u0003אמר רב חסדא: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחר\u0004 זמן\" האמור במשנתנו — הכוונה לשיעורו של פרק זמן נוסף, שלישי, שהוא \u0003\"אחר\u0004 זמן\" הבא ל\u0003\"אחר\u0004 זמן\" הקודם לו. ששיעורו של פרק הזמן הראשון המכונה \"אחר זמן\" הוא כדברי ר' אליעזר בר' צדוק, ושיעור משנתנו מתייחס לפרק הזמן הבא אחריו, שדינו שאין הדם הנמצא על עד הבדיקה שלה מטמא אותם טומאת שבעה, אלא טומאת ערב בלבד (לשיטת חכמים).","ומקשים על כך: \u0003והא קתני עלה\u0004 \u0005[והרי שנינו עליה,\u0006 על שיעור זמן זה שבמשנתנו\u0005]:\u0006 \u0003נמצא על שלה לאחר זמן\u0004 — \u0003טמאין\u0004 טומאת שבעה \u0003מספק ופטורין מן הקרבן.\u0004 ועל פרק זמן זה נאמר בהמשך המשנה \u0003איזהו \"אחר זמן\"?\u0004 — \u0003כדי שתרד מן המטה ותדיח פניה,\u0004 והרי זה איפוא פרק הזמן הבא מיד לאחר פרק הזמן הנקרא \"אותיום\", ולא פרק זמן שלישי, שאין הבעל נטמא בו אלא טומאת ערב!","ומתרצים: \u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 התנא שבמשנתנו, \u0005אומר,\u0006 זו כוונת דבריו\u0005]:\u0006 \u0003איזהו \"אחר זמן\"\u0004 שאם בדקה באותו זמן הריהם טמאים שבעה? — \u0003כדי שתושיט ידה לתחת הכר או לתחת הכסת ותטול עד ותבדוק בו,\u0004 וכהגדרתו של ר' אליעזר בר' צדוק. \u0003ו\u0004בשיעור זמן שיש בו \u0003כדי שתרד מן המטה ותדיח את פניה\u0004 — \u0003מחלוקת ר'\u0004 \u0003עקיבא וחכמים\u0004 היא אם נטמאים מספק טומאת שבעה, או נטמא הבעל טומאת ערב בלבד.","ושואלים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 במחלוקתם זו של חכמים ור' עקיבא \u0003\"אחר כך\" קתני\u0004 \u0005[שנינו]\u0006 במשנתנו, שנחלקו בנמצא הדם בפרק הזמן הבא לאחר פרק הזמן המכונה \"לאחר זמן\"! ומתרצים: \u0003הכי קאמר\u0004 \u0005[כך הוא\u0006 התנא שבמשנתנו אומר, זו כוונת דבריו\u0005]:\u0006 \u0003וזהו\u0004 שיעור הזמן המכונה \u0003\"אחר כך\" שנחלקו\u0004 בו ר' עקיבא וחכמים.","\u0003רב אשי אמר\u0004 תירוץ אחר לסתירה זו: \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 — \u0003חד שיעורא\u0004 \u0005[שיעור אחד]\u0006 \u0003הוא,\u0004 ותלוי הדבר במצבה של האשה: אם נמצא כבר \u0003עד\u0004 הבדיקה \u0003בידה\u0004 ואינה צריכה להושיט ידה כדי להוציאו מתחת לכר או הכסת — שיעור הזמן הוא כאמור במשנתנו \u0003כדי שתרד מן המטה ותדיח את פניה.\u0004 ואם \u0003אין עד\u0004 הבדיקה \u0003בידה\u0004 — שיעור הזמן הוא \u0003כדי שתושיט ידה לתחת הכר או לתחת הכסת, ותטול\u0004 את \u0003עד\u0004 הבדיקה \u0003ותבדוק בו\u0004 בעודה במיטה.","\u0003מיתיבי\u0004 \u0005[שואלים]\u0006 על תירוצו של רב אשי ממה ששנינו: \u0003איזהו\u0004 שיעור זמן המכונה \u0003\"אחר זמן\"\u0004 שהדם הנמצא על עד הבדיקה שלה מטמא את שניהם טומאת שבעה מספק? — \u0003דבר זה שאל ר'\u0004 \u0003אלעזר בר' צדוק לפני חכמים באושא, ואמר להם:\u0004"],["\u0003שמא כר'\u0004 \u0003עקיבא אתם אומרים, ש\u0004לשיטתו הריהי \u0003מטמאה את בועלה,\u0004 כדרך שהיא מטמאת טהרות שנגעה בהן, למפרע כל מעת לעת? \u0003אמרו לו\u0004 חכמי אושא לר' אלעזר בר' צדוק: כשיטה זו של ר' עקיבא \u0003לא שמענו\u0004 (לא קיבלנוה להלכה) ומעתה רצוננו לדעת מהו שיעור זמן זה.","\u0003אמר להם\u0004 ר' אלעזר בר' צדוק, \u0003כך פרשו חכמים ביבנה:\u0004 כל זמן ש\u0003לא שהתה\u0004 (התעכבה) האשה אחר התשמיש עד שתבדוק עצמה בקינוח משך זמן שיש בו \u0003כדי שתרד מן המטה ותדיח את פניה\u0004 (בית הערוה) — כ\u0003תוך זמן\u0004 נחשב \u0003הוא זה\u0004 (שהוא הזמן המכונה \"אחר זמן\" הבא לאחר הזמן הנקרא \"אותיום\"), \u0003ו\u0004אם נמצא בפרק זמן זה דם על עד הבדיקה שלה — שניהם \u0003טמאין\u0004 טומאת שבעה \u0003מספק, ופטורין מקרבן\u0004 חטאת שאינו בא אלא על חטא הנעשה בשוגג שודאי נעשה, \u0003וחייבין ב\u0004קרבן \u0003אשם תלוי\u0004 הבא על הספק.","ואם \u0003שהתה\u0004 לאחר התשמיש שיעור זמן שיש בו \u0003כדי שתרד מן המטה ותדיח את פניה\u0004 — \u0003אחר הזמן\u0004 של פרק הזמן הנקרא \"אחר זמן\" \u0003הוא זה, ו\u0004דינו של הדם הנמצא על עד הבדיקה שלה בפרק זמן זה, ו","\u0003כן כששהתה מעת לעת ומפקידה לפקידה\u0004 — \u0003בועלה מטמא\u0004 טומאת ערב \u0003משום מגע\u0004 נדה, \u0003ואינו מטמא\u0004 טומאת שבעה \u0003משום בועל\u0004 נדה. \u0003ר' עקיבא אומר: אף מטמא\u0004 טומאת שבעה \u0003משום בועל\u0004 נדה. \u0003ר' יהודה בנו של רבן יוחנן בן זכאי אומר:\u0004 לאחר שיעור זה של \"אחר זמן\" — \u0003בעלה\u0004 אינו נטמא אף לא בטומאת מעת לעת שמדברי חכמים, ואם כהן הוא — רשאי שיהיה \u0003נכנס להיכל ומקטיר קטורת.\u0004","ומעתה יש לשאול: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב חסדא\u0004 הסבור ששיעור \"אחר זמן\" שבועלה טמא בו טומאת שבעה הינו כשיעור עד שתושיט ידה ותבדוק — \u0003היינו דמטהרי רבנן\u0004 \u0005[זהו\u0006 הטעם \u0005שמטהרים חכמים\u0006 בברייתא זו\u0005]\u0006","\u0005לאחר פרק זמן זה,\u0006 \u0003אלא ל\u0004שיטת \u0003רב אשי\u0004 הסבור שאם כבר יש עד בדיקה בידה, הריהי מטמאה את בעלה בשיעור של עד שתרד מן המיטה ותדיח את פניה — \u0003אמאי מטהרי רבנן\u0004 \u0005[מדוע מטהרים חכמים]\u0006 את בעלה לאחר שחלף זמן זה של עד שתושיט ידה ותבדוק, והרי לשיטתו פרק הזמן שבו היא מטמאה את בעלה נמשך עד שתרד מן המיטה ותדיח?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהברייתא עוסקת כאשר \u0003אין\u0004 \u0003העד בידה,\u0004 ומשום כך שיעור הזמן הנזכר בה הוא עד שתושיט ידה ותבדוק, אין לומר כן, שהרי אם כך כוונתו, \u0003האי\u0004 \u0005[זה]\u0006 הלשון \u0003\"עד בידה\" ו\"אין עד בידה\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לתנא שבברייתא לחלק ולומר! ומסכמים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הברייתא על שיטת רב אשי.","שנינו בברייתא ש\u0003ר' יהודה בנו של רבן יוחנן בן זכאי\u0004 היה \u0003אומר\u0004 כי לאחר \"אחר זמן\" אין \u0003בעלה\u0004 נטמא כלל, ואם רוצה הריהו אף \u0003נכנס להיכל ומקטיר קטורת.\u0004 ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו\u0006 הלכה\u0005]\u0006 שהוא טמא משום \u0003דהוה\u0004 \u0005[שהריהו]\u0006 \u0003נוגע במעת לעת שבנדה,\u0004 שכן גזרו חכמים טומאה למפרע בטהרות שנגעה בהן!","ומתרצים: \u0003הוא,\u0004 ר' יהודה בנו של רבן יוחנן בן זכאי ש\u0003אמר\u0004 כן, סבור \u0003כשמאי\u0004 ש\u0003אמר\u0004 כי לא גזרו חכמים טומאת מעת לעת, אלא \u0003כל הנשים דיין שעתן\u0004 לטומאה.","ושואלים עוד על דברי ר' יהודה בנו של רבן יוחנן בן זכאי: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו\u0006 הלכה\u0005]\u0006 שבעלה טמא משום \u0003דהוה\u0004 \u0005[שהריהו]\u0006 \u0003בעל קרי!\u0004 ומתרצים: מדובר כאן \u0003ב\u0004מקרה \u0003שלא גמר\u0004 הבועל את \u0003ביאתו.\u0004","עוד שנינו במשנתנו: \u0003ומודים חכמים לר' עקיבא ברואה כתם\u0004 שמטמאה את בועלה. ובענין זה נחלקו אמוראים, ש\u0003אמר רב\u0004 שמטמאה את בועלה \u0003למפרע, ו\u0004כשיטת \u0003ר' מאיר היא\u0004 הסבור שהרואה כתם מטמאת טהרות למפרע (לעיל ה,א).","\u0003ו\u0004אילו \u0003שמואל אמר\u0004 שאינה מטמאת את בועלה למפרע, אלא רק אם יבוא עליה \u0003מכאן ולהבא\u0004 (לאחר ראיית הכתם), \u0003ו\u0004כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא\u0004 הסבורים שראיית כתם מטמאת רק מכאן ולהבא. ושואלים על דברי שמואל: מדוע הוא אומר שמטמאת את בועלה \u0003מכאן ולהבא,\u0004 והרי \u0003פשיטא\u0004 \u0005פשוט]\u0006 הוא הדבר!","ומשיבים: יש צורך לומר את הדברים, שהרי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הואיל ו\u0004כל עיקרה של טומאת \u0003מעת לעת\u0004 למפרע הריהי גזירה מ\u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003ו\u0004אף טומאת \u0003כתמים\u0004 הריהי גזירה מ\u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 ומעתה אפשר לומר: \u0003מה\u0004 בטומאת \u0003מעת לעת\u0004 — \u0003לא מטמאה את בועלה, אף\u0004 בטומאת \u0003כתמים\u0004 — \u0003לא מטמאה את בועלה,\u0004 ואף לא מכאן ולהבא. לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 שמואל \u0005משמיע לנו]\u0006 שמטמאת את בועלה מכאן ולהבא.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור\u0006 שאכן \u0005כך\u0006 הוא \u0005גם כן]!,\u0006 שלא תטמא אף מכאן ולהבא! ומתרצים: יש הבדל, שכן \u0003התם שם,\u0004 בטומאת מעת לעת\u0005]\u0006 — \u0003אין \"שור שחוט לפניך\"\u0004 (הוכחה לפניך), שהרי לא ראתה אלא עתה. ולכך אין טומאת מעת לעת אלא כחומרה שהחמירו חכמים לענין טהרות, ואין בה כדי להחמיר אף לענין בועלה. ולעומת זאת, \u0003הכא\u0004 \u0005[כאן,\u0006 בטומאת כתמים\u0005]\u0006 — הרי \u0003יש \"שור שחוט לפניך\",\u0004 שהרי ראתה דם.","ומציינים: \u0003וכן\u0004 כמחלוקת זו בין רב ושמואל בפירוש דברי המשנה, נחלקו ריש לקיש ור' יוחנן. שכך \u0003אמר ריש לקיש\u0004 כי הרואה כתם מטמאה את בועלה \u0003למפרע, ו\u0004כשיטת \u0003ר' מאיר היא.\u0004 ואילו \u0003ר' יוחנן אמר\u0004 שהרואה כתם מטמאת את בועלה רק \u0003מכאן ולהבא, ו\u0004כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא.\u0004","כלל הוא: \u0003כל הנשים\u0004 הן \u0003בחזקת טהרה\u0004 מטומאת הנדה, ומותרות בתשמיש \u0003לבעליהן,\u0004 ואין הבעל צריך לברר קודם תשמיש אם טהורה היא. ואף הבעלים \u0003הבאין מן הדרך,\u0004 שלא היו בביתם קודם לכן, אם כשיצאו לדרך היו נשותיהם טהורות — \u0003נשיהן להן\u0004 עתה בחזקת טהרה. שנינו במשנתנו שכל הנשים הינן בחזקת טהרה לבעליהן, ובכלל זה אף לבעלים הבאים מן הדרך. ושואלים: \u0003למה\u0004","\u0003ליה למתני\u0004 \u0005[למה לו\u0006 לתנא \u0005לשנות]\u0006 דין מיוחד לאלו \u0003הבאין מן הדרך,\u0004 במה הם שונים משאר הבעלים? ומסבירים: \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שיש חזקת טהרה לנשים לענין תשמיש אמורים דווקא \u0003היכא דאיתיה במתא\u0004 \u0005[היכן,\u0006 במקרה, \u0005שנמצא\u0006 הבעל \u0005בעיר,\u0006 במקום מגוריו\u0005],\u0006 משום שאז \u0003רמיא אנפשה\u0004 \u0005[מטילה\u0006 האשה \u0005על עצמה]\u0006 להיות טהורה לבעלה בכל עת, \u0003ובדקה\u0004 \u0005[ו\u0006משום כך היא \u0005בודקת]\u0006 את עצמה. \u0003אבל היכא דליתא במתא\u0004 \u0005[היכן,\u0006 במקרה, \u0005שלא נמצא\u0006 הבעל \u0005בעיר\u0006 מגוריו\u0005], דלא רמיא אנפשה\u0006 \u0005[שאין\u0006 האשה \u0005מטילה על עצמה]\u0006 חובה זו — \u0003לא\u0004 תהא מוחזקת כטהורה, לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 התנא במשנתנו שאף במקרה זה יש חזקת טהרה לנשים אצל בעליהן. ובענין זה \u0003אמר\u0004","\u0003ריש לקיש משום\u0004 (בשם) \u0003ר' יהודה נשיאה\u0004 (הנשיא): \u0003ו\u0004מה שמותרת אשה לבעלה הבא מן הדרך על סמך חזקת טהרתה \u0003הוא\u0004 דווקא בזמן \u0003שבא\u0004 הבעל \u0003ומצאה\u0004 לאשתו כשהיא \u0003בתוך ימי עונתה\u0004 (בתוך שלושים יום מראייתה הקודמת), שיכול להניח שעדיין לא ראתה וסומך על חזקת טהרתה, אבל אם בא לאחר עונתה סביר להניח שכבר ראתה דם בעונתה ואינה מותרת לו, אלא אם כן בדקה עצמה ונמצאה טהורה.","ובענין חזקת הטהרה של הנשים אצל בעליהן, \u0003אמר רב הונא: לא שנו\u0004 חכמים דין זה \u0003אלא\u0004 רק באשה \u0003שאין לה וסת\u0004 קבוע. \u0003אבל\u0004 אשה ש\u0003יש לה וסת\u0004 קבוע — \u0003אסור\u0004 הבעל \u0003לשמש\u0004 עימה.","ותמהים על כך: \u0003כלפי לייא\u0004 \u0005[לאן\u0006 הדברים \u0005נוטים],\u0006 שהרי \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003איפכא מסתברא\u0004 \u0005[ההיפך\u0006 מכך \u0005מסתבר],\u0006 שכן בזמן ש\u0003אין לה וסת\u0004 — \u0003אימא: חזאי\u0004 \u0005[אמור: ראתה]\u0006 ויש מקום לחשוש שטמאה היא, ובזמן ש\u0003יש לה וסת\u0004 — \u0003וסת קביע\u0004 \u0005[קבועה]\u0006 \u0003לה\u0004 ויודע מתי!","\u0003אלא\u0004 כך יש לומר: \u0003אי איתמר\u0004 \u0005[אם נאמרו]\u0006 הדברים, \u0003הכי איתמר\u0004 \u0005[כך נאמרו],\u0006 \u0003אמר רב הונא: לא שנו\u0004 הלכה זו של חזקת טהרה לנשים (שיש להן וסת קבוע) אצל בעליהן \u0003אלא\u0004 בזמן \u0003שלא הגיע שעת וסתה\u0004 קודם חזרתו מהדרך, \u0003אבל\u0004 אם \u0003הגיע שעת וסתה\u0004 — \u0003אסורה.\u0004 וטעמו משום ש\u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003וסתות\u0004 (חיוב הבדיקה בשעת הוסת) הריהו \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 שהוא הלכה למשה מסיני, ומשום כך כיון שהגיע זמן וסתה, אף אם לא הרגישה שיצא ממנה דם, הרי היא בחזקת טומאה אם לא בדקה עצמה ומצאה טהורה. ואין הבעל הבא מן הדרך יכול לסמוך על כך שבדקה אשתו בשעת וסתה, בלא שיברר אצלה תחילה אם בדקה עצמה ונמצאה טהורה.","ואילו \u0003רבה בר בר חנה אמר: אפילו\u0004 אם \u0003הגיע שעת וסתה\u0004 קודם חזרתו מהדרך — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מותרת\u0004 האשה לבעלה, וטעמו: משום ש\u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003וסתות\u0004 הריהו מ\u0003דרבנן\u0004 \u0005[דברי חכמים],\u0006 שמדין תורה אף אם הגיע זמן וסתה, הריהי בחזקת טהורה, אם לא הרגישה, אף שלא בדקה עצמה. ומשום שאין חובה זו אלא מדברי חכמים, אין אנו מעמידים אותה בספק טמאה.","ומביאים עוד, כי \u0003רב אשי\u0004 הסביר את דברי משנתנו האומרת שכל הנשים הריהן בחזקת טהרה לבעליהן, אף לאחר שהגיע זמן וסתן, ו\u0003מתני הכי\u0004 \u0005[היה שונה כך]\u0006 את שיטות רב הונא ורבה בר בר חנה. שכך לדעתו \u0003אמר רב הונא:\u0004"],["\u0003לא שנו\u0004 שכל אשה בחזקת טהורה לבעלה \u0003אלא\u0004 בזו \u0003שאין לה וסת לימים\u0004 בלבד, \u0003אלא יש לה וסת\u0004 גם לימים קבועים \u0003ו\u0004גם לקפיצות (פעולות גופניות שעושה, כקפיצה). \u0003כיון\u0004 שגם \u0003במעשה\u0004 מסויים \u0003תליא מילתא\u0004 \u0005[תלוי הדבר]\u0006 אם תראה — \u0003אימא\u0004 \u0005[אמור,\u0006 יש מקום לומר\u0005]\u0006 ש\u0003לא קפיץ\u0004 \u0005[לא קפצה],\u0006 \u0003ו\u0004לכך גם \u0003לא חזאי\u0004 \u0005[ראתה].\u0006 ומשום כך הריהי בחזקת טהורה לבעלה. \u0003אבל\u0004 באשה ש\u0003יש לה וסת לימים\u0004 בלבד, והגיע יום וסתה — \u0003אסורה לשמש.\u0004","וטעמו, שכן \u0003קסבר\u0004 \u0005[סבור הוא\u0006 רב הונא\u0005]\u0006 כי דין \u0003וסתות\u0004 הריהו \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ומעתה, כשהגיע יום וסתה הריהי בחזקת טמאה מספק מדין תורה, ולכך אינה מותרת לבעלה בלא בירור הבעל אם בדקה עצמה.","ואילו \u0003רבה בר בר חנה אמר\u0004 כי \u0003אפילו\u0004 אשה ש\u0003יש לה וסת לימים\u0004 בלבד \u0003מותרת\u0004 לבעלה בלא שאלה. שכן \u0003קסבר\u0004 \u0005[סבור הוא,\u0006 רבה בר בר חנה\u0005]\u0006 כי דין \u0003וסתות\u0004 הריהו \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 שחכמים הם שתיקנו בדיקה ביום הוסת, ועדיין היא בחזקת טהורה לבעלה ביום זה, ומותרת אף בלא ששאלה.","ועוד בענין זה, \u0003אמר רב שמואל משמיה\u0004 \u0005[בשמו]\u0006 של \u0003ר' יוחנן: אשה שיש לה וסת,\u0004 ובעלה שהה בדרך שבעה ימים לאחר יום וסתה, ושב לביתו — \u0003בעלה מחשב ימי וסתה,\u0004 וכיון שיש מקום לומר שטבלה ונטהרה מטומאתה, \u0003ובא עליה\u0004 אף שלא שאל אם נטהרה.","ובבירורה של הלכה זו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמואל בר ייבא לר' אבא\u0004 בשאלה: האם \u0003אמר ר'\u0004 \u0003יוחנן\u0004 את ההלכה הזו \u0003אפילו\u0004 במי שהיא \u0003ילדה\u0004 (קטנה) \u0003דבזיזא למטבל\u0004 \u0005[שבושה לטבול],\u0006 ומעתה יש לומר שכיון שבעלה לא היה בעיר, לא טבלה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא לרב שמואל בר ייבא בתשובה: \u0003אטו\u0004 \u0005[וכי]\u0006 גם בזו ש\u0003ודאי ראתה מי\u0004 \u0005[האם]\u0006 \u0003אמר ר'\u0004 \u0003יוחנן\u0004 שהיא מותרת?! \u0003אימר\u0004 \u0005[אמור]\u0006 שלא \u0003אמר ר'\u0004 \u0003יוחנן\u0004 להתיר אלא את האשה ש\u0003ספק ראתה ספק לא ראתה, ו\u0004באשה שכזו אומרים אנו שאף \u0003אם תמצא\u0004 (תרצה) \u0003לומר\u0004 ש\u0003ראתה\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003טבלה\u0004 אחר כך.","\u0003אבל\u0004 באשה ש\u0003ודאי ראתה\u0004 — \u0003מי יימר\u0004 \u0005[יאמר]\u0006 שר' יוחנן מתירה בלא בירור שהניח ש\u0003טבלה? הוה ליה\u0004 \u0005[הרי הוא]\u0006 מצב של \u0003ספק\u0004 (אם טבלה) \u0003וודאי\u0004 (שראתה), \u0003ו\u0004כלל הוא ש\u0003אין ספק מוציא מידי ודאי.\u0004 ומעתה, אף בעניינה של ילדה, הרי זה ספק ראתה וספק שמא טבלה, ולכך אף היא מותרת לבעלה.","ותוהים: \u0003ו\u0004האם \u0003לא\u0004 כך הוא, שספק מעין זה הריהו מוציא מידי ודאי? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בדינו של מי שהיה \u0003חבר\u0004 (שמוחזק כמקפיד על הפרשת תרומותיו ומעשרותיו) \u0003שמת, והניח\u0004 אחריו ליורשיו \u0003מגורה\u0004 (ממגורה, מחסן) \u0003מלאה פירות, אפילו\u0004 הפירות הללו \u0003הן בני יומן\u0004 (שהובאו למגורה באותו יום שנפטר בו החבר) — \u0003הרי הן בחזקת מתוקנין\u0004 (מעושרים כדינם, ומותרים באכילה), שמן הסתם עישר אותם החבר. ומעתה יש לברר: \u0003והא הכא\u0004 \u0005[והרי כאן,\u0006 בפירות המגורה\u0005]\u0006 מדובר בפירות שהיו \u0003ודאי טבל\u0004 בשעה שהובאו אל המגורה, ואילו עתה הם בגדר \u0003ספק מעושר ספק אינו מעושר, ו\u0004בכל זאת, \u0003קאתי\u0004 \u0005[בא]\u0006 ה\u0003ספק ומוציא מידי ודאי!\u0004","ומשיבים: \u0003התם\u0004 \u0005[שם,\u0006 בפירות המגורה\u0005]\u0006 אין זה מקרה של ודאי (טבל) וספק (מעושר), אלא \u0003ודאי וודאי הוא\u0004 — \u0003כ\u0004דברי רב חנינא חוזאה, שכן \u0003אמר רב חנינא חוזאה:\u0004 \u0003חזקה על חבר שאינו מוציא מתחת ידו דבר שאינו מתוקן\u0004 (לענין תרומות ומעשרות), ולכך ודאי הפריש תרומות ומעשרות.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תשובה אחרת: מקרה זה \u0003ספק וספק הוא,\u0004 שאף פירות המגורה מעיקרם הריהם ספק טבל. \u0003וכ\u0004שיטת \u0003ר' אושעיא\u0004 היא. שכן \u0003אמר ר'\u0004 \u0003אושעיא: מערים אדם על תבואתו\u0004 שלא לחייבה בתרומות ומעשרות, \u0003ומכניסה\u0004 למגורה בעוד התבואה \u0003במוץ שלה\u0004 (שלא הושלמה בדישה ובמירוח ערימת התבואה), \u0003כדי שתהא בהמתו אוכלת\u0004 מתבואה זו, \u0003ופטורה מן המעשר.\u0004 שכל עוד לא נגמרה מלאכת התבואה, לא נתחייבה בתרומות ומעשרות, והיא מותרת למאכל בהמה בלי עישור. ויתכן איפוא שמתחילה לא חל חיוב תרומה על התבואה, וכיון שהוא ספק — בא ספק ומוציא מידי ספק.","ושואלים עוד: \u0003ואכתי\u0004 \u0005ועדיין]\u0006 כך הוא ש\u0003אין ספק מוציא מידי ודאי? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מעשה בשפחתו של מסיק אחד ב\u0004מקום הנקרא \u0003רימון, שהטילה נפל\u0004 (ולד מת) \u0003לבור.\u0004 \u0003ובא כהן והציץ בו\u0004 בבור, שרצה \u0003לידע אם\u0004 נפל זה \u0003זכר אם נקבה\u0004 הוא, שכן יש הבדל בין לידת זכר ללידת נקבה לענין דיני טומאה וטהרה של היולדת. אלא שיש חשש שמא היה הנפל בבור, ואולי נטמא הכהן בטומאת מת מפני שהאהיל עליו.","\u0003בא מעשה\u0004 זה לפני חכמים, וטהרוהו. והטעם שטיהרוהו: \u0003מפני שחולדה וברדלס מצויים שם,\u0004 ובודאי אכלוהו או גררוהו משם.","ומעתה יש לברר: \u0003והא הכא\u0004 \u0005[והרי כאן,\u0006 במקרה זה של נפל\u0005]\u0006 \u0003ודאי הטילה נפל,\u0004 ומצד אחר הרי זה \u0003ספק\u0004 שמא \u0003גררוהו\u0004 חיות, \u0003ספק\u0004 שמא \u0003לא גררוהו, וקאתי\u0004 \u0005[ובא]\u0006 ה\u0003ספק ומוציא מידי ודאי!\u0004","ומתרצים: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 בדברי הברייתא שאותה שפחה \u0003\"הטילה נפל\u0004 ודאי \u0003לבור\", אלא אימא\u0004 \u0005[אמור]\u0006"],["\"שהטילה \u0003כמין נפל\u0004 לבור\", ויש איפוא ספק אם היתה שם טומאה.","ומקשים על תירוץ זה: כיצד אפשר לפרש כך, \u0003והא\u0004 \u0005[והרי]\u0006 \"ובא כהן והציץ בו \u0003לידע אם זכר אם נקבה\" קתני\u0004 \u0005[שנה]\u0006 בברייתא. משמע שברור כי היה זה נפל!","ומתרצים: \u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 התנא שבברייתא, \u0005אמר]:\u0006 \u0003ובא כהן והציץ בו\u0004 כדי \u0003לידע\u0004 בתחילה \u0003אם נפל הפילה אם רוח\u0004 (דבר שאינו בגדר ולד) \u0003הפילה, ו\u0004אף \u0003אם תמצי\u0004 \u0005[תמצא,\u0006 תרצה] \u0003לומר\u0004 ש\u0003נפל הפילה\u0004 — יש מקום \u0003לידע אם זכר\u0004 הוא \u0003אם נקבה\u0004 היא.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: אין מקרה זה של נפל נחשב כודאי וספק, אלא ודאי ודאי, שכן \u0003כיון\u0004 ש\u0003חולדה וברדלס\u0004 ודאי \u0003מצויים שם\u0004 בבור — \u0003ודאי גררוהו\u0004 משם.","ועוד בענין הוסתות, \u0003בעו מיניה\u0004 \u0005[שאלו\u0006 התלמידים \u0005ממנו]\u0006 \u0003מרב נחמן:\u0004 דין \u0003וסתות\u0004 שצריכה אשה בדיקה בשעת וסתה, האם הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ולכך אם לא בדקה — הריהי טמאה, ואפילו בדקה לאחר מכן, ולא מצאה דם. שכן יש מקום לומר שהיתה יציאת דם, ונפל הדם לקרקע. \u0003או\u0004 שמא מן התורה די בכך שלא ראתה דם בשעת וסתה, ולא הרגישה ביציאת דם ממנה, ודין זה של חובת בדיקה הריהו מ\u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 ולכך אם לא בדקה — הריהי טהורה.","\u0003אמר להו\u0004 \u0005[להם]\u0006 רב נחמן: יש פתרון לשאלתכם \u0003מ\u0004מה ש\u0003אמר הונא חברין\u0004 \u0005[חברנו]\u0006 \u0003משמיה\u0004 \u0005[בשמו]\u0006 של \u0003רב\u0004 בדינה של \u0003אשה שיש לה וסת\u0004 קבוע, \u0003והגיע שעת וסתה ולא בדקה, ולבסוף\u0004 (לאחר מכן, בבדיקה ראשונה שבדקה) \u0003ראתה\u0004 שיצא ממנה דם והיא טמאה — הריהי \u0003חוששת\u0004 (מחמירה לטמא טהרות שעסקה בהן) למפרע \u0003ל\u0004מן שעת \u0003וסתה,\u0004 ואף שעבר זמן רב מאז. \u0003ו\u0004כן היא \u0003חוששת\u0004 (מחמירה לטמא טהרות שעסקה בהן) למפרע מעת לעת, \u0003ל\u0004מן שעת \u0003ראייתה,\u0004 ואף אם ראתה זמן קצר לאחר שעת וסתה. \u0003אלמא\u0004 \u0005[\u0006יש \u0005להסיק]\u0006 מכאן כי דין \u0003וסתות דאורייתא\u0004 \u0005[מן התורה]\u0006 הוא, ולכך מחמירים בה לטמא משעת וסתה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003הכי קאמר להו\u0004 \u0005[כך הוא,\u0006 רב נחמן, \u0005אמר להם]:\u0006 מהלכה זו של רב נדייק: \u0003טעמא\u0004 \u0005[טעם]\u0006 הלכה זו, שמטמאים אנו את הטהרות שעסקה בהן למפרע משעת וסתה הוא משום שלבסוף \u0003ראתה,\u0004 ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 אם לא ראתה לבסוף — \u0003אין חוששין\u0004 בה לטמא את הטהרות למפרע משעת וסתה, אף שלא בדקה בשעת וסתה. \u0003אלמא\u0004 \u0005[\u0006יש \u0005להסיק]\u0006 מכאן כי דין \u0003וסתות\u0004 הריהו מ\u0003דרבנן\u0004 \u0005[מדברי חכמים].\u0006","מתוך שהובאו למעלה דברי רב, מובאת מחלוקתם של רב ושמואל באותה הלכה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 בדינה של \u0003אשה שיש לה וסת\u0004 קבוע, \u0003והגיע שעת וסתה ולא בדקה, ולבסוף\u0004 (לאחר זמן) \u0003בדקה,\u0004 נחלקו בדבר חכמים. ש\u0003אמר רב:\u0004 אם לאחר מכן \u0003בדקה ומצאת\u0004 שהיא \u0003טמאה\u0004 — הריהי \u0003טמאה,\u0004 ואם כשבדקה לאחר מכן מצאה עצמה שהיא \u0003טהורה\u0004 — הריהי \u0003טהורה.\u0004 \u0003ו\u0004אילו \u0003שמואל אמר:\u0004 \u0003אפילו בדקה\u0004 לאחר מכן \u0003ומצאת\u0004 (מצאה עצמה) שהיא \u0003טהורה\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003טמאה.\u0004 וטעם הדבר: \u0003מפני שאורח\u0004 (דרך נשים להופעת הדם) \u0003בזמנו בא.\u0004","ומציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003ב\u0004דין \u0003וסתות קמיפלגי\u0004 \u0005[הם חולקים],\u0006 \u0003דמר\u0004 \u0005[שחכם זה,\u0006 שמואל\u0005]\u0006 האומר שטמאה בכל מקרה, \u0003סבר\u0004 \u0005[סבור]\u0006 שדין וסתות הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ו\u0004אילו \u0003מר\u0004 \u0005[חכם זה,\u0006 רב\u0005]\u0006 האומר שאם בדקה לבסוף ומצאה שהיא טהורה — טהורה היא, \u0003סבר\u0004 \u0005[סבור]\u0006 שדין וסתות הוא מ\u0003דרבנן\u0004 \u0005[מדברי סופרים]!\u0006","\u0003אמר ר'\u0004 \u0003זירא:\u0004 אפשר לומר כי \u0003דכולי עלמא\u0004 \u0005[\u0006לדעת \u0005הכל],\u0006 ואף לדעת רב, דין \u0003וסתות\u0004 הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ולכך סבור רב שאם לא בדקה עצמה בשעת הוסת — הריהי טמאה. והטעם שבמקרה זה רב מטהר אותה משום ש\u0003כאן\u0004 מדובר כ\u0003שבדקה עצמה כשיעור וסת,\u0004 שהוא שיעור זמן סמוך לשעת הוסת, ויש לומר שאילו היה בה דם בשעת הוסת, היתה רואה אותו בשעת בדיקה זו. ואילו \u0003כאן,\u0004 בשאר מקרים שבדקה עצמה לאחר מכן — מדובר כ\u0003שלא בדקה עצמה\u0004 \u0003כשיעור וסת.\u0004","\u0003ואילו\u0004 \u0003רב נחמן בר יצחק אמר\u0004 בהסבר מחלוקתם זו של רב ושמואל כי \u0003ב\u0004דין \u0003וסתות גופייהו קמיפלגי\u0004 \u0005[עצמן הם חולקים],\u0006 ש\u0003מר\u0004 \u0005[חכם זה,\u0006 שמואל\u0005]\u0006 \u0003סבר\u0004 \u0005[סבור]\u0006 כי דין \u0003וסתות\u0004 הריהו \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003ו\u0004אילו \u0003מר\u0004 \u0005[וחכם זה,\u0006 רב\u0005]\u0006 \u0003סבר\u0004 \u0005[סבור]\u0006 כי דין \u0003וסתות\u0004 הריהו \u0003דרבנן\u0004 \u0005[מדברי חכמים].\u0006","ועוד בענין המחלוקת שבין רב ושמואל בדין וסתות, \u0003אמר רב ששת:\u0004 חלוקים רב ושמואל בדבר זה, \u0003כ\u0004דרך שחלקו כבר \u0003תנאי\u0004 \u0005[תנאים]\u0006 בו, שכך שנינו בדינה של אשה שיש לה וסת קבוע והגיע וסתה ולא בדקה, ש\u0003ר' אליעזר אומר\u0004 כי היא \u0003טמאה נדה,\u0004 ומכאן שלדעתו דין וסתות הוא מן התורה.","\u0003ו\u0004אילו \u0003ר' יהושע אומר\u0004 ש\u0003תבדק\u0004 עתה, לאחר זמן, ואם בבדיקה זו היא תימצא טהורה — הריהי אכן טהורה אף למפרע. ומכאן שלדעתו דין וסתות הוא מדברי חכמים. \u0003ו\u0004מוסיפים: אף \u0003הני תנאי\u0004 \u0005[אלה התנאים,\u0006 ר' אליעזר ור' יהושע\u0005]\u0006 חלוקים בדבר זה \u0003כי הני תנאי\u0004 \u0005[כמו אלה התנאים,\u0006 שיוזכרו להלן\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדינה של מי שהגיע זמן וסתה ולא בדקה עצמה, ש\u0003ר' מאיר אומר\u0004 שהיא \u0003טמאה נדה,\u0004 הרי שלדעתו דין וסתות הוא מן התורה. \u0003ו\u0004אילו \u0003חכמים אומרים\u0004 כי \u0003תבדק\u0004 עתה, ואם בבדיקה תימצא טהורה — הריהי טהורה אף למפרע. הרי שלדעתם דין וסתות הוא מדברי חכמים.","ועוד בדבר זה \u0003אמר אביי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 שכך היא שיטת ר' מאיר בדין הוסתות, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכתנו\u0005],\u0006 \u0003ר' מאיר אומר: אם היתה\u0004 האשה נמצאת \u0003במחבא\u0004 מפני סכנה, \u0003והגיע שעת וסתה ולא בדקה\u0004 עצמה ביום וסתה — הריהי \u0003טהורה,\u0004 וטעם הדבר: מפני \u0003ש\u0004ה\u0003חרדה מסלקת את הדמים,\u0004 ואין לחשוש שמא יצא ממנה דם ביום וסתה, ולא הרגישה בכך. ויש לדייק: \u0003טעמא\u0004 \u0005[הטעם\u0006 דווקא\u0005]\u0006 משום \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003חרדה\u0004 בהיותה במחבא, ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 אם ביום וסתה \u0003ליכא\u0004 \u0005[אין]\u0006 \u0003חרדה\u0004 לאשה זו — הריהי \u0003טמאה.\u0004 \u0003אלמא\u0004 \u0005[מכאן\u0006 נסיק] שלדעת ר' מאיר דין \u0003וסתות דאורייתא\u0004 \u0005[מן התורה].\u0006","ומציעים עוד בשיטותיהם של חכמים החלוקים בדין הוסתות: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003הני תנאי\u0004 \u0005[אלה התנאים,\u0006 שיוזכרו להלן\u0005],\u0006 \u0003בהא\u0004 \u0005[בזה,\u0006 בדין וסתות\u0005]\u0006 \u0003נמי פליגי\u0004 \u0005[גם כן חולקים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 בדינה של אשה \u0003הרואה דם מחמת מכה\u0004 (פצע) הנמצא במקום המקור — \u0003אפילו\u0004 ראתה \u0003בתוך ימי נדתה\u0004 (בעונת הנדה או בשעת וסתה), הריהי \u0003טהורה,\u0004 שכן תולים אנו דם זה כבא מן הפצע ולא מן המקור. אלו \u0003דברי רבן שמעון בן גמליאל.\u0004","ואילו \u0003רבי אומר\u0004 כי באשה שאין לה וסת קבוע — אומרים שיש לתלות את הדם במכה. ואולם \u0003אם יש לה וסת\u0004 קבוע, וראתה דם ביום הוסת, ואפילו היה הדם מחמת הפצע שבאותו המקום — הריהי \u0003חוששת לוסתה,\u0004 שמא טיפת דם מהמקור מעורבת בדם זה.","\u0003מאי לאו, בהא קמיפלגי\u0004 \u0005[האם לא, בזה הם חלוקים],\u0006 ש\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רבי \u0005סבור]\u0006 שדין \u0003וסתות\u0004 הריהו \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ולכך יש להחמיר במי שיש לה וסת קבוע. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רבן שמעון בן גמליאל \u0005סבור]\u0006 כי דין \u0003וסתות\u0004 הריהו \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 ולכך מקילים אנו בה, ומטהרים בכגון זה אף את זו שיש לה וסת קבוע.","\u0003אמר רבינא: לא,\u0004 אין זה בהכרח שחלוקים הם בדין זה, שכן יש מקום לומר כי \u0003דכולי עלמא\u0004 \u0005[\u0006לדעת \u0005כולם,\u0006 ואף לדעת רבי\u0005]\u0006 דין \u0003וסתות\u0004 הוא \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 — \u0003ב\u0004שאלה אם ה\u0003מקור מקומו טמא,\u0004 וכל דם שעבר בו, אף שהוא דם מכה טמא, \u0003קמיפלגי\u0004 \u0005[הם חולקים].\u0006","ש\u0003רבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]\u0006 כי ה\u0003אשה\u0004 עצמה \u0003טהורה\u0004 מטומאת נדה. ודין וסתות הוא מדברי חכמים. \u0003ו\u0004אולם ה\u0003דם\u0004 — הריהו \u0003טמא,\u0004 כיון \u0003דקאתי\u0004 \u0005[שהוא בא]\u0006 \u0003דרך\u0004 ה\u0003מקור,\u0004 ונטמא בו, והריהו איפוא מטמא את האשה בטומאת ערב (כשאר אבות הטומאה), אך לא טומאת שבעת ימים (כנדה).","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי: אי חיישת\u0004 \u0005[אם חושש אתה]\u0006 \u0003ל\u0004יום ה\u0003וסת,\u0004 משום שסבור אתה כי דין וסתות הוא מן התורה — ה\u0003אשה נמי\u0004 \u0005[גם כן]\u0006 הריהי \u0003טמאה, ואי לא חיישת\u0004 \u0005[ואם אין אתה חושש]\u0006 \u0003ל\u0004יום ה\u0003וסת,\u0004 משום שסבור אתה כי דין וסתות הוא מדברי חכמים — אף ה\u0003מקור\u0004 אינו מטמא את הדם הנמצא ב\u0003מקומו,\u0004 ו\u0003טהור הוא.\u0004","\u0003בית שמאי אומרים: צריכה\u0004 האשה \u0003שני עדים\u0004 (אמצעי בדיקה) \u0003על כל תשמיש ותשמיש\u0004 שהיא משמשת עם בעלה באותו הלילה, אחד לפני התשמיש ואחד לאחריו. ולמחרת, לאור היום, תבדוק את שני העדים הללו. \u0003או\u0004 שלאחר ש\u0003תשמש\u0004 תבדוק את עד הבדיקה \u0003לאור הנר,\u0004 ותוכל לשוב ולשמש באותו הלילה. ואילו \u0003בית הלל אומרים:\u0004 אין היא צריכה לבדוק עצמה בין כל תשמיש שהיא משמשת באותו הלילה, אלא \u0003דיה בשני עדים כל הלילה,\u0004 אחד שבודקת בו לפני התשמיש הראשון באותו הלילה ואחד שבודקת בו לאחר התשמיש האחרון שבאותו הלילה."],["שנינו במשנתנו שלדעת בית שמאי מותר לשמש לאור הנר, ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אף על פי שאמרו\u0004 חכמים כי \u0003משמש מטתו לאור הנר\u0004 — \u0003הרי זה מגונה, בית שמאי אומרים: צריכה\u0004 האשה שתבדוק עצמה ב\u0003שני עדים על כל תשמיש\u0004 שמשמשת באותו הלילה, \u0003או\u0004 ש\u0003תשמש לאור הנר\u0004 כדי שתוכל לבדוק לאורו את עד הבדיקה. \u0003ובית הלל אומרים: דיה בשני עדים כל הלילה,\u0004 אחד לבדיקה לפני התשמיש הראשון ואחד לבדיקה אחר התשמיש האחרון.","ועוד במחלוקת זו של בית שמאי ובית הלל, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמרו להם בית שמאי לבית הלל: לדבריכם,\u0004 שיכולה לשמש כמה פעמים באותו הלילה, ואינה צריכה לבדוק בין כל תשמיש ותשמיש, \u0003ליחוש\u0004 \u0005[נחשוש]\u0006 \u0003שמא תראה טיפת דם\u0004 קטנה \u0003כ\u0004גודל גרגיר צמח ה\u0003חרדל\u0004 כבר \u0003בביאה ראשונה,\u0004 ונטמאה בה, \u0003ותחפנה\u0004 (תכסה אותה) \u0003שכבת זרע\u0004 ש\u0003בביאה\u0004 ה\u0003שניה,\u0004 ולא תימצא טיפת דם זו בבדיקה שלאחר הביאה האחרונה, ותחשוב האשה שהיא טהורה, ואינה אלא טמאה! אלא ודאי צריכה לבדוק אחרי כל תשמיש.","\u0003אמרו להם בית הלל\u0004 בתשובה לכך: \u0003אף לדבריכם\u0004 שבודקת היא את עצמה לפני כל תשמיש ותשמיש, גם כן \u0003ליחוש\u0004 \u0005[נחשוש],\u0006 שכן אפשר ש\u0003עד\u0004 (בעוד) \u0003שהרוק\u0004 (הדם) נמצא עדיין \u0003בתוך הפה\u0004 (כינוי לבית הערוה) \u0003שמא נימוק\u0004 (נמעך) \u0003והולך לו,\u0004 שאף לשיטתכם יתכן ששכבת זרע של אותו תשמיש חיפתה אותו, ולא הועילה הבדיקה שלאחר התשמיש הראשון להראותה את הדם!","\u0003אמרו להם\u0004 בית שמאי לבית הלל בתשובה לכך: אין הדברים דומים \u0003לפי שאינו דומה נימוק\u0004 (נמעך) הנמצא בבית הערוה \u0003פעם אחת\u0004 שהוא הבסיס לחשש שהעליתם, \u0003לנימוק שתי פעמים\u0004 ויותר שהוא הבסיס לחשש שלנו.","ועוד במחלוקתם זו, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003יהושע: רואה\u0004 (מעדיף) \u0003אני את דברי בית שמאי\u0004 בענין זה. \u0003אמרו לו תלמידיו: רבי, כמה הארכת\u0004 (הכבדת) \u0003עלינו\u0004 בפסק זה! \u0003אמר להם: מוטב שאאריך עליכם בעולם הזה, כדי ש\u0004לא תחטאו בביאת איסור ובכך \u0003יאריכו ימיכם לעולם הבא.\u0004","\u0003אמר ר'\u0004 \u0003זירא: מדברי כולם,\u0004 הן בית שמאי שלא התירו לשמש שנית אלא לאחר בדיקה, והן בית הלל שהתירו לשמש שנית אף בלא בדיקה וחייבו לבדוק לאחר התשמיש האחרון, \u0003נלמד\u0004 (יש ללמוד) כי אין זה אלא בגדר המותר, ואולם כל שהוא \u0003בעל נפש\u0004 (הנוהג בחסידות) — \u0003לא יבעול וישנה\u0004 (ויחזור) בלא לבדוק בין תשמיש לתשמיש.","ואילו \u0003רבא אמר:\u0004 אף מי שהוא בעל נפש מותר שיהא \u0003בועל ושונה\u0004 (חוזר) ובועל אף בלא בדיקה בינתיים. שכן \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה]\u0006 ברייתא בחיוב הבדיקות כשמשמשת כמה פעמים באותו הלילה, הרי זה דווקא \u0003ל\u0004ענין האשה העסוקה ב\u0003טהרות,\u0004 ואולם באשר לתשמיש עם בעלה, אין כל חשש.","ואכן \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא האומרת \u0005גם כן כך]:\u0006 \u0003במה דברים אמורים\u0004 שחייבת האשה לבדוק לפני כל תשמיש ולאחריו לשיטת בית שמאי, או אחת לפני התשמיש הראשון ואחת לאחר האחרון לשיטת בית הלל — \u0003לטהרות, אבל לבעלה\u0004 — \u0003מותרת\u0004 אף שלא בדקה עצמה כלל, ואף אם אינו שואל אותה. \u0003ובמה דברים אמורים\u0004 — כ\u0003שהניחה\u0004 בשעה שיצא לדרך כשהיא \u0003בחזקת טהרה, אבל\u0004 אם בשעה שיצא לדרך \u0003הניחה\u0004 כשהיא \u0003בחזקת טמאה\u0004 — \u0003לעולם היא בחזקתה\u0004 כטמאה, \u0003עד שתאמר לו\u0004 במפורש \u0003\"טהורה אני\".\u0004","ועוד בענין בדיקות שלפני התשמיש בלילה \u0003אמר ר'\u0004 \u0003אבא, אמר ר'\u0004 \u0003חייא בר אשי, אמר רב: בדקה\u0004 האשה עצמה בלילה \u0003בעד, ואבד\u0004 עד הבדיקה — \u0003אסורה לשמש\u0004 פעם נוספת \u0003עד שתבדוק\u0004 עצמה בעד אחר, שמא ראתה דם והיה על עד הבדיקה שאבד. \u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על שמועה זו\u0005]\u0006 \u0003ר' אילא: אילו איתא\u0004 \u0005[ישנו]\u0006 לעד הבדיקה הזה, שלא אבד העד, \u0003מי לא\u0004 \u0005[האם אין]\u0006 האשה \u0003משמשה\u0004 \u0005[משמשת]\u0006 שוב עם בעלה באותו הלילה, על סמך שתעיין בעד רק למחרת, \u0003ואף על גב דלא ידעה\u0004 \u0005[ואף על פי שאינה יודעת]\u0006 בשעה שמשמשת בפעם השניה אם יש על עד הבדיקה דם? \u0003השתא נמי\u0004 \u0005[עכשיו\u0006 שאבד העד \u0005גם כן]\u0006 \u0003תשמש!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 יש הבדל בין שני המקרים, שכן במקרה שעד הבדיקה נמצא בידה, הרי \u0003זו\u0004 האשה שעד הבדיקה בידה — \u0003מוכיחה\u0004 (ההוכחה) אם טהורה היא אם לא \u0003קיים\u0004 ועומד, ואם תימצא למחר על פי עד הבדיקה הזה שהיא טמאה, תביא קרבן על ששימשה בטומאה. \u0003ו\u0004אילו \u0003זו\u0004 שאבד עד הבדיקה שלה — \u0003אין מוכיחה קיים,\u0004 ולעולם לא תדע אם צריכה היא כפרה, ועומדת לעולם בספק חוטאת.","\u0003אמר ר'\u0004 \u0003יוחנן: אסור לאדם שישמש מטתו ביום.\u0004 \u0003אמר רב המנונא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 ממנו נלמד דבר זה? — \u0003שנאמר: \"יאבד יום אולד בו והלילה אמר הרה גבר\"\u0004 (איוב ג, ג) — \u0003לילה ניתן להריון, ויום לא ניתן להריון.\u0004 \u0003ריש לקיש אמר, מהכא\u0004 \u0005[מכאן,\u0006 מכתוב זה\u0005]\u0006 יש להביא ראיה שנאמר: \u0003\"בוזה דרכיו ימות\"\u0004 (משלי יט, טו), שמא לאור היום יראה באשתו דבר מגונה ותתבזה בעיניו.","ושואלים: \u0003וריש לקיש, האי קרא\u0004 \u0005[כתוב זה]\u0006 שדרשו \u0003ר' יוחנן מאי דריש ביה\u0004 \u0005[מה\u0006 הוא \u0005דורש בו]?\u0006 ומשיבים: \u0003מבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003ל\u0004דרשה אחרת, וכמו \u0003דדריש\u0004 \u0005[שדרש]\u0006 \u0005ר' חנינא בר פפא.\u0006 \u0003דדריש\u0004 \u0005[ש\u0006כן \u0005דרש]\u0006 \u0003ר' חנינא בר פפא:\u0004 \"והלילה אמר הורה גבר\" — \u0003אותו מלאך הממונה על ההריון, \"לילה\" שמו.\u0004 \u0003ונוטל\u0004 מלאך זה את ה\u0003טפה\u0004 של זרע שממנה עתיד להיווצר אדם, \u0003ומעמידה לפני הקדוש ברוך הוא, ואומר לפניו: רבונו של עולם, טפה זו מה תהא עליה?\u0004 האם יהיה האדם הנוצר ממנה \u0003גבור או חלש, חכם או טיפש, עשיר או עני?\u0004","\u0003ואילו רשע או צדיק לא קאמר\u0004 \u0005[אין הוא אומר],\u0006 והרי זה \u0003כ\u0004דברי \u0003ר' חנינא.\u0004 שכך \u0003אמר ר'\u0004 \u0003חנינא: הכל,\u0004 כל מדות וקורות האדם לאורך חייו הריהם \u0003בידי שמים, חוץ מיראת שמים,\u0004 וכפי \u0003שנאמר: \"ועתה ישראל מה ה'\u0004 \u0003אלהיך שאל מעמך כי אם ליראה\u0004 את ה' אלהיך\" (דברים י, יב).","\u0003ו\u0004אילו \u0003ר' יוחנן\u0004 לא דרש כך, משום ש\u0003אם כן\u0004 שלכך בא הכתוב, \u0003נכתוב קרא\u0004 \u0005[שיכתוב הכתוב]\u0006 \"והלילה אמר \u0003גבר הורה\", מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"הורה גבר\"?\u0004 — \u0003לילה ניתן להריון, ויום לא ניתן להריון.\u0004","\u0003ו\u0004שואלים לשיטת \u0003ר' יוחנן: האי קרא\u0004 \u0005[כתוב זה]\u0006 שהביאו \u0003ריש לקיש מאי דריש ביה\u0004 \u0005[מה\u0006 הוא \u0005דורש בו]?\u0006 ומשיבים: \u0003מבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003ל\u0004ענין \u0003כדכתיב\u0004 \u0005[כמו שכתוב]\u0006 \u0003בספר בן סירא: \"שלשה\u0004 אנשים \u0003שנאתי, וארבעה לא אהבתי,\u0004 ואלו הם: \u0003שר,\u0004 ובכל זאת הוא \u0003נרגל\u0004 (רגיל להימצא) \u0003בבית המשתאות,\u0004 שבכך הוא מבזה את עצמו (\"בוזה דרכיו\"), ובא לכלל הרס עצמי (\"ימות\"). \u0003ואמרי לה\u0004 \u0005[ו\u0006יש \u0005האומרים אותה]\u0006 באופן שונה: \u0003שר הנרגן\u0004 (מרבה לפטפט) בבית המשתאות. \u0003ואמרי לה\u0004 \u0005[ו\u0006יש \u0005האומרים אותה]\u0006 באופן אחר: \u0003שר הנרגז\u0004 (הממהר לרגוז) בהיותו בבית המשתאות,","\u0003והמושיב שבת במרומי קרת\u0004 (בגובהה של עיר, במקום שעיני הכל נשואות שמה). \u0003והאוחז באמה ומשתין מים.\u0004 \u0003והנכנס לבית חבירו פתאום.\u0004 \u0003אמר ר'\u0004 \u0003יוחנן: ו\u0004בכלל זה \u0003אפילו\u0004 הנכנס פתאום \u0003לביתו\u0004 שלו שמא בני הבית עסוקים באותה שעה בדבר הראוי לצניעות.","ועוד בענין זה, \u0003אמר ר'\u0004 \u0003שמעון בן יוחאי: ארבעה דברים הקדוש ברוך הוא שונאן, ואני איני אוהבן.\u0004 ואלו הם: \u0003הנכנס לביתו פתאום, ואין צריך לומר\u0004 — הנכנס \u0003לבית חבירו.\u0004 \u0003והאוחז באמה ומשתין מים,\u0004"],["\u0003ו\u0004האיש ה\u0003משתין מים\u0004 כשהוא \u0003ערום לפני מטתו, וה\u0004אדם ה\u0003משמש מטתו בפני כל חי.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה לשמואל:\u0004 האם הכוונה בביטוי הכולל \"בפני כל חי\" לכל בעלי החיים שהם \u0003ואפילו לפני עכברים? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שיננא\u0004 \u0005[גדול השינים],\u0006 \u0003לא, אלא\u0004 הכוונה ל\u0003כגון\u0004 האנשים \u0003של בית פלוני שמשמשין מטותיהן בפני עבדיהם ושפחותיהם.\u0004","ומבררים: \u0003ואינהו\u0004 \u0005[והם],\u0006 אותם אנשי בית פלוני שנהגו כן, \u0003מאי דרוש\u0004 \u0005[מה\u0006 מאין דרשו] שמותר לעשות כן? — שכך אמר אברהם לשני עבדיו לפני העקידה: \u0003\"שבו לכם פה עם החמור\"\u0004 (בראשית כב, ה), שבא להשוותם ולומר שהריהם \u0003עם הדומה לחמור.\u0004 וסברו אנשי אותו בית שכשם שמותר לשמש לפני בעלי חיים, כך מותר לשמש לפני עבדים ושפחות.","ומביאים מדרכיהם של חכמים בשמירת הצניעות: ש\u0003רבה בר רב הונא\u0004 היה \u0003מקרקש זגי דכילתא\u0004 \u0005[משמיע קול פעמוני הכילה,\u0006 החופה על מטתו\u0005]\u0006 בשעת תשמישו, שיידעו כי אין להתקרב לשם. ואילו \u0003אביי\u0004 היה אף \u0003באלי דידבי\u0004 \u0005[מגרש זבובים]\u0006 שסביב מיטתו, לבל ישמש לפניהם, ואילו \u0003רבא\u0004 היה \u0003באלי פרוחי\u0004 \u0005[מגרש יתושים]\u0006 שסביב מיטתו בשעת התשמיש.","ומביאים עוד ממה ש\u0003אמר ר'\u0004 \u0003שמעון בן יוחי\u0004 בהנהגות האדם: \u0003חמישה דברים הן שהעושה אותן מתחייב בנפשו ודמו בראשו,\u0004 ואלו הן: \u0003האוכל שום קלוף, ובצל קלוף, וביצה קלופה, והשותה משקין מזוגין שעבר עליהן\u0004 על כל אחד מהדברים האמורים \u0003הלילה, והלן בבית הקברות, והנוטל צפרניו וזורקן לרשות הרבים, והמקיז דם ומשמש\u0004 \u0003מטתו\u0004 מיד.","ומפרטים: \u0003האוכל שום קלוף\u0004 ובצל קלוף וביצה קלופה שעבר עליהם הלילה — יש בדבר סכנה, \u0003ואף על גב דמנחי בסילתא ומציירי וחתימי\u0004 \u0005[ואף על פי שמונחים\u0006 הדברים הקלופים \u0005בסל, וצרורים וחתומים\u0006 בו\u0005]\u0006 במשך הלילה, לפי שבכגון זה \u0003רוח רעה שורה עליהן.\u0004 \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שיש באכילתם משום סכנה, \u0003אלא\u0004 רק בזמן ש\u0003לא שייר בהן\u0004 את \u0003עיקרן\u0004 (שורשם) \u0003או\u0004 את \u0003קליפתן, אבל\u0004 אם \u0003שייר בהן עיקרן או קליפתן\u0004 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 סכנה באכילתם.","\u0003ו\u0004עוד אמר ר' שמעון בן יוחאי כי \u0003השותה משקין מזוגין שעבר עליהן הלילה\u0004 יש בדבר סכנה. \u0003אמר רב יהודה, אמר שמואל:\u0004 \u0003והוא\u0004 (ובלבד) \u0003שלנו\u0004 (ששהו משך לילה) \u0003בכלי מתכות.\u0004 \u0003אמר רב פפא: וכלי נתר ככלי מתכות דמו\u0004 \u0005[נחשבים]\u0006 לענין זה. \u0003וכן אמר ר'\u0004 \u0003יוחנן: והוא שלנו בכלי מתכות, וכלי נתר ככלי מתכות דמו\u0004 \u0005[נחשבים].\u0006","\u0003ו\u0004עוד אמר ר' שמעון בן יוחאי כי \u0003הלן בבית הקברות\u0004 הרי זה מסוכן. ומסבירים: הרי זה אמור במי שלן בבית הקברות \u0003כדי שתשרה עליו רוח טומאה.\u0004 וזאת, משום ש\u0003זימנין\u0004 \u0005[פעמים]\u0006 כוחות הטומאה המצויים בבית הקברות \u0003מסכנין ליה\u0004 \u0005[מסכנים אותו]\u0006 את הלן.","\u0003ו\u0004עוד אמר ר' שמעון בן יוחאי כי יש סכנה באדם \u0003הנוטל צפרניו וזורקן לרשות הרבים.\u0004 והסבר הדבר: \u0003מפני שאשה מעוברת\u0004 עלולה שתהיה \u0003עוברת\u0004 מ\u0003עליהן, ו\u0004עלול שתהא \u0003מפלת\u0004 בשל כך את עוברה. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שיש בדבר זה סכנה \u0003אלא\u0004 רק במקרה \u0003דשקיל בגנוסטרי\u0004 \u0005[שנוטל\u0006 צפרניו \u0005במספריים].\u0006 \u0003ו\u0004כן \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שיש סכנה בדבר זה \u0003אלא\u0004 רק במקרה \u0003דשקיל דידיה ודכרעיה\u0004 \u0005[שנוטל\u0006 צפרני \u0005ידו ורגלו].\u0006 \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שיש בדבר זה סכנה \u0003אלא\u0004 רק במקרה ש\u0003לא גז מידי בתרייהו\u0004 \u0005[גזז דבר\u0006 כלשהו \u0005אחריהן],\u0006 \u0003אבל\u0004 אם \u0003גז מידי בתרייהו\u0004 \u0005[גזז דבר אחריהן]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש סכנה. ומסכמים: \u0003ולא\u0004 כך \u0003היא\u0004 הלכה, אלא \u0003לכולה מילתא חיישינן\u0004 \u0005[לכל הדבר,\u0006 בכל האופנים, \u0005אנו חוששים]\u0006 לסכנה.","ועוד בענין ההנהגה בנטילת צפרניים \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה דברים נאמרו ב\u0004נטילת ה\u0003צפרנים:\u0004 ה\u0003שורפן\u0004 — הריהו \u0003חסיד\u0004 שמכלה אותם לגמרי, ה\u0003קוברן\u0004 — הריהו בדרגה פחותה ממנו ואינו אלא \u0003צדיק,\u0004 שיתכן ויתגלו ויעברו עליהם, ואילו ה\u0003זורקן\u0004 סתם — הריהו \u0003רשע.\u0004","\u0003ו\u0004עוד אמר ר' שמעון בן יוחאי כי יש סכנה באדם \u0003המקיז דם ו\u0004מיד לאחר מכן \u0003משמש מטתו.\u0004 ומסבירים, שכן \u0003אמר רב\u0004 \u0005[החכם]:\u0006 ה\u0003מקיז דם ו\u0004לאחר מכן \u0003משמש מטתו\u0004 — \u0003הויין\u0004 \u0005[יהיו]\u0006 \u0003לו\u0004 מזיווג זה \u0003בנים ויתקין\u0004 \u0005[חלושים].\u0006 ואם \u0003הקיזו\u0004 דם \u0003שניהם,\u0004 הבעל והאשה, \u0003ושמשו\u0004 לאחר מכן — \u0003הויין\u0004 \u0005[יהיו]\u0006 \u0003לו בנים בעלי ראתן\u0004 (חולי זיבה). \u0003אמר רב: ולא אמרן\u0004 \u0005[אמרנו]\u0006 שיש סכנה בדבר \u0003אלא\u0004 כש\u0003לא טעים מידי\u0004 \u0005[טועם דבר]\u0006 לאחר שהקיז, \u0003אבל\u0004 אם \u0003טעים מידי\u0004 \u0005[טועם דבר]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש.","ועוד בענין דרך התשמיש, \u0003אמר רב חסדא: אסור לו לאדם שישמש מטתו ביום, שנאמר: \"ואהבת לרעך כמוך\"\u0004 (ויקרא יט, יח). ושואלים: \u0003מאי משמע\u0004 \u0005[מה,\u0006 כיצד \u0005נשמע]\u0006 איסור זה מהפסוק? \u0003אמר אביי:\u0004 שאם ישמש ביום, יש לחשוש \u0003שמא\u0004 אגב כך \u0003יראה בה\u0004 הבעל באשתו \u0003דבר מגונה, ותתגנה עליו,\u0004 ונמצא עובר על מצות \"ואהבת לרעך כמוך\". \u0003אמר רב הונא: ישראל קדושים הם, ואין משמשין מטותיהן ביום.\u0004","\u0003אמר רבא: ואם היה\u0004 זה \u0003בית אפל\u0004 — \u0003מותר\u0004 לשמש בו אף ביום. \u0003ותלמיד חכם\u0004 — \u0003מאפיל בכסותו ומשמש\u0004 אף ביום, שודאי ישמש מיטתו בצניעות.","ושואלים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003או תשמש לאור הנר,\u0004 הרי שאין איסור לשמש אף באור! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן כך בלשון המשנה: \u0003\"תבדוק לאור הנר\",\u0004 אך לא תשמש לאורו.","ומביאים ראיה, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003אף על פי שאמרו\u0004 כי \u0003המשמש מטתו לאור הנר הרי זה מגונה,\u0004 מכל מקום בית שמאי אומרים... תשמש לאור הנר! הרי שאף שהוא מגונה, אין בו איסור! ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \"אף על פי שאמרו ש\u0003הבודק מטתו\u0004 (שבודקת עצמה בעד לצורך תשמיש או לאחריו) \u0003לאור הנר הרי זה מגונה,\u0004 שכן בדרך זו אין הבדיקה נעשית כראוי, בית שמאי אומרים... תבדוק לאור הנר\".","ומביאים ראיה אחרת, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003ושל בית מונבז המלך היו עושין שלשה דברים, ומזכירין\u0004 (ומציינים) \u0003אותן\u0004 חכמים על כך \u0003לשבח: היו משמשין מטותיהם ביום.\u0004 \u0003ו\u0004היו \u0003בודקין מטותיהם ב\u0004בד מילא פרהבא, שהוא לבן ביותר וניכר עליו כל כתם. \u0003ו\u0004היו \u0003נוהגין טומאה וטהרה בשלגים.\u0004 מבין שלוש הנהגות משובחות אלו \u0003קתני מיהא\u0004 \u0005[שנה על כל פנים]\u0006 אחת מהן שהיו \u0003משמשין מטותיהן ביום,\u0004 הרי שאין איסור בדבר!","ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן בלשון ברייתא זו: שהיו \u0003בודקין מטותיהם ביום.\u0004 \u0003הכי נמי מסתברא\u0004 \u0005[כך גם מסתבר]\u0006 לומר, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שהיו \u0003משמשין\u0004 ביום, וכי על כך היו חכמים \u0003מזכירין אותן לשבח?\u0004 ודוחים: \u0003אין הכי נמי\u0004 \u0005[כן,\u0006 אכן \u0005כך גם כן]\u0006 יש צד של שבח במשמש מיטתו ביום, \u0003דאגב דאיכא\u0004 \u0005[שמתוך שיש]\u0006 בלילה \u0003אונס\u0004 (כורח) של \u0003שינה,\u0004 שרוצה הבעל לישון מרוב עייפות היום, עלול הדבר להביא שאשתו הרוצה בתשמיש \u0003מגניא באפיה\u0004 \u0005[מתגנה בפניו].\u0006","\u0003ו\u0004עוד שיבחו חכמים את אנשי בית מונבז, שהיו \u0003בודקין מטותיהן במילא פרהבא.\u0004 ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 מאמר זה \u0003לשמואל,\u0004 שכן \u0003אמר שמואל: אין בודקין את המטה אלא ב\u0004בגד העשוי מ\u0003פקולין\u0004 \u0005[פשתן],\u0006 \u0003או ב\u0004בגד העשוי מ\u0003צמר נקי ורך.\u0004 \u0003אמר רב: היינו דכי הואי התם\u0004 \u0005[זהו\u0006 ההסבר למה \u0005ש\u0006שמעתי \u0005כאשר הייתי שם,\u0006 בארץ ישראל\u0005]\u0006 \u0003בערבי שבתות,\u0004 שהוא עונת תלמידי חכמים, ש\u0003הוו אמרי\u0004 \u0005[היו אומרים]:\u0006 \u0003מאן בעי פקולי בנהמא\u0004 \u0005[מי צריך פקולות ב\u0006אכילת \u0005לחם,\u0006 שהוא כינוי לתשמיש\u0005],\u0006 \u0003ולא ידענא מאי קאמרי\u0004 \u0005[ידעתי,\u0006 הבנתי, \u0005מה הם אומרים].\u0006","\u0003אמר רבא: הני שחקי דכיתנא\u0004 \u0005[\u0006בגדים \u0005שחוקים אלה של כותנה]\u0006 הריהם \u0003מעלי מעולים,\u0004 טובים\u0005]\u0006 \u0003לבדיקה.\u0004 ושואלים על כך: \u0003איני\u0004 \u0005[האמנם],\u0006 \u0003והא תנא\u0004 \u0005[והרי שנה]\u0006 החכם של \u0003בי\u0004 \u0005[בית\u0006 המדרש\u0005]\u0006 של \u0003מנשה: אין בודקין את המטה לא בעד\u0004 בדיקה \u0003אדום, ולא בעד שחור, ולא בפשתן, אלא בפקולין או בצמר נקי ורך!\u0004","ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאין בודקים בפשתן — הרי זהו אמור רק \u0003בכיתנא\u0004 \u0005[בכותנה]\u0006 כשלעצמה, ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר רבא שמועילה הכותנה לבדיקה — הרי זה אמור \u0003במאני דכיתנא\u0004 \u0005[בבגדי כותנה].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003הא והא\u0004 \u0005[זה וזה]\u0006 הן בדברי החכם של בית המדרש של מנשה והן בדברי רבא מדובר \u0003במאני דכיתנא\u0004 \u0005[בבגדי כותנה],\u0006 ואולם יש להבחין, \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שאין הכותנה ראויה לבדיקה — הרי זה דווקא \u0003בחדתי\u0004 \u0005[בחדשים],\u0006 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר רבא שמועילה הכותנה לבדיקה — הרי זה \u0003ב\u0004בגדי כותנה \u0003שחקי\u0004 \u0005[שחוקים],\u0006 שהם בהירים יותר.","ועוד שיבחו חכמים את אנשי בית מונבז על שהיו \u0003נוהגין טומאה וטהרה בשלגין.\u0004 ובענין זה \u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 בתוספתא\u0005]:\u0006 \u0003שלג\u0004 כשלעצמו לענין טומאה \u0003אינו\u0004 נחשב \u0003לא אוכל ולא משקה.\u0004 ואם \u0003חישב עליו לאכילה\u0004 — בטלה דעתו, ו\u0003אינו מטמא טומאת אוכלין.\u0004 ואולם אם חשב על השלג \u0003למשקה\u0004 — הריהו נחשב בכך כמשקה, ו\u0003מטמא\u0004 (ראוי הוא לקבל) \u0003טומאת משקין.\u0004","ואם \u0003נטמא מקצתו\u0004 של השלג — \u0003לא נטמא כולו,\u0004 אלא המקום שנגע בטומאה בלבד, שאין השלג נחשב כגוש אחד. השלג שנטמא והשיקוהו במקוה, אף שלא נגעו מי המקוה אלא בשלג הנמצא בפי הכלי, כיון שבכך \u0003נטהר מקצתו\u0004 של השלג — \u0003נטהר כולו.\u0004","ודנים בדבר, \u0003הא גופא קשיא\u0004 \u0005[הרי\u0006 זה \u0005עצמו קשה],\u0006 שכן בתחילה \u0003אמרת\u0004 שאם \u0003נטמא מקצתו\u0004 של השלג — \u0003לא נטמא\u0004 בכך \u0003כולו,\u0004 \u0003והדר תני\u0004 \u0005[וחזר\u0006 ו\u0005שנה]\u0006 שאם \u0003נטהר מקצתו\u0004 של השלג — \u0003נטהר כולו, למימרא\u0004 \u0005[האם\u0006 אין זה בא \u0005לומר]\u0006 שיש אופן בו \u0003נטמא כולו,\u0004 אף שלא נגעה הטומאה בכולו?!","\u0003אמר אביי:\u0004 אופן זה שנטמא כולו הריהו \u0003כגון שהעבירו\u0004 את השלג \u0003על\u0004 (בתוך) \u0003אויר\u0004 (חלל) כלי כגון \u0003תנור\u0004 שהיתה טומאה בתוכו, שהרי \u0003התורה העידה\u0004 בכתוב \"כל אשר בתוכו יטמא\" (ויקרא יא, לג) \u0003על כלי חרס\u0004 שכל שנמצא בתוכו, ואוירו בכלל זה, הריהו טמא."],["ו\u0003אפילו\u0004 היה כלי החרס \u0003מלא\u0004 בדברים קטנים כגרגירי זרע ה\u0003חרדל,\u0004 שלא נגעו בדפנות הכלי אלא מעט מן הגרגרים הללו, טמאים כל הגרגרים שהיו בתוך הכלי. ואף השלג, משעבר באויר כלי החרס שבו הטומאה, נטמא כולו.","מקום בית הערוה באשה מורכב מחלקים שונים, ואין דין דם הנמצא בחלק זה כדין דם הנמצא בחלק אחר. ולכך \u0003משל משלו חכמים\u0004 בתיאור מבנה בית הערוה ש\u0003באשה\u0004 לחלקיו השונים, כבית: \u0003החדר,\u0004 הפנימי מכל החלקים — הוא הרחם שבאשה. \u0003ו\u0004לפני \u0003ה\u0004חדר נמצא \u0003פרוזדור\u0004 (מסדרון, המבוא לחדר) — הוא המעבר אל הרחם, \u0003ו\u0004מעל שני אלה נמצאת \u0003העלייה\u0004 — חלק בית הערוה הנתון מעל הרחם והפרוזדור.","ומעתה לדין הדם בכל אחד מאלה המקומות: \u0003דם החדר\u0004 — \u0003טמא,\u0004 שהרי זה דם המקור. \u0003דם העלייה\u0004 שאין זה דם נדה. הדם ה\u0003נמצא בפרוזדור,\u0004 שספק יש בו אם בא מן החדר (והוא טמא) או שבא מן העלייה (והוא טהור) — \u0003ספקו\u0004 זה גורם לו שהריהו \u0003טמא\u0004 טומאה ודאית, הגם שהרי זה ספק. וטעם הדבר: \u0003לפי שחזקתו\u0004 של הדם הנמצא, שהוא בא \u0003מן המקור,\u0004 ולא מהעליה.","שנינו במשנתנו כי בבית הערוה של האשה ישנם חלקים המכונים חדר ופרוזדור. ומביאים עוד באותו ענין: \u0003רמי בר שמואל ו\u0004כן \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה תנו\u0004 \u0005[שנו]\u0006 את מסכת \u0003נדה\u0004 \u0003בי\u0004 \u0005[\u0006ב\u0005בית\u0006 המדרש\u0005]\u0006 של \u0003רב הונא.\u0004 \u0003אשכחינהו\u0004 \u0005[מצאם]\u0006 \u0003רבה בר רב הונא דיתבי וקאמרי\u0004 \u0005[שיושבים ואומרים]\u0006 כך את לשון משנתנו זו: \u0003החדר,\u0004 הוא הרחם — נמצא \u0003מבפנים\u0004 (פנימה יותר, לכיוון אחורי הגוף). \u0003והפרוזדור\u0004 — נמצא \u0003מבחוץ\u0004 לו (לכיוון קידמת הגוף). \u0003ו\u0004ה\u0003עלייה בנויה על שתיהן.\u0004 \u0003ו\u0004עוד הוסיפו ושנו כי מצוי באותו מקום גם \u0003לול\u0004 (חלל) ה\u0003פתוח בין\u0004 ה\u0003עלייה לפרוזדור.\u0004","אם \u0003נמצא\u0004 דם במקום שהוא \u0003מן הלול ולפנים\u0004 (לכיוון אחורי הגוף) — \u0003ספקו טמא.\u0004 נמצא במקום שהוא \u0003מן הלול ולחוץ\u0004 (לכיוון קידמת הגוף) — \u0003ספקו טהור.\u0004","\u0003אתא\u0004 \u0005[בא]\u0006 רבה \u0003ואמר ליה לאבוה\u0004 \u0005[לו לאביו,\u0006 רב הונא\u0005]:\u0006 האם בדין הדם הנמצא בין הלול ולפנים \u0003\"ספקו טמא\" אמרת לן מר\u0004 \u0005[לנו, אדוננו],\u0006 וכדרך ששמעתי מפי חכמי בית המדרש? \u0003והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"שחזקתו מן המקור\" תנן\u0004 \u0005[שנינו]\u0006 מפיך, משמע שטומאה ודאית היא זו. ומעתה במה דברים אמורים? לא בנמצא מן הלול ולפנים ולא בנמצא מן הלול ולחוץ!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לבנו רבה: \u0003אנא הכי קאמינא\u0004 \u0005[אני כך אמרתי]\u0006 בדינו של הדם הנמצא בפרוזדור: נמצא הדם במקום שהוא \u0003מן הלול ולפנים\u0004 — הרי זה \u0003ודאי טמא,\u0004 שחזקתו מן המקור, ובאלה עוסקים דברי משנתנו. נמצא הדם \u0003מן הלול ולחוץ\u0004 — \u0003ספקו טמא,\u0004 שאף שיש מקום לומר שאילו היה זה דם החדר — לא היה מגיע מן הלול ולחוץ, מכל מקום יש לחשוש שמא התכופפה האשה, ומתוך כך יצא הדם מהחדר מן הלול ולחוץ, ולכך הריהי טמאה מספק.","\u0003אמר אביי\u0004 בשאלה על כך: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 במה נבדל\u0005]\u0006 הדם הנמצא \u0003מן הלול ולחוץ\u0004 ש\u0003ספקו טמא\u0004 — \u0003דדלמא\u0004 \u0005[ששמא]\u0006 \u0003שחתה\u0004 (התכופפה), \u0003ומחדר אתא\u0004 \u0005[בא]\u0006 הדם — אם כן אף אם נמצא הדם \u0003מן הלול ולפנים,\u0004 שאתה מטמא בודאי \u0003נמי\u0004 \u0005[גם כן],\u0006 \u0003אימא\u0004 \u0005[אמור]:\u0006 שמא \u0003אזדקרה\u0004 \u0005[הזדקפה]\u0006 האשה, \u0003ו\u0004מתוך כך \u0003מעלייה אתא\u0004 \u0005[בא]\u0006 הדם לאותו מקום, וטמאה רק מספק!","\u0003אלא אמר אביי: אי בתר חששא אזלת\u0004 \u0005[אם אחר חשש\u0006 שמא הדם הנמצא במקום זה בא בעקבות התכופפות או הזדקפות \u0005אתה הולך]\u0006 — \u0003אידי ואידי\u0004 \u0005[זה וזה,\u0006 בין נמצא מן הלול ולפנים ובין מן הלול ולחוץ\u0005]\u0006 — \u0003ספק הוא, ואי בתר\u0004 \u0005[ואם אחר]\u0006 \u0003חזקה אזלת\u0004 \u0005[אתה הולך]\u0006 — \u0003מן הלול ולפנים\u0004 — \u0003ודאי טמא, מן הלול ולחוץ\u0004 — \u0003ודאי טהור.\u0004","למדנו איפוא ארבע שיטות חכמים בדין הדם הנמצא בפרוזדור, ותחילה מביאים את מה ש\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: דם הנמצא בפרוזדור\u0004 — טמא ודאי, ואם נכנסה האשה שראתה דם זה למקדש, \u0003חייבין עליו\u0004 (בגללו) \u0003על\u0004 איסור \u0003ביאת מקדש\u0004 בטומאה, \u0003ושורפין עליו את התרומה\u0004 שנגעה בה אשה זו. \u0003ו\u0004אילו \u0003רב קטינא אמר:\u0004 אין זו אלא טומאה מספק, ולכך \u0003אין חייבין עליו על ביאת מקדש, ואין שורפין עליו את התרומה.\u0004","ומעתה יש לברר מה היחס בין ארבע שיטות אלה למחלוקת שבין ר' חייא ורב קטינא: \u0003להך לישנא\u0004 \u0005[ללשון זו]\u0006 ש\u0003אמר אביי\u0004 ש\u0003אי בתר חששא אזלת\u0004 \u0005[אם אחר חשש\u0006 דם המגיע בעקבות התכופפות או הזדקפות \u0005אתה הולך],\u0006 ובכל האופנים הריהו ספק טומאה — \u0003מסייע ליה\u0004 \u0005[לו]\u0006 שיטה זו של אביי \u0003לרב קטינא\u0004 שאף הוא מטמא מספק דם הנמצא בפרוזדור, \u0003ופליגא\u0004 \u0005[וחולק]\u0006 אביי על שיטת \u0003ר' חייא\u0004 המטמא בודאי.","ואילו \u0003להך לישנא\u0004 \u0005[ללשון זו]\u0006 של אביי \u0003דאמרת אי בתר\u0004 \u0005[האומרת אם אחר]\u0006 \u0003חזקה אזלת\u0004 \u0005[אתה הולך],\u0006 לכן בנמצא מן הלול ולפנים הריהי טמאה ודאי, ובנמצא מן הלול ולחוץ הריהי טהורה בודאי — \u0003מסייע ליה\u0004 \u0005[לו]\u0006 שיטה זו של אביי \u0003לר' חייא,\u0004 שאף הוא סבור כי הריהי טמאה בודאי (שאף דברי ר' חייא לא נאמרו אלא בדם הנמצא מן הלול ולפנים), ולכך חייבים על טומאה זו משום ביאת מקדש ושורפים את התרומה שנגעה בה."],["\u0003ופליגא\u0004 \u0005[וחולק]\u0006 אביי על שיטתו של \u0003רב קטינא\u0004 האומר שהריהי טמאה מספק.","\u0003ול\u0004שיטתו של \u0003רב הונא\u0004 האומר שבנמצא מן הלול ולפנים הריהי ודאי טמאה, ובנמצא מן הלול ולחוץ הריהי ספק טמאה — סבורה היא הן כר' חייא והן כרב קטינא, ויש מקום לומר ש\u0003לא פליגי\u0004 \u0005[אינם חלוקים]\u0006 הם בעיקרו של דין, אלא שדברו באופנים שונים: \u0003כאן\u0004 בדברי ר' חייא המטמא בודאי, מדובר כשנמצא הדם \u0003מן הלול ולפנים.\u0004 ואילו \u0003כאן\u0004 בדברי רב קטינא המטמא מן הספק, מדובר כשנמצא הדם \u0003מן הלול ולחוץ.\u0004","\u0003אלא ל\u0004שיטתו של \u0003רמי בר שמואל ול\u0004שיטתו של \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה, דאמרי\u0004 \u0005[שאומרים]\u0006 כי דם הנמצא \u0003מן הלול ולחוץ\u0004 — \u0003ספקו טהור,\u0004 ודם הנמצא \u0003מן הלול ולפנים\u0004 — \u0003ספקו טמא, הני במאי מתוקמא\u0004 \u0005[אלה,\u0006 ר' חייא ורב קטינא, \u0005במה,\u0006 באיזה מקרה, \u0005עומדת,\u0006 עוסקת מחלוקתם\u0005]?\u0006 — \u0003מן הלול ולפנים,\u0004 שהרי לדעת רמי בר שמואל ורב יצחק בנמצא מן הלול ולחוץ הריהו טהור.","ומעתה \u0003לימא פליגא\u0004 \u0005[האם נאמר\u0006 ש\u0005חלוקים\u0006 הם] על שיטת \u0003ר' חייא\u0004 המטמא בודאי, בעוד הם מטמאים מספק!","ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר קשה], שכן יש מקום לומר שרמי בר שמואל ורב יצחק סבורים אף כר' חייא, ולשיטתם לא נחלקו ר' חייא ורב קטינא בעיקרו של דין, אלא שדברו באופנים שונים: \u0003כאן\u0004 בדברי ר' חייא המטמא בודאי, מדובר \u0003כשנמצא\u0004 הדם \u0003בקרקע פרוזדור,\u0004 שבזה יש לומר שבא הדם מהחדר ולא מהעליה. \u0003ו\u0004אילו \u0003כאן\u0004 בדברי רב קטינא המטמא מן הספק, מדובר \u0003שנמצא\u0004 הדם \u0003בגג פרוזדור,\u0004 שבזה יש ספק מהיכן בא הדם אם מן העליה או מן החדר.","ובעקבות הלכה זו מביאים מה ש\u0003אמר ר'\u0004 \u0003יוחנן: בשלשה מקומות\u0004 של ספק \u0003הלכו\u0004 (פסקו) \u0003בו חכמים\u0004 שהולכים \u0003אחר הרוב, ו\u0004על סמך הרוב \u0003עשאום\u0004 (קבעו את דינם של הספקות הללו) \u0003כודאי,\u0004 ואלו הם: \u0003מקור, שליא, חתיכה.\u0004 ומפרטים: \u0003מקור\u0004 — \u0003הא דאמרן\u0004 \u0005[\u0006הלכה \u0005זו שאמרנו],\u0006 שאם נמצא הדם בפרוזדור לפנים מהלול, שדם זה טמא ודאי.","\u0003שליא\u0004 — \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה בפרק הבא\u0005]:\u0006 \u0003שליא\u0004 (איבר בגוף האשה שהעובר נתון בתוכו ומקבל דרכו את מזונו) שנמצאה \u0003בבית,\u0004 אף שאין בשליה ולד — \u0003הבית טמא\u0004 בטומאת אהל, ככל בית שהמת נתון בתוכו. \u0003ו\u0004טעם הדבר: \u0003לא\u0004 מפני \u0003שהשליא\u0004 עצמה הינה \u0003ולד, אלא\u0004 מפני \u0003שאין\u0004 כמעט \u0003שליא בלא ולד,\u0004 שברוב השליות יש ולד. ואף בזו ודאי היה ולד, ומת הולד ונמחה לאחר שיצאה השליה מגוף האשה, ולכן אינו נראה עתה. וטמא הבית משום הולד המת שבשליה. ואילו \u0003ר' שמעון אומר:\u0004 אין הבית טמא בטומאת אהל, כיון ש\u0003נמוק\u0004 (נמחה) \u0003הולד עד שלא\u0004 (בטרם) \u0003יצא,\u0004 ונעשה לדם, והתערב דם זה בדם הלידה, והתבטל ברוב. ומכל מקום שנינו שלדעת חכמים, טמא הבית טומאת ודאי, אף שנסמך הדבר על רוב שליות.","\u0003חתיכה\u0004 — \u0003דתנן\u0004 \u0005[ששנינו\u0006 בתוספתא\u0005]: המעוברת\u0006 \u0003המפלת\u0004 צורת \u0003יד חתוכה\u0004 (שאצבעותיה חתוכות, מופרדות וניכרות) \u0003ורגל חתוכה\u0004 — \u0003אמו טמאה לידה\u0004 (שבועיים כיולדת נקבה, מחמת הספק) ככל היולדת (או המפלת) עובר שנגמרה צורתו ואף יש לה ימי טוהר (כזכר בלבד, מחמת הספק). \u0003ואין חוששין שמא מגוף אטום\u0004 (שלא נגמרה צורתו, שאין בו חלוקת איברים) \u0003באת\u0004 (באה) חתיכה זו ואין לה ימי טוהר. משום שרוב הנשים המעוברות יולדות עובר שנגמרה צורתו, ואף במקרה זה יש לומר שבאה היד או הרגל החתוכה מולד שהיה שלם, ונמחה בלידה. הרי שקבעו חכמים טומאה ודאית, בהסתמך על הרוב.","ושואלים: \u0003ותו\u0004 \u0005[ועוד]\u0006 מקרים, מלבד שלושה מקומות אלה, שדנו בספק כודאי, בהסתמך על רוב, \u0003ליכא\u0004 \u0005[אין]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 דין \u0003תשע חנויות!\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 עיר שיש בה \u0003תשע חנויות\u0004 ש\u0003כולן מוכרות בשר\u0004 כשר שהוא בשר \u0003שחוטה, ואחת מוכרת בשר נבלה\u0004 האסור באכילה, \u0003ולקח\u0004 (קנה) אדם \u0003מאחת מהן, ואינו יודע מאיזה מהן לקח\u0004 — \u0003ספקו אסור,\u0004 שכן בספק זה שהתחיל במקום קבוע, כגון החנויות שבעיר הקבועות במקומן, אין הולכים אחר הרוב.","\u0003ו\u0004אולם \u0003ב\u0004מקרה שבו לא נוצר הספק לאחר שנלקח הבשר מאחת החנויות, אלא לאחר ש\u0003נמצא\u0004 הבשר מוטל בעיר, ואין ידוע מאיזו חנות הגיע — הכלל הוא: \u0003הלך\u0004 (לך) \u0003אחר הרוב,\u0004 וכיון שרוב החנויות מוכרות בשר כשר, אף חתיכה זו הריהי כשרה בודאי. והרי מקרה נוסף בו עשו את הספק כודאי!","ומתרצים: מנין המקומות בהם עשו חכמים את הספק כודאי בהסתמך על הכלל שהולכים אחר הרוב, דווקא בעניינים הנוגעים ל\u0003טומאה\u0004 הוא ש\u0003קאמרינן\u0004 \u0005[אומרים אנו]\u0006 אותו, ואילו בעניינים הנוגעים ל\u0003איסור\u0004 כגון זה של חנויות המוכרות בשר שחוטה ונבילה — \u0003לא קאמרינן\u0004 \u0005[אין אנו אומרים].\u0006","ושואלים עוד: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 מקרה זה של \u0003תשע צפרדעין\u0004 מתים (שאינם מטמאים במותם) \u0003ושרץ אחד\u0004 מת המטמא ישנו \u0003ביניהם, ונגע באחד מהן,\u0004 מהעשרה הללו, \u0003ואינו יודע באיזה מהן נגע\u0004 — אם היה הדבר \u0003ברשות היחיד\u0004 — \u0003ספקו טמא,\u0004 שלמדים ממדרש המקראות שספק טומאה ברשות היחיד הריהו טמא. ואם היה הדבר \u0003ברשות הרבים\u0004 — \u0003ספקו טהור.\u0004","\u0003וב\u0004מקרה שבו אחד מבעלי החיים הללו פרש מתוך הקבוצה ו\u0003נמצא\u0004 שלא במקום כולם, ושם נגע בו — הכלל הוא: \u0003הלך אחר הרוב,\u0004 ומכיון שהרוב צפרדעים — טהור. הרי שיש עוד מקרה, בענייני טומאה שקבעו בו חכמים שדינו כודאי בהסתמך על הרוב!","ומתרצים: מנין זה של שלושה מקומות, דווקא בעניינים הנוגעים ל\u0003טומאה\u0004 שב\u0003אשה\u0004 — \u0003קאמרינן\u0004 \u0005[אומרים אנו],\u0006 ואילו בעניינים שב\u0003טומאה בעלמא\u0004 \u0005[בכלל]\u0006 — \u0003לא קאמרינן\u0004 \u0005[אין אנו אומרים].\u0006","ושואלים עוד: \u0003והאיכא הא\u0004 \u0005[והרי יש\u0006 דבר \u0005זה]\u0006 ש\u0003אמר ר'\u0004 \u0003יהושע בן לוי:\u0004 אשה מעוברת ש\u0003עברה בנהר\u0004"],["\u0003והפילה\u0004 נפל אל תוך הנהר, ואין ידוע מה הפילה, אם היה זה ולד גמור או ולד שלא הושלם — \u0003מביאה\u0004 אשה זו ככל אשה היולדת (או המפלת) עובר שנגמרה צורתו \u0003קרבן\u0004 יולדת, עולה וחטאת, \u0003ונאכל\u0004 קרבן החטאת שנמלק כדרך חטאת העוף, אף שספק הוא שמא היה זה ולד שלא הושלם, ואין היא חייבת בקרבן זה, וכל עוף שאינו קרבן מליקתו אוסרתו.","ופסקו כך לפי שכלל הוא: \u0003הלך\u0004 (לך, יש ללכת) \u0003אחר רוב\u0004 ה\u0003נשים\u0004 המעוברות, \u0003ורוב\u0004 ה\u0003נשים\u0004 המעוברות — \u0003ולד מעליא ילדן\u0004 \u0005[מעולה,\u0006 שלם, הן \u0005יולדות].\u0006 וסמכו חכמים על כלל זה, ועשו את דינה של חטאת העוף של זו כדין ודאי, ולכן הוא נאכל. הרי שאף בטומאת אשה יש מקרה נוסף שבו הולכים אחר הרוב לעשות את הספק כודאי, ומדוע מנה ר' יוחנן רק שלושה מקרים בלבד?","ומתרצים: רק מקרים הנשנים ב\u0003מתניתין קאמרינן\u0004 \u0005[\u0006במשנה או ברייתא \u0005אומרים אנו]\u0006 בכלל מנין זה, ואילו מקרים הנזכרים ב\u0003שמעתתא\u0004 \u0005[שמועה,\u0006 דברי חכמים\u0005],\u0006 כגון הלכה זו של ר' יהושע בן לוי — \u0003לא קאמרינן\u0004 \u0005[אין אנו אומרים].\u0006","ושואלים על הסבר זה: \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 כי מסורת בידו ש\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0005ר' יוסי בר ר'\u0006 \u0003חנינא\u0004 על דברי ר' יהושע בן לוי אלו מברייתא העוסקת באשה ה\u0003טועה\u0004 (שאינה יודעת מתי ילדה), והוסיף רבין ואמר: \u0003ולא ידענא מאי תיובתיה\u0004 \u0005[ואין אני יודע מהי קושייתו]\u0006 מברייתא זו.","ודנים בכוונת דברי רבין, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא שדברי ברייתא זו \u0003לא תיובתא\u0004 \u0005[אינן קושיה]\u0006 על שיטת ר' יהושע בן לוי, \u0003אלא\u0004 דווקא \u0003סייעתא\u0004 \u0005[סיוע]\u0006 לה. ואם כן, הרי שלדברי ר' יהושע בן לוי יש משקל לדברי המשנה, וראוי היה איפוא לכוללם נוסף לשלושת המקרים שמנה ר' יוחנן!","ומשיבים: \u0003לא,\u0004 אין להוכיח מכאן, \u0003דלמא\u0004 \u0005[שמא]\u0006 התכוון לומר שלדעתו דברי ברייתא זו אינם \u0003לא תיובתא\u0004 \u0005[לא קושיה]\u0006 \u0003ולא סייעתא\u0004 \u0005[ולא סיוע]\u0006 לשיטת ר' יהושע בן לוי.","ושואלים: מה שאמר ר' יוחנן כי בשלושה מקומות הלכו חכמים אחר הרוב ועשאום כודאי, ומשמע מדבריו שבא להדגיש שאין אלו אלא שלושה מקרים בלבד, מנין זה \u0003למעוטי מאי\u0004 \u0005[למעט מה]\u0006 הוא בא?","\u0003אילימא למעוטי\u0004 \u0005[אם לומר\u0006 שבא \u0005למעט]\u0006 ספק שיש בו מן הצד האחד \u0003רובא\u0004 לטמא את האשה, ואולם \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003חזקה בהדיה\u0004 \u0005[איתו,\u0006 כלומר, כנגדו\u0005]\u0006 לטהרה, שגורעת החזקה מכוחו של הרוב, ולכן אין הספק מוכרע כודאי, ו\u0003לא שרפינן עליה\u0004 \u0005[אין שורפים עליו]\u0006 \u0003את התרומה\u0004 — \u0003והא\u0004 \u0005[והרי]\u0006 כבר אמרה ר' י \u0003וחנן חדא זימנא\u0004 \u0005[פעם אחת]\u0006 בענין שאר טומאות, שאם יש ספק שרוב מטהו לטומאה וחזקה המטה אותו לטהרה, אין הולכים אחר הרוב לעשותו כטומאה ודאי!","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במסכת טהרות\u0005]:\u0006 \u0003תינוק\u0004 טמא \u0003הנמצא בצד העיסה\u0004 הטהורה \u0003ו\u0004מקצת מן ה\u0003בצק\u0004 נתון \u0003בידו,\u0004 ואין ידוע אם הוא עצמו לקח חתיכה זו מהעיסה, וטימא אותה בכך, או שאדם אחר, טהור, לקחה מן העיסה ונתנה לו, ואין העיסה טמאה. נחלקו חכמים, ר' מאיר מטהר, \u0003וחכמים מטמאין.\u0004 \u0003וטעמם של חכמים, משום\u0004 \u0003ש\u0004כן הוא \u0003דרכו של תינוק לטפח\u0004 בעיסה הנמצאת לצידו (תוס'), ולכן מניחים אנו שהתינוק הוא שלקח את חתיכת הבצק מן העיסה.","\u0003ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר\u0004 — \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כי אמנם \u0003רוב\u0004 ה\u0003תינוקות מטפחין\u0004 בעיסה הנמצאת לצידם, \u0003ו\u0004אולם יש \u0003מיעוט\u0004 תינוקות ש\u0003אין מטפחין, ו\u0004מכיון ש\u0003עיסה זו בחזקת טהורה עומדת,\u0004 לכן אומרים אנו: \u0003סמוך\u0004 (צרף) את \u0003מיעוטא\u0004 \u0005[מיעוט]\u0006 התינוקות שאין מטפחים \u0003לחזקה\u0004 של טהרה — \u0003ואיתרע ליה רובא\u0004 \u0005[והתרועע,\u0006 ונחלש \u0005לו הרוב].\u0006 ולכן אין סומכים על הרוב לטמא את העיסה.","\u0003ו\u0004אילו שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא ש\u0003מיעוטא\u0004 \u0005[מיעוט]\u0006 ככלל ביחס לרוב — \u0003כמאן דליתיה דמי\u0004 \u0005[כמי שאינו\u0006 קיים הוא \u0005נחשב],\u0006 ומיעוט התינוקות שאינם מטפחים אינו נחשב, ואין לנו אלא רוב תינוקות המטפחים שהוא סיבה לטמא את העיסה, ולעומת זאת יש חזקת טהרה, \u0003ו\u0004כלל הוא: \u0003רובא\u0004 \u0005[רוב]\u0006 \u0003וחזקה\u0004 — \u0003רובא\u0004 \u0005[רוב]\u0006 \u0003עדיף\u0004 ולכן הם מטמאים.","\u0003ו\u0004בהסבר שיטת חכמים במשנה זו \u0003אמר ריש לקיש משום\u0004 (בשם) \u0003ר' אושעיא:\u0004 חזקה \u0003זו\u0004 שרוב התינוקות מטפחים בעיסה \u0003היא חזקה\u0004 גמורה, ודינה של העיסה כטמאה ודאי, \u0003ששורפין עליה את התרומה, ו\u0004אילו \u0003ר' יוחנן אמר: אין\u0004 חזקה \u0003זו חזקה\u0004 גמורה לקבוע את העיסה כטמאה ודאי, \u0003ששורפין עליה את התרומה.\u0004 הרי שכבר אמר ר' יוחנן שבמקרה של רוב שניצבת מולו חזקה אין סומכים על הרוב לעשות את הדבר כטמא ודאי, ולא היה צריך איפוא למנות רק שלושה מקרים בהם הספק נחשב לודאי טמא בהסתמך על הרוב!","ומתרצים: לא בא מנין זה של שלושה מקרים שמנה ר' יוחנן \u0003אלא למעוטי רובא\u0004 \u0005[למעט רוב]\u0006 מסויים וכגון זה שאמרו \u0003ר' יהודה, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 האשה המעוברת \u0003המפלת חתיכה\u0004 (גוש בשר חסר צורה), \u0003אם יש עמה\u0004 (עם החתיכה הזו, ומחוצה לה) \u0003דם\u0004 — הרי האשה \u0003טמאה\u0004 טומאת נדה. \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003טהורה\u0004 היא מנדה והרי זו נחשבת כלידה. \u0003ר' יהודה אומר: בין כך\u0004 שיש עם החתיכה דם, \u0003ובין כך\u0004 שאין עמה דם — האשה \u0003טמאה\u0004 טומאת נדה, שכן ודאי הוא שעם פתיחת הרחם ראתה דם, אף שאינו נראה עתה.","\u0003ו\u0004בהבנת שיטת ר' יהודה \u0003אמר רב יהודה, אמר שמואל: לא טימא ר'\u0004 \u0003יהודה אלא בחתיכה\u0004 שהמראה שלה הוא כמראהו \u0003של\u0004 אחד מ\u0003ארבע מיני\u0004 מראות ה\u0003דמים\u0004 המטמאים, השנויים להלן בפרקנו, \u0003אבל\u0004 אם היה מראה חתיכה זו כמראה \u0003שאר מיני דמים\u0004 שאינם מטמאים — \u0003טהורה.\u0004 \u0003ו\u0004אילו \u0003ר' יוחנן אמר:\u0004 אם היה מראה חתיכה זו כמראה \u0003של ארבע מיני\u0004 ה\u0003דמים\u0004 המטמאים — \u0003דברי הכל טמאה,\u0004 שאף לדעת חכמים האשה טמאה. \u0003ו\u0004כמו כן אם היה מראה חתיכה זו כמראה \u0003של שאר דמים\u0004 — \u0003דברי הכל טהורה,\u0004 שאף ר' יהודה מטהר בכך. \u0003לא נחלקו\u0004 חכמים ור' יהודה \u0003אלא כשהפילה\u0004"],["\u0003ואינה יודעת מה הפילה,\u0004 מה היה מראה חתיכה זו, וכגון שאבדה אותה חתיכה שהפילה, שבמקרה זה \u0003ר' יהודה סבר\u0004 \u0005[סבור]\u0006 שכך יש לנהוג בדין זה: \u0003זיל בתר\u0004 \u0005[לך אחר]\u0006 המראה של \u0003רוב\u0004 ה\u0003חתיכות\u0004 שאשה מפילה, \u0003ו\u0004כיון שהמראה של \u0003רוב חתיכות\u0004 אלו — מראה \u0003של ארבע מיני דמים הויין\u0004 \u0005[הינן],\u0006 הריהי אם כן טמאה. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 שאין מראה רוב החתיכות שהאשה מפלת כשל מראה דמים טמאים, ולכן \u0003זיל בתר\u0004 \u0005[לך אחר]\u0006 \u0003רוב חתיכות\u0004 — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 ואם כן יש לומר כי המנין של שלושה מקרים שמנה ר' יוחנן, בא למעט הלכה זו של ר' יהודה שפסק טומאה ודאית על פי רוב.","\u0003חמשה\u0004 מראות \u0003דמים טמאים\u0004 יש \u0003באשה,\u0004 הנבדלים בצבעיהם, שאם ראתה אחד מסוגי דמים אלו, הריהי טמאה. ואלו הם: \u0003האדום, והשחור, וכקרן\u0004 (כצבע בוהק של) צמח ה\u0003כרכום, ו\u0004צבעם של \u0003כמימי\u0004 (המים שמציפים בהם) \u0003אדמה\u0004 אדומה, \u0003וכ\u0004צבעו של היין האדום ה\u0003מזוג\u0004 במים. \u0003בית שמאי אומרים: אף\u0004 הדם שמראהו \u0003כמימי\u0004 (המים בו שורים) את צמח ה\u0003תלתן, ו\u0004הדם שמראהו \u0003כמימי\u0004 (המיצים הנוטפים) מ\u0003בשר\u0004 ה\u0003צלי\u0004 הם ממראות הדמים הטמאים, ולא רק אותם חמישה. \u0003ו\u0004אילו \u0003בית הלל\u0004 \u0003מטהרים\u0004 בשני מראות אלה. ובדינו של \u0003ה\u0004דם שמראהו \u0003ירוק\u0004 (צהוב) נחלקו חכמים, שכן \u0003עקביא בן מהללאל מטמא,\u0004 שלדעתו אף הוא דם נדות, \u0003ו\u0004אילו \u0003חכמים מטהרין,\u0004 שלדעתם אין זה דם נדה כלל.","\u0003אמר ר'\u0004 \u0003מאיר: אם אינו מטמא משום כתם,\u0004 וכדם הנדה — מכל מקום הריהו דם וככזה הריהו \u0003מטמא\u0004 (מכשיר את הזרעים לקבל טומאה, אם נשפך עליהם) \u0003משום\u0004 היותו \u0003משקה,\u0004 כאחד משבעת המשקים שבנפילתם על הזרעים הם מכשירים אותם לקבל טומאה. \u0003ר' יוסי אומר: לא כך,\u0004 כשיטת עקביא בן מהללאל המטמא את הדם שמראהו ירוק בטומאת הנדה, \u0003ולא כך,\u0004 כשיטת ר' מאיר המחשיב אותו כמכשיר את הזרעים לקבל טומאה, אלא הריהו טהור לגמרי.","ומעתה מבררים: \u0003איזהו\u0004 הצבע ה\u0003אדום\u0004 המטמא — \u0003כ\u0004מראה ה\u0003דם\u0004 היוצא מן \u0003המכה.\u0004 ואיזהו ה\u0003שחור\u0004 המטמא — \u0003כ\u0004צבע ה\u0003חרת\u0004 (דיו). ואם מראה הדם \u0003עמוק\u0004 (כהה) יותר \u0003מכן,\u0004 ששחור הוא יותר מחרת — \u0003טמא,\u0004 ואם מראה הדם \u0003דיהה\u0004 (בהיר) יותר \u0003מכן,\u0004 ששחור פחות מן החרת — \u0003טהור.\u0004 \u0003ו\u0004הדם שצבעו קרן כרכום שמטמא — הרי זה דווקא \u0003כ\u0004מראה של העלה ה\u0003ברור\u0004 (הזוהר ביותר) \u0003שבו.\u0004","\u0003ו\u0004זה שצבעו \u0003כמימי אדמה\u0004 שהריהו מטמא — הרי זה דווקא אדמה \u0003מבקעת בית כרם, ו\u0004דווקא כשהוא \u0003מיצף\u0004 (מציף) אותה ב\u0003מים\u0004 עד שהמים צפים עליה. \u0003ו\u0004הדם שמראהו \u0003כ\u0004מראה היין ה\u0003מזוג\u0004 המטמא — הרי זה דווקא כאשר מזיגה זו מורכבת מ\u0003שני חלקים מים ו\u0004חלק \u0003אחד יין,\u0004 ודווקא \u0003מן היין השרוני\u0004 (מאיזור השרון שבארץ ישראל).","שנינו במשנתנו אלו הם מראות הדמים המטמאים, ומכאן שדם שמראהו אינו כן, אינו מטמא. ושואלים: \u0003מנלן דאיכא\u0004 \u0005[מנין לנו שיש]\u0006 בכלל \u0003דם טהור באשה? דלמא\u0004 \u0005[שמא]\u0006 \u0003כל דם דאתי מינה\u0004 \u0005[שבא ממנה]\u0006 הריהו \u0003טמא!\u0004","\u0003אמר ר'\u0004 \u0003חמא בר יוסף, אמר ר'\u0004 \u0003אושעיא, אמר קרא\u0004 \u0005[הכתוב]\u0006 בבאים לפני בית הדין: \u0003\"כי יפלא ממך דבר למשפט בין דם לדם\u0004 בין דין לדין ובין נגע לנגע, דברי ריבות בשעריך וקמת ועלית אל המקום אשר יבחר ה' אלהיך בו\" (דברים יז, ח), וכוונת הכתוב \"בין דם לדם\" — \u0003בין דם טהור לדם טמא,\u0004 והרי שיש באשה גם דם טהור.","ודוחים ראיה זו: לפי הבנה זו שהכתוב עניינו בהבחנה שבין דם טמא לדם טהור, \u0003אלא מעתה\u0004 אף האמור בהמשך הכתוב \u0003\"בין נגע לנגע\", הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שכוונתו \u0003בין נגע טמא לנגע טהור? וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003הכי נמי\u0004 \u0005[\u0006אכן \u0005כך גם כן]\u0006 שבא הכתוב לחלק בין נגעים שונים — \u0003נגע טהור מי איכא\u0004 \u0005[האם יש]?\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שיש נגע שהוא טהור, והרי זה כאמור בפרשת הנגעים: \"וראה הכהן והנה כסתה הצרעת את כל בשרו וטהר את הנגע \u0003\"כולו הפך לבן טהור הוא\"\u0004 (ויקרא יג, יג) — הנגע \u0003ההוא\u0004 \u0005[אותו]\u0006 לא \"נגע\" הוא נקרא, אלא \u0003\"בוהק\" מקרי\u0004 \u0005[נקרא],\u0006 שאין דבר הנקרא נגע אם תפרש שאיננו טמא.","\u0003אלא\u0004 אם תסביר את האמור \"ובין נגע לנגע\", לענין ש\u0003בין נגעי אדם לנגעי בתים ולנגעי בגדים, ו\u0004אף שחלוקים הם בכמה דברים מכל מקום \u0003כולן טמאין,\u0004 אם כן \u0003הכא נמי\u0004 \u0005[כאן\u0006 בכתוב \"בין דם לדם\" \u0005גם כן]\u0006 תאמר כי הכוונה היא לענין ש\u0003בין דם נדה לדם זיבה, וכולן טמאין,\u0004 ואין איפוא להביא ראיה מכתוב זה שיש דם היוצא מן האשה שהוא טהור! ושואלים על דחיה זו: הרי בפרשה זו למדנו דינו של זקן ממרא, הוא החכם החולק על פסק דינם של הסנהדרין, כאמור: \"והאיש אשר יעשה בזדון לבלתי שמוע...\" (שם, יב).","ומעתה, יש לשאול \u0003האי מאי\u0004 \u0005[זו\u0006 ההשוואה בין הלשונות שבפסוק \u0005מה\u0006 טיבה\u0005]? בשלמא התם\u0006 \u0005[נניח שם]\u0006 בלשון \"ובין נגע לנגע\", אף שכל הנגעים טמאים הם, \u0003איכא לאפלוגי\u0004 \u0005[יש\u0006 מקום \u0005לחלק]\u0006 \u0003ב\u0004דינם של \u0003נגעי אדם, ו\u0004אפשר שנחלק הזקן הממרא עם חכמי הסנהדרין \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 \u0003ר' יהושע ורבנן\u0004 \u0005[וחכמים],\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במסכת נגעים\u0005]:\u0006 \u0003אם בהרת\u0004 ששיעורה כגריס היתה באדם \u0003קודם לשער\u0004 (שתי שערות) בצבע \u0003לבן\u0004 — הריהו \u0003טמא,\u0004 שהשער הלבן הריהו סימן טומאה. \u0003ו\u0004אולם \u0003אם\u0004 ה\u0003שער\u0004 ה\u0003לבן קודם לבהרת\u0004 — \u0003טהור.\u0004 \u0003ואם\u0004 \u0003ספק\u0004 הוא אם הבהרת קדמה לשער הלבן או להיפך — \u0003טמא.\u0004 זו דעת חכמים, \u0003ו\u0004אילו ר' \u0003יהושע אומר\u0004 שלא כחכמים, אלא \u0003כהה\u0004 (פקפק) בדבר. \u0003ואמר רבה\u0004 בדברי ר' יהושע שכך כוונתו שהוא \u0003כהה\u0004 על חכמים \u0003ו\u0004לדעתו \u0003טהור\u0004 הנגע.","וכמו כן אפשר לומר שנחלק הזקן ממרא על הסנהדרין \u0003ב\u0004דין \u0003נגעי בתים, כי הא פלוגתא\u0004 \u0005[כמו מחלוקת זו]\u0006 שנחלקו בה \u0003ר' אלעזר בר' שמעון ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת נגעים\u0005]:\u0006 \u0003ר' אלעזר בר' שמעון אומר: לעולם אין\u0004 נגע \u0003הבית טמא עד שיראה כשני גריסין על שני אבנים\u0004 הסמוכות זו לזו כשהן נתונות \u0003בשני כותלים\u0004 של הבית \u0003בקרן זוית.\u0004 ושיעורו של נגע הבית הזה \u0003ארכו כשני גריסין ורחבו כגריס.\u0004","ומסבירים, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעזר בר' שמעון?\u0004 — \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב אחד בפרשת נגעי בתים: \"ומראיהן שפל מן ה\u0003קיר\"\u0004 (ויקרא יד, לז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בתחילת אותו פסוק: \"והנה הנגע ב\u0003קירות\u0004 בית\", ומעתה \u0003איזהו קיר שהוא כשני קירות\u0004 — \u0003הוי אומר: זה קרן זוית.\u0004 ולדעת החולק על ר' אלעזר בר' שמעון אין צורך שיראה הנגע בשני כתלים בקרן זוית, על מנת שיטמא הבית.","וכמו כן אף \u0003בנגעי בגדים\u0004 יש מקום לומר כי נחלק הזקן ממרא עם חברי הסנהדרין \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 זו שנחלקו בה \u0003ר' יונתן בן אבטולמוס ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יונתן בן אבטולמוס אומר: מנין לפריחת בגדים,\u0004 שאם פרחה הצרעת בכל הבגד כולו, \u0003שהיא טהורה?\u0004","— \u0003נאמר \"קרחת\" ו\"גבחת\" בבגדים\u0004 (ויקרא יג, נה), \u0003ונאמר \"קרחת\" ו\"גבחת\" באדם\u0004 (שם מב),","\u0003מה להלן\u0004 באדם, הדין הוא שאם \u0003פרח בכולו\u0004 הריהו \u0003טהור\u0004 (שם יב) — \u0003אף כאן\u0004 בבגדים \u0003נמי\u0004 \u0005[גם כן]\u0006 אם \u0003פרח בכולו\u0004 הריהו \u0003טהור.\u0004 ואילו לשיטת חכמים בגד זה טמא.","\u0003אלא הכא\u0004 \u0005[כאן\u0006 בלשון \"בין דם לדם\"\u0005],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003דם טהור ליכא\u0004 \u0005[אין]\u0006 כלל, נמצא איפוא ש\u0003במאי פליגי\u0004 \u0005[במה חולקים]\u0006 הזקן ממרא וחברי הסנהדרין?! הרי שראיה היא זו מכתוב זה שיש דם טהור.","ולאחר שלמדנו כי יש דמים טהורים ודמים טמאים, יש לשאול: \u0003וממאי דהני\u0004 \u0005[וממה,\u0006 מנין \u0005שאלו]\u0006 הדמים שאינם אמורים במשנה הם ה\u0003טהורין והני\u0004 \u0005[ואלו]\u0006 האמורים במשנה הם הדמים ה\u0003טמאין? אמר ר'\u0004 \u0003אבהו:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויראו מואב\u0004 מנגד \u0003את המים אדמים כדם\"\u0004 (מלכים ב ג, כב). ללמדנו שצבע הדם הוא אדום. ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מתוך הכתוב הזה שצבע ה\u0003דם אדום הוא,\u0004 אם כן \u0003אימא\u0004 \u0005[אמור]\u0006 שרק הצבע שהוא \u0003אדום\u0004 כדם המכה יהיה נחשב כמראה הדם המטמא, \u0003ותו\u0004 \u0005[ועוד],\u0006 שאר המראות — \u0003לא\u0004 ייחשבו?","\u0003אמר ר'\u0004 \u0003אבהו: אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין הנדה: \"וטהרה ממקור \u0003דמיה\"\u0004 (ויקרא יב, ז), ולשון \"דמיה\" בצורת רבים בא להורות על שני דמים. ונאמר עוד בדין הנדה: \"ואיש אשר ישכב את אשה דוה... והיא גלתה את מקור \u0003דמיה\u0004 ונכרתו שניהם מקרב עמם\" (שם כ, יח), שאף כאן נאמר לשון זה בצורת רבים — \u0003הרי כאן\u0004 מקור שישנם \u0003ארבעה\u0004 דמים טמאים.","ושואלים על כך: \u0003והא אנן\u0004 \u0005[והרי אנו]\u0006 במשנתנו \u0003\"חמשה\u0004 דמים טמאים באשה\" \u0003תנן\u0004 \u0005[שנינו]!\u0006 \u0003אמר ר'\u0004 \u0003חנינא:\u0004 מראה \u0003שחור\u0004 — מראה \u0003אדום הוא, אלא שלקה\u0004 (שהתקלקל) צבעו, ונראה עתה שחור. והרי איפוא, אף שהמשנה מנתה חמישה מראות דמים, אינם אלא ארבעה.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 שאין הצבע השחור אלא צבע אדום שלקה: הדם ה\u0003שחור\u0004 המטמא — \u0003כחרת,\u0004 ואם עמוק (כהה) \u0003מכן\u0004 — \u0003טמא,\u0004 ואם \u0003דיהה\u0004 (בהיר) הוא מכצבע החרת, ו\u0003אפילו\u0004 הוא \u0003ככחול\u0004 — הרי זה \u0003טהור.\u0004 \u0003ו\u0004צבע \u0003שחור זה\u0004 של הדם, \u0003לא מתחלתו\u0004 בהיותו בגוף \u0003הוא משחיר, אלא\u0004 רק \u0003כשנעקר\u0004 מן הגוף \u0003הוא משחיר.\u0004 \u0003משל\u0004 (בדומה) \u0003לדם מכה\u0004 (פצע) שמתחילתו הריהו אדום, ואולם \u0003לכשנעקר\u0004 מן הגוף \u0003הוא משחיר.\u0004","שנינו במשנתנו כי \u0003בית שמאי אומרים\u0004 ש\u0003אף\u0004 הדם שמראהו \u0003כמימי תלתן\u0004 וכמימי בשר צלי הריהו בכלל הדמים הטמאים. ושואלים על כך: \u0003ולית להו\u0004 \u0005[ו\u0006כי \u0005אין להם,\u0006 לא מקובלת\u0005]\u0006 \u0003לבית שמאי\u0004 דרשה זו של ר' אבהו על המלים \u0003\"דמיה\" \"דמיה\"\u0004 שלמדנו ממנה ש\u0003הרי כאן\u0004 (במשמעות המילים הללו) רמוזים \u0003ארבעה\u0004 מיני דמים טמאים ולא יותר?!","ומתרצים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]: אכן\u0006 \u0003לית להו\u0004 \u0005[אין להם]\u0006 דרשה זו של ר' אבהו, וסבורים הם שיש יותר מארבעה מיני דמים טמאים. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003אית להו\u0004 \u0005[יש להם]\u0006 לבית שמאי כדרשה זו של ר' אבהו, ואולם \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר ר'\u0004 \u0003חנינא\u0004 בעניינו של הצבע השחור, שאין הוא צבע נוסף על הארבעה המנויים במשנה, כיון שה\u0003שחור\u0004 — \u0003אדום הוא, אלא שלקה,\u0004 אם כן, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ביחס למראה כמימי התלתן וכמימי בשר צלי, אפשר לומר שאין אלו מראות נוספים על הארבעה המנויים במשנה, אלא הם כשלעצמם אדומים, אלא ש\u0003מלקא\u0004 \u0005[ליקוי]\u0006 \u0003הוא דלקי\u0004 \u0005[שלקה]\u0006 הדם ונשתנה צבעו לשני אלה.","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003בית הלל\u0004 חולקים על שיטת בית שמאי זו, ו\u0003מטהרין\u0004 דם שמראהו כמימי תלתן וכמימי בשר צלי. ושואלים: אם כן שיטת בית הלל זו \u0003היינו\u0004 \u0005[זוהי]\u0006 שיטת \u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שבמשנתנו!","ומתרצים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה"],["אם יש \u0003לתלות\u0004 (לנהוג דין ספק) בדמים הללו שמראיהם כמימי תלתן או כמימי בשר צלי, או שהם טהורים לגמרי. שלדעת התנא הראשון שבמשנתנו ישנם חמשת מיני מראות דמים שדינם שהם טמאים ודאי, ואילו מראות אחרים, דוגמת שני מראות אלה, הם טמאים מספק. ואילו לשיטת בית הלל מראות אלה טהורים לגמרי.","חוץ ממראות הדמים הנזכרים במשנתנו נאמר בדין מראה הדם \u0003הירוק\u0004 (צהוב) שלדעת \u0003עקביא בן מהללאל\u0004 הריהו \u0003מטמא.\u0004 ושואלים: \u0003ו\u0004האם \u0003לית ליה\u0004 \u0005[אין לו,\u0006 לא מקובל\u0005]\u0006 \u0003לעקביא\u0004 בן מהללאל דרשה זו של ר' אבהו על המלים \u0003\"דמיה\" \"דמיה\"\u0004 שממנה למדים אנו כי \u0003הרי כאן ארבעה\u0004 מיני דמים המטמאים, והוא מוסיף מראה נוסף?","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שאכן \u0003לית ליה\u0004 \u0005[אין לו], ולדעתו יש יותר מארבעה מראות דמים המטמאים.\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר, כי אכן \u0003אית ליה\u0004 \u0005[יש לו,\u0006 סבור הוא\u0005]\u0006 כדרשה זו, ואולם \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר ר'\u0004 \u0003חנינא\u0004 ביחס לדם שמראהו \u0003שחור\u0004 שכשלעצמו \u0003אדום הוא, אלא שלקה, הכא נמי\u0004 \u0005[כאן,\u0006 לענין המראה הירוק, \u0005גם כן]\u0006 אפשר לומר שהדם שמראהו ירוק אינו אלא אדום ביסודו, אלא ש\u0003מלקא\u0004 \u0005[ליקוי]\u0006 \u0003הוא דלקי\u0004 \u0005[שלקה].\u0006","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003חכמים\u0004 נחלקו על עקביא בן מהללאל, ו\u0003מטהרין\u0004 מראה דם ירוק. ושואלים: שיטת חכמים זו \u0003היינו\u0004 \u0005[\u0006הרי \u0005זוהי]\u0006 בדיוק דעת ה\u0003תנא קמא\u0004 \u0005[הראשון\u0006 שבמשנתנו\u0005],\u0006 שהרי אף הוא לא מנה את הדם הירוק בין חמשת המראות המטמאים! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לענין אם יש \u0003לתלות\u0004 (לנהוג דין ספק) בדם הירוק. שלדעת התנא הראשון יש חמישה מיני מראות דמים שהם טמאים ודאי, ואילו מראות אחרים, דוגמת המראה הירוק הינם ספק טמאים. ואילו לשיטת חכמים הדם הירוק טהור לגמרי.","שנינו במשנתנו ש\u0003אמר ר'\u0004 \u0003מאיר\u0004 בדין הדם הירוק, ש\u0003אם אינו מטמא משום כתם,\u0004 הריהו נחשב כמשקה להכשיר זרעים שנפל עליהם לקבל טומאה.","ובהסבר דברי ר' מאיר \u0003אמר ר'\u0004 \u0003יוחנן: ירד\u0004 (הלך) \u0003ר' מאיר לשיטת עקביא בן מהללאל\u0004 בדין הדם הירוק, \u0003וטימא\u0004 משום נדה. \u0003ו\u0004מה שאמר במשנתנו, \u0003הכי קאמר להו לרבנן\u0004 \u0005[כך אמר להם\u0006 ר' מאיר \u0005לחכמים]:\u0006 \u0003נהי דהיכא דקא משכחת\u0004 \u0005[אמנם במקרה שהיא,\u0006 האשה, \u0005מוצאת]\u0006 \u0003כתם ירוק אמנא\u0004 \u0005[על הבגד]\u0006 אתם \u0003לא מטמאיתו\u0004 \u0005[אינכם מטמאים]\u0006 אותה בשל כך, שכיון שירוק הוא — יש להניח שלא בא מגופה. ואולם \u0003היכא דקחזיא\u0004 \u0005[במקרה שהיא רואה]\u0006 \u0003דם ירוק\u0004 ובודאי בא \u0003מגופה\u0004 — \u0003תטמא.\u0004","ושואלים על הסבר זה, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הלשון שאחז בה ר' מאיר במשנתנו \u0003\"אם אינו מטמא משום כתם, מטמא משום משקה\"\u0004 אינה מדוייקת, ו\"אם אינו מטמא משום כתם, מטמא \u0003משום רואה\" מבעיא ליה\u0004 \u0005[צריך היה לו]\u0006 לומר!","\u0003אלא הכי קאמר להו\u0004 \u0005[כך הוא,\u0006 ר' מאיר \u0005אמר להם\u0006 לחכמים\u0005]:\u0006 \u0003נהי היכא דקא חזיא\u0004 \u0005[אמנם במקרה שהיא רואה]\u0006 \u0003דם ירוק מעיקרא\u0004 \u0005[מלכתחילה]\u0006 — \u0003לא מטמאיתו\u0004 \u0005[אין אתם מטמאים]\u0006 אותה בכך, ואולם \u0003היכא דחזיא\u0004 \u0005[היכן,\u0006 במקרה \u0005שרואה]\u0006 \u0003דם אדום והדר חזיא\u0004 \u0005[וחוזרת ורואה]\u0006 \u0003דם ירוק\u0004 — \u0003תטמא, מידי דהוה\u0004 \u0005[כמו שהריהו]\u0006 בדין \u0003משקה זב וזבה,\u0004 שכל המשקים (נוזלי הגוף, כרוק וכשתן) היוצאים מן הזב ומן הזבה מטמאים, ויהא הדם הירוק היוצא ממנה כמותם.","\u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[חכמים]\u0006 הסבורים שהדם הירוק טהור הוא, לדעתם משקה הנדה המטמא זה שהוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003רוק.\u0004 ובאופן זה, \u0003מה רוק\u0004 דרך יריקתו מפה האדם הוא \u0003ש\u0004בתחילה \u0003מתעגל\u0004 (מצטבר לכדי כדור) \u0003ו\u0004לאחר מכן הריהו \u0003יוצא\u0004 אל מחוץ לגוף האדם היורקו, \u0003אף כל\u0004 משקה אחר המטמא הרי זה בדומה לכך, \u0003ש\u0004אף הוא \u0003מתעגל ויוצא.\u0004 \u0003והגדרה זו באה\u0004 \u0003לאפוקי האי\u0004 \u0005[להוציא,\u0006 למעט את \u0005זה]\u0006 הדם הירוק ש\u0003אין\u0004 הוא \u0003מתעגל ויוצא.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, שאין מטמא אלא המשקה שהוא כעין הרוק המתעגל ויוצא, \u0003שפיר קאמרי ליה רבנן\u0004 \u0005[יפה אמרו לו חכמים]\u0006 \u0003לר' מאיר,\u0004 ומדוע לשיטת ר' מאיר הריהו מטמא?","\u0003אלא\u0004 יש לומר הסבר אחר בדברי ר' מאיר לחכמים, ו\u0003הכי קאמר להו\u0004 \u0005[כך הוא אמר להם]:\u0006 \u0003להוי\u0004 \u0005[שיהיה]\u0006 דינו של הדם הירוק לפחות \u0003כמשקה\u0004 לענין \u0003להכשיר את הזרעים\u0004 עליהם הוא נפל, לקבל טומאה מכאן ולהבא, ומדוע לשיטתם הריהו טהור מכל וכל. \u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[חכמים]\u0006 סבורים כי \u0003בעי\u0004 \u0005[צריך]\u0006 כל דם הנחשב למשקה המכשיר לקבל טומאה שיהיה כעין הנאמר בכתוב \"ו \u0003דם חללים\u0004 ישתה\" (במדבר כג, כד), שהוא דם שהנפש יוצאת בו, \u0003ו\u0004אילו בדם הירוק \u0003ליכא\u0004 \u0005[אין כאן]\u0006 משום דם שהנפש יוצאת בו, ולכן אף אינו מכשיר לקבל טומאה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003שפיר קאמרי ליה רבנן\u0004 \u0005[יפה אמרו לו חכמים]\u0006 \u0003לר' מאיר!\u0004","\u0003אלא\u0004 יש לומר ש\u0003הכי קאמר להו\u0004 \u0005[כך הוא אמר להם]\u0006 ר' מאיר לחכמים: \u0003אלפוה\u0004 \u0005[למדוה]\u0006 להלכה זו שיהא הדם הירוק מכשיר את הזרעים לקבל טומאה, \u0003בגזרה שוה\u0004 זו, שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן,\u0006 בתיאור הרעיה\u0005]:\u0006 \u0003\"שלחיך פרדס רמונים\"\u0004 (שיר השירים ד, יג), שדם נדתה הזב ממנה מתואר בכתוב זה כ\"שלחיך\", \u0003ו\u0004בצורת לשון דומה \u0003כתיב התם\u0004 \u0005[נאמר שם]\u0006 בתיאור המים היורדים על הארץ: \"הנותן מטר על פני ארץ \u0003ושולח מים על פני חוצות\"\u0004 (איוב ה, י). הרי שדם הנדה דומה למים, וכמוהם הריהו מכשיר לטומאה.","\u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[חכמים]\u0006 אין להם גזירה שווה זו, משום ש\u0003אדם דן קל וחומר מעצמו, ואין אדם דן גזרה שוה מעצמו.\u0004","עוד שנינו במשנתנו ש\u0003ר' יוסי אומר\u0004 כי דם ירוק דינו \u0003לא כך\u0004 כשיטת עקביא בן מהללאל שהריהו מטמא, ולא כך כשיטת ר' מאיר שמכשיר הוא את הזרעים לקבל טומאה, אלא טהור הוא. ושואלים: \u0003היינו\u0004 \u0005[\u0006הרי \u0005זוהי]\u0006 דעת \u0003תנא קמא\u0004 \u0005[הראשון\u0006 שבמשנתנו, חכמים שבמשנתנו החולקים על עקביא בן מהללאל\u0005],\u0006 ומה השמיענו ר' יוסי? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]:\u0006 \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 — \u0003ר' יוסי\u0004 הוא, \u0003ו\u0004חשוב לדעת מיהו אומר השמועה, שכן \u0003כל האומר דבר\u0004 שמועה \u0003בשם אומרו\u0004 — \u0003מביא\u0004 בכך \u0003גאולה לעולם.\u0004","שנינו במשנתנו: \u0003איזהו\u0004 מראה \u0003אדום\u0004 המטמא באשה — \u0003כדם המכה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003כדם המכה? אמר רב יהודה, אמר שמואל: כדם שור שחוט.\u0004","ושואלים: אם כן, \u0003ולימא\u0004 \u0005[ויאמר]\u0006 התנא במפורש כי האדום הריהו \u0003כדם שחיטה!\u0004 ומשיבים: \u0003אי אמר\u0004 \u0005[היה אומר]\u0006 \u0003כדם שחיטה\u0004 — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהכוונה \u0003כ\u0004דם היוצא במשך \u0003כולה\u0004 \u0005[כל]\u0006 ה\u0003שחיטה,\u0004 והרי משתנה צבעו במשך השחיטה. לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 ש\u0003כדם המכה\u0004 הכוונה דווקא לדם הבא ב\u0003תחילת הכאה של סכין\u0004 השחיטה. ומביאים הגדרות אחרות למראה המתואר במשנתנו כ\"דם המכה\".","\u0003עולא אמר: כדם\u0004 הזב מ\u0003צפור חיה\u0004 שנפצעה. \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לבני בית המדרש\u0005]\u0006 שאלה זו: האם כשאמר עולא דם צפור \u0003חיה\u0004 נתכוין לכך שאינה מתה, \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 דם צפור \u0003שחוט\u0004 שאינו בכלל המראה המטמא. \u0003או דלמא\u0004 \u0005[שמא]\u0006 כשאמר דם צפור חיה התכוין לכך שהיא בריאה, ובא הדבר \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 דם צפור \u0003כחוש\u0004 שאינו בכלל המראה המטמא? לשאלה זו לא נמצא פתרון ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","הגדרה אחרת אמר החכם \u0003זעירי\u0004 שכך \u0003אמר ר'\u0004 \u0003חנינא: כדם\u0004 היוצא מ\u0003מאכולת\u0004 (כינה) \u0003של ראש\u0004 שנמעכה. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו להלן (בפרק שמיני) בדיני כתם דם הנמצא על בגד האשה, שאם \u0003הרגה\u0004 האשה \u0003מאכולת\u0004 ולאחר מכן נמצא כתם דם על בגדה או גופה — \u0003הרי זה תולה\u0004 כתם זה \u0003בה,\u0004 בכינה, שאומרים שמדם הכינה הוא זה, והריהי טהורה. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שמדובר בכינה \u0003דכוליה\u0004 \u0005[של כל]\u0006 מקום ב\u0003גופה,\u0004 בכל כינה שהרגה האשה, ולא רק בכינה של ראש, כדברי ר' חנינא! ודוחים: \u0003לא,\u0004 הכוונה דווקא בכינה שעל \u0003ראשה.\u0004","הגדרה אחרת ל\"דם המכה\" אמר החכם \u0003אמי ורדינאה\u0004 שכך \u0003אמר ר'\u0004 \u0003אבהו: כ\u0004צבע ה\u0003דם\u0004 הזב מן ה\u0003אצבע\u0004 ה\u0003קטנה של\u0004 \u0003היד, שנגפה\u0004 (נפצעה) \u0003ו\u0004לאחר מכן \u0003חייתה\u0004 (הבריאה), \u0003ו\u0004שוב \u0003חזרה ונגפה\u0004 (נפצעה). \u0003ולא\u0004 באצבעו \u0003של כל אדם, אלא\u0004 דווקא באצבעו \u0003של בחור שלא נשא אשה.\u0004 \u0003ו\u0004אף בזה לא אמרו בכל בחור, אלא \u0003עד\u0004 בן \u0003כמה\u0004 הוא — \u0003עד בן עשרים\u0004 שנה.","\u0003מיתיבי\u0004 \u0005[שואלים]\u0006 על כך ממה ששנינו באותה משנה שבדיני הכתמים: אם נפצעו בנה או בעלה, \u0003תולה\u0004 האשה המוצאת כתם דם על בגדה, את הכתם \u0003בבנה ובבעלה,\u0004 וטהורה היא. ויש לדון בדבר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שתולה היא \u0003בבנה\u0004 — \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה\u0006 אפשרות\u0005]\u0006 שיתקיימו בו בבנה כל אותם תנאים שאמר ר' אבהו (בחור שלא נשא אשה, והריהו בן פחות מעשרים שנה), \u0003אלא\u0004 שתולה היא ב\u0003בעלה\u0004 — \u0003היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה\u0006 אפשרות\u0005],\u0006 והרי בעלה כבר נשוי?","\u0003אמר רב נחמן בר יצחק: כגון שנכנסה לחופה, ולא נבעלה\u0004 עדיין. והרי הוא בעלה, ואולם נחשב הוא עדיין כבחור שלא נשא אשה לענין זה שאפשר לתלות בו את הכתם הנמצא.","\u0003רב נחמן אמר\u0004 הגדרה אחרת ל\"דם המכה\" שבמשנתנו: \u0003כדם הקזה\u0004 (דם שהנפש יוצאת בו עם השחיטה). \u0003מיתיבי\u0004 \u0005[שואלים]\u0006 על כך ממה ששנינו: \u0003מעשה\u0004 היה בכתם שנמצא בבגד אשה, \u0003ותלה ר'\u0004 \u0003מאיר\u0004"],["\u0003בקילור\u0004 (משחת תרופה לעינים), שנתעסקה בה לפני כן האשה, שלדעתו יכולה האשה לתלות את הכתם הנמצא בקילור זה. \u0003ו\u0004כן נמסר כי אף \u0003רבי\u0004 נהג כן הלכה למעשה ו\u0003תלה\u0004 את הכתם הנמצא \u0003בשרף\u0004 היוצא מעץ ה\u0003שקמה,\u0004 אם נתעסקה בו האשה קודם לכן. ויש לשאול: \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שתלו ר' מאיר ורבי את הכתם שצבעו אדום בקילור ובשרף השקמה משום שאף אלו צבעם \u0003אדום,\u0004 ואף שאין הוא אדום כל כך. הרי שאין מקום לכל ההבחנות הללו שהזכירו החכמים שיהא הצבע אדום ביותר!","ומתרצים: \u0003לא,\u0004 הכוונה שתלו ר' מאיר ורבי בקילור ובשרף השקמה את הכתם שצבעו הוא כ\u0003שאר\u0004 ה\u0003דמים\u0004 הנזכרים במשנתנו, שהם הדומים לקילור ולשרף השקמה.","ומסופר כי החכמים \u0003אמימר ומר זוטרא ורב אשי הוו יתבי קמיה אומנא\u0004 \u0005[היו יושבים לפני אומן,\u0006 מקיז דם\u0005]\u0006 לצורך הקזת דם לבריאות. \u0003שקלי ליה קרנא קמייתא\u0004 \u0005[נטלו לו\u0006 האומן דם ב\u0005קרן,\u0006 כלי ההקזה, פעם \u0005ראשונה]\u0006 \u0003לאמימר, חזייה\u0004 \u0005[ראה\u0006 אמימר \u0005אותו,\u0006 את הדם שבקרן\u0005],\u0006 ו\u0003אמר להו\u0004 \u0005[להם,\u0006 לחבריו\u0005]:\u0006 \u0003\"אדום\" דתנן\u0004 \u0005[ששנינו]\u0006 במשנתנו — הכוונה למראה דם \u0003כי האי\u0004 \u0005[כמו זה].\u0006 לאחר מכן \u0003שקלי ליה אחריתי\u0004 \u0005[נטלו לו\u0006 דם בקרן הקזה \u0005אחרת ],\u0006 ראה אמימר את הדם שבקרן זו, ו\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אשתני\u0004 \u0005[השתנה]\u0006 מראה דם ממראה הדם הקודם. \u0003אמר רב אשי\u0004 שישב אף הוא לפני מקיז הדם, וראה את שני הדמים הללו: כל חכם \u0003כגון אנא, דלא ידענא בין האי להאי\u0004 \u0005[אני, שאיני יודע\u0006 להבחין \u0005בין\u0006 דם \u0005זה ל\u0006דם \u0005זה]\u0006 — \u0003לא מבעי לי למחזי דמא\u0004 \u0005[איני צריך לראות דם]\u0006 ולפסוק בו אם טהור או טמא הוא.","שנינו במשנתנו בכלל מראות הדמים הטמאים מראה דם שהוא \u0003שחור כחרת.\u0004 \u0003אמר רבה בר רב הונא: חרת שאמרו\u0004 במשנתנו — הכוונה ל\u0003דיו.\u0004 ומציינים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 מראה \u0003שחור\u0004 — \u0003כחרת, ושחור שאמרו\u0004 — \u0003דיו.\u0004 ושואלים על ברייתא זו: מדוע כפלה לשונה בהגדרת השחור, שהוא כחרת ושחרת הריהו דיו, \u0003ולימא\u0004 \u0005[ויאמר]\u0006 בפשטות ששחור הכוונה ל\u0003דיו!\u0004 ומשיבים: \u0003אי אמר\u0004 \u0005[אם\u0006 התנא שבברייתא \u0005היה אומר]\u0006 רק שחור כ\u0003דיו\u0004 — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שהכוונה: \u0003כי פכחותא דדיותא\u0004 \u0005[כמו שקיפות הדיו,\u0006 חלקו העליון של נוזל הדיו שבקסת שהוא בהיר יותר\u0005],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בזה שאמר כחרת וכדיו, שהכוונה היא \u0003כי חרותא דדיותא\u0004 \u0005[כמו חרת,\u0006 \u0003שחרות\u0004 \u0005הדיו,\u0006 חלקו התחתון של נוזל הדיו שבקסת שהוא כהה יותר\u0005].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לבני בית המדרש\u0005]\u0006 שאלה זו: באיזה חרת אמרו חכמים, האם \u0003בלחה או ביבשתא\u0004 \u0005[ביבשה]?\u0006 ומביאים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה שנמסר שכך נהג הלכה למעשה \u0003ר' אמי,\u0004 שכאשר היה בא לפניו מראה דם שחור היה \u0003פלי קורטא דדיותא ובדיק\u0004 \u0005[מבקע חתיכת דיו יבש, ובודק]\u0006 \u0003בה.\u0004","שנינו במשנתנו במראה הדם השחור שאם היה עמוק (כהה) ממראה החרת — הרי זה דם טמא, ואם היה בהיר יותר — הרי זה דם טהור. ובענין זה \u0003אמר רב יהודה, אמר שמואל:\u0004 אשה שראתה דם שמראהו \u0003כקיר\u0004 (שעוה שחורה), או \u0003כדיו, ו\u0004כן שמראהו \u0003כענב\u0004 שחור — הריהי \u0003טמאה, וזוהי\u0004 הכוונה במה \u0003ששנינו\u0004 במשנתנו \u0003עמוק\u0004 יותר \u0003מכן\u0004 ממראה החרת — הריהי \u0003טמאה.\u0004 ועוד במראה הדם השחור, \u0003אמר ר'\u0004 \u0003אלעזר:\u0004 אשה שראתה דם שמראהו \u0003כזית,\u0004 או \u0003כזפת, ו\u0004כן \u0003כ\u0004מראה ה\u0003עורב\u0004 — הרי זה דם \u0003טהור, וזוהי ששנינו\u0004 במשנתנו בדם השחור שאם היה \u0003דיהה\u0004 (בהיר) יותר \u0003מכן\u0004 ממראה החרת — הרי זה דם \u0003טהור.\u0004","\u0003עולא אמר:\u0004 זה ששנינו במשנתנו שהדם השחור טמא, הכוונה שמראהו \u0003כלבושא\u0004 \u0005[מלבוש]\u0006 בני המקום \u0003סיואה\u0004 שהוא שחור מאד. ומסופר כי \u0003עולא אקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004עיר \u0003פומבדיתא.\u0004 \u0003חזייה לההוא טייעא\u0004 \u0005[ראה ערבי אחד]\u0006 שהיה \u0003לבוש לבושא אוכמא\u0004 \u0005[מלבוש\u0006 שצבעו \u0005שחור],\u0006 \u0003אמר\u0004 עולא \u0003להו\u0004 \u0005[להם]\u0006 לחכמי פומבדיתא: \u0003\"שחור\" דתנן\u0004 \u0005[ששנינו]\u0006 במשנתנו שדם הנמצא במראה זה הינו טמא — הכוונה לשחור \u0003כי האי\u0004 \u0005[כמו זה].\u0006 ומסופר כי כיון שרצו הכל שיהיה בידם דבר שצבעו שחור כעין השחור השנוי במשנתנו, \u0003מרטו מיניה פורתא פורתא\u0004 \u0005[תלשו ממנו,\u0006 מאותו בגד שחור, \u0005מעט מעט],\u0006 וכתשלום על אותו בגד שקרעוהו \u0003יהבו ביה ארבע מאה זוזי\u0004 \u0005[נתנו בו ארבע מאות זוזים].\u0006","\u0003ר' יוחנן אמר:\u0004 הדם השחור ששנינו במשנתנו שהריהו טמא, הכוונה שמראהו כ\u0003אלו\u0004 ה\u0003כלים\u0004 (בגדים) \u0003האוליירין\u0004 (של הבלנים) \u0003הבאים ממדינת הים\u0004 (מחוצה לארץ). ושואלים על כך: \u0003למימרא דאוכמי נינהו\u0004 \u0005[האם נאמר\u0006 מתוך דברי ר' יוחנן אלו, \u0005ששחורים הם]\u0006 כלים האוליירים, \u0003והאמר להו\u0004 \u0005[והרי אמר להם]\u0006 \u0003ר' ינאי\u0004 בצוואתו \u0003לבניו\u0004 קודם פטירתו: \u0003בני, אל תקברוני\u0004 כשאני לבוש \u0003לא בכלים שחורים ולא בכלים לבנים.\u0004 וטעם הדבר, לא בבגדים \u0003שחורים\u0004 — \u0003שמא אזכה\u0004 בדין לעולם הבא להיות יושב בין הצדיקים, \u0003ואהיה\u0004 נראה בבגדיי השחורים \u0003כאבל\u0004 הלבוש שחורים \u0003בין החתנים\u0004 הלבושים לבנים. ואל תקברוני בבגדים \u0003לבנים\u0004 — \u0003שמא לא אזכה\u0004 לבוא בין הצדיקים אלא בין הרשעים הלבושים שחורים, \u0003ואהיה\u0004 נראה בבגדיי הלבנים ביניהם \u0003כחתן בין האבלים.\u0004 \u0003אלא\u0004 הלבישוני בבגדי קבורתי \u0003בכלים האוליירין הבאים ממדינת הים.\u0004","\u0003אלמא\u0004 \u0005[מכאן]\u0006 נסיק כי \u0003לאו אוכמי נינהו\u0004 \u0005[לא שחורים הם]!\u0006 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמובן מדברי ר' ינאי שכלים האוליירים אינם שחורים — הרי זה \u0003ב\u0004בגד כ\u0003גלימא\u0004 (גלימה), ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שכלים האוליירים הינם שחורים — הרי זה \u0003ב\u0004בגד הניתן על חפץ כ\u0003פתורא\u0004 \u0005[שולחן]\u0006 ומיטה.","ואשר לאופן בדיקת חמשת מראות הדמים הנזכרים במשנתנו \u0003אמר רב יהודה, אמר שמואל: וכולם,\u0004 כל המראות הללו, לגווניהם השונים, \u0003אין בודקין\u0004 אותם \u0003אלא\u0004 כשהם נתונים \u0003על גבי מטלית\u0004 בד \u0003לבנה.\u0004 שרק באופן זה ניתן לבדוק במדוייק ולבחון את צבעם האמיתי של המראות הללו. \u0003אמר רב יצחק בר אבודימי:\u0004 אכן יש להניח את המראות הללו על גבי מטלית בד לבנה, \u0003ו\u0004אולם כדי להבחין במראה \u0003שחור\u0004 אם מראהו כחרת — יש להניחו \u0003על גבי\u0004 מטלית בד בצבע \u0003אדום.\u0004","\u0003אמר רב ירמיה מדפתי: ולא פליגי\u0004 \u0005[ואין\u0006 שמואל ורב יצחק בר אבודימי \u0005חלוקים],\u0006 שכן \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב יצחק בר אבודימי שצריך לבדוק על מטלית בד בצבע אדום — הרי זה דווקא \u0003ב\u0004מראה \u0003שחור,\u0004 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר שמואל שיש לעשות את הבדיקה על מטלית לבנה — הכוונה \u0003בשאר\u0004 ארבעת מראות ה\u0003דמים\u0004 הנזכרים במשנתנו. \u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על הסבר זה\u0005]\u0006 \u0003רב אשי: אי הכי\u0004 \u0005[אם כך],\u0006 \u0003לימא\u0004 \u0005[שיאמר]\u0006 \u0003שמואל\u0004 באופן זה: \"וכולם \u0003חוץ משחור\u0004 אין בודקים אותם אלא על גבי מטלית לבנה\"! \u0003אלא אמר רב אשי:\u0004 אכן בשחור גופיה קמיפלגי \u0005[עצמו הם חלוקים],\u0006 אם יש לבודקו על גבי מטלית לבנה או אדומה. \u0003אמר\u0004","\u0003עולא:\u0004 ב\u0003כולן,\u0004 בכל חמשת המראות הנזכרים במשנתנו — אם היה מראה הדם \u0003עמוק\u0004 (כהה) \u0003מכן,\u0004 מצבעם האמור במשנה — הריהו דם \u0003טמא,\u0004 ואם היה מראה הדם \u0003דיהה\u0004 (בהיר) \u0003מכן\u0004 — הריהו \u0003טהור,\u0004 והוא הדין בכל המראות, ו\u0003כ\u0004דינו של המראה ה\u0003שחור\u0004 הנזכר במפורש במשנה.","\u0003ו\u0004יש לשאול: אם כך \u0003אלא מאי שנא\u0004 \u0005[מה שונה\u0006 מיוחד\u0005]\u0006 מראה \u0003שחור\u0004 דווקא \u0003דנקט\u0004 \u0005[שאחז]\u0006 בו התנא להשמיענו דין הנוהג בכל המראות? — שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003הואיל ואמר ר'\u0004 \u0003חנינא\u0004 כי דם \u0003שחור\u0004 — \u0003אדום הוא, אלא שלקה, הילכך\u0004 (משום כך) יהא דינו ש\u0003אפילו\u0004 אם הוא \u0003דיהה מכן נמי ליטמא\u0004 \u0005[גם כן שיטמא],\u0006 לכן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 דין זה שאם דהה יותר מהשיעור הנזכר במשנה הרי הוא טהור, אף בשחור.","ואילו \u0003ר' אמי בר אבא אמר: ו\u0004ב\u0003כולן,\u0004 בכל חמשת המראות הנזכרים במשנתנו, אם היה המראה \u0003עמוק מכן\u0004 — \u0003טמא,\u0004 וכן אם היה \u0003דיהה מכן\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003טמא, חוץ משחור,\u0004 שאם הוא דהה מכאן — הרי הוא טהור. ומעתה יש לשאול: \u0003אלא מאי אהני שיעוריה דרבנן\u0004 \u0005[מה הועילו השיעורים\u0006 של המראות הנזכרים במשנתנו \u0005ש\u0006קבעו \u0005חכמים],\u0006 אם טמאים הם בין היו כהים יותר או בהירים יותר? — \u0003לאפוקי\u0004 \u0005[להוציא,\u0006 למעט\u0005]\u0006 בארבעת המראות מלבד שחור, מראה \u0003דיהה\u0004 של \u0003דיהה,\u0004 שכה בהיר הוא, עד שאינו בכלל הדם הטמא.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שכך \u0003רמי בר אבא אמר: ו\u0004ב\u0003כולן, עמוק מכן\u0004 — \u0003טהור, דיהה מכן\u0004 — \u0003טהור, חוץ משחור,\u0004 שאם מראה הדם כהה משיעור זה — הריהו טמא. \u0003ולהכי\u0004 \u0005[ולכך]\u0006 לקבוע את הגוון המדוייק של המראות, \u0003מהני שיעוריה דרבנן\u0004 \u0005[הועיל שיעורם של חכמים].\u0006","ואילו \u0003בר קפרא אמר: וכולן, עמוק מכן\u0004 — \u0003טמא, דיהה מכן\u0004 — \u0003טהור.\u0004 \u0003חוץ מ\u0004דם שמראהו כ\u0003מזג\u0004 (יין מזוג, המעורב מיין חי וממים), \u0003ש\u0004אם מראהו \u0003עמוק מכן\u0004 מהשיעור הנזכר במשנתנו — הריהו \u0003טהור,\u0004 וכן אם הוא \u0003דיהה מכן\u0004 — הריהו \u0003טהור,\u0004 שאינו מטמא אלא אם הוא בדיוק כגוון זה. ומסופר כי רצו לבדוק את \u0003בר קפרא,\u0004 ופעם אחת הביאו לפניו דם שמראהו כיין המזוג ו\u0003אדיהו ליה\u0004 \u0005[הבהירו אותו] —\u0006 \u0003ודכי\u0004 \u0005[וטיהר]\u0006 אותו בר קפרא. ופעם נוספת הביאו לפניו דם שמראהו כיין המזוג ו\u0003אעמיקו ליה\u0004 \u0005[והכהו אותו]\u0006 — \u0003ודכי\u0004 \u0005[וטיהר]\u0006 אותו. \u0003אמר\u0004 על כך \u0003ר' חנינא\u0004 בהתפעלות: \u0003כמה נפיש גברא דלביה כמשמעתיה\u0004 \u0005[גדול\u0006 הוא \u0005האיש אשר\u0006 הרגש לבו, המבחין בין מראות כה קרובים, הריהו \u0005כשמועתו,\u0006 כפי שפסק\u0005]!\u0006","\u0003ו\u0004עוד שנינו במשנתנו בין חמשת מראות הדם הטמא, מראה \u0003קרן\u0004 צמח ה\u0003כרכום\u0004 וכוונת הדברים לחלק הברור שבו. ובפירוש הדברים \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בברייתא: כמראה החלק ה\u0003לח\u0004 שבכרכום \u0003ולא\u0004 כמראה החלק ה\u0003יבש\u0004 שבו. ועוד בענין זה שנינו כמה ברייתות.","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003כ\u0004מראה החלק ה\u0003תחתון\u0004 שבצמח זה, ו\u0003לא כ\u0004מראה החלק ה\u0003עליון.\u0004 \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003כ\u0004מראה החלק ה\u0003עליון ולא כ\u0004מראה החלק ה\u0003תחתון.\u0004 \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003כ\u0004מראה החלק ה\u0003עליון, וכל שכן כ\u0004מראה החלק ה\u0003תחתון.\u0004 \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003כ\u0004מראה החלק ה\u0003תחתון, וכל שכן כ\u0004מראה החלק ה\u0003עליון.\u0004","\u0003אמר אביי\u0004 בפירוש הברייתות, שלא תסתורנה זו את זו: \u0003תלתא דרי\u0004 \u0005[שלוש שורות]\u0006 עלים יש בכרכום, זו למטה מזו, \u0003ו\u0004כל שורה ושורה \u0003תלתא טרפן הויין\u0004 \u0005[שלושה עלים הינם]\u0006 זה למטה מזה.","ועל מנת לבדוק מראה דם שהוא כמראה קרן כרכום המטמא, \u0003נקוט דרא מציעאה\u0004 \u0005[אחוז את השורה האמצעית]\u0006 שהיא השורה הראויה לבדוק בה, \u0003ו\u0004מאותה שורה אחוז את \u0003טרפא מציעתא\u0004 \u0005[העלה האמצעי]\u0006 \u0003בידך,\u0004 והשווה אותו למראה הדם, שאם דומים הם — הרי זה דם טמא. ואין ארבע הברייתות הללו סותרות זו את זו, שכן שתי הברייתות הראשונות עניינן שורת העלים הנבדקת, ובאופן זה: הברייתא האומרת \"כתחתון ולא כעליון\" — כוונתה לשורה האמצעית שהיא מתחת לעליונה, ולא לשורה שמעליה. והברייתא האומרת \"כעליון ולא כתחתון\" — כוונתה לשורה האמצעית שהיא מעל השורה התחתונה, ולא לשורה שמתחתיה. ואילו שתי הברייתות האחרות עניינן בעלים שבתוך השורה האמצעית, ובאופן זה: הברייתא האומרת \"כתחתון וכל שכן כעליון\" — כוונתה בעלה התחתון, וכל שכן בעלה שמעליו (העלה האמצעי) שבשורה האמצעית. ואילו הברייתא האומרת \"כעליון וכל שכן כתחתון\" — כוונתה כעלה העליון שבשורה האמצעית וכל שכן שכעלה שמתחתיו (העלה האמצעי). וחלק זה של קרן הכרכום הוא המכונה במשנתנו \"בברור שבו\".","ועוד בדיני מראה דם כמראה קרן כרכום נמסר: \u0003כי אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003ר' אבהו\u0004 לבדיקת דם שמראהו כקרן כרכום, \u0003אמר להו\u0004 \u0005[היה אומר להם]:\u0006 דווקא כקרן כרכום כשהיא נתונה עדיין \u0003בגושייהו\u0004 \u0005[בגושם],\u0006 שמחוברת עדיין לגוש האדמה בו גדלה \u0003שנינו\u0004 במשנתנו. שכן לאחר שנתלש ממקום גידולו, צבעו משתנה.","\u0003ו\u0004עוד שנינו במשנתנו בין מראות הדם הטמאים זה שהוא \u0003כ\u0004מראה \u0003מימי אדמה.\u0004 ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 הבודק מראה דם שמראהו \u0003כמימי אדמה\u0004 — הריהו \u0003מביא אדמה שמנה\u0004 (דשנה) \u0003מבקעת בית כרם, ומציף עליה מים,\u0004 וכמראה מים אלו כך הוא מראה דם המטמא, אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004 \u0003ר'\u0004 \u0003עקיבא אומר:\u0004 מביא אדמה \u0003מבקעת יודפת.\u0004 \u0003ר'\u0004 \u0003יוסי אומר:\u0004 מביא אדמה \u0003מבקעת סכני.\u0004 \u0003ר'\u0004 \u0003שמעון אומר:\u0004 מביא אדמה \u0003אף מבקעת גנוסר וכיוצא בהן.\u0004","ועוד בדין בדיקת דם שמראהו כמימי אדמה \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003וכמימי אדמה\u0004 — \u0003מביא אדמה שמנה מבקעת בית כרם, ומציף עליה מים\u0004 מועטים \u0003כ\u0004עובי \u0003קליפת השום\u0004 שהוא מועט ביותר. \u0003ו\u0004זאת מכיון ש\u0003אין שיעור למים, משום\u0004 ש\u0003אין שיעור ל\u0004כמות ה\u0003עפר\u0004 בו מתבצעת הבדיקה, שדי במעט אדמה ובמעט מים. \u0003ואין בודקין אותן\u0004 כאשר מימי האדמה הזו הינם \u0003צלולין\u0004 (שקופים), שכן אז אין מראה האדמה ניכר עוד במים אלו, \u0003אלא\u0004 כשהם \u0003עכורין\u0004 ממראה האדמה שבהם. ואם \u0003צללו\u0004 המים, ששקע העפר שבהם — \u0003חוזר ועוכרן, וכשהוא עוכרן.\u0004 \u0003אין עוכרן ביד אלא בכלי.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לבני בית המדרש\u0005]\u0006 שאלה זו: האם הכוונה במה ששנינו ש\u0003אין עוכרין אותן ביד אלא בכלי\u0004 היא ש\u0003לא לרמיה בידיה ולעכרינהו\u0004 \u0005[\u0006שלא ישליכנו את העפר \u0005אל תוך ידו ויעכרם\u0006 בעודו בידו\u0005],\u0006 \u0003אבל\u0004 כאשר נמצא העפר \u0003במנא\u0004 \u0005[בכלי],\u0006 \u0003כי עכר ליה בידיה\u0004 \u0005[כאשר עוכר אותו בידו]\u0006 — \u0003שפיר דמי\u0004 \u0005[\u0006כ\u0005יפה,\u0006 ראוי, \u0005נחשב\u0006 הדבר\u0005], או דלמא\u0006 \u0005[שמא]\u0006 הכוונה היא שאף בהיותם בתוך הכלי \u0003לא לעכרינהו בידיה\u0004 \u0005[לא יעכרם בידו],\u0006 \u0003אלא במנא\u0004 \u0005[בכלי]\u0006 יעכיר את המים?","ואומרים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו: \u0003כשהוא בודקן\u0004 למימי האדמה — \u0003אין בודקן אלא בכוס.\u0004 \u0003ו\u0004שואלים: \u0003עדיין תבעי\u0004 \u0005[תישאל]\u0006 \u0003לך:\u0004 אכן ה\u0003בדיקה\u0004 עצמה צריכה שתיעשה בהיות מימי האדמה \u0003בכוס,\u0004 ואולם ה\u0003עכירה במאי\u0004 \u0005[במה]\u0006 נעשית, האם דווקא בכלי, או שאפשר לעשותה אף ביד? ומסכמים: \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה בלא פתרון.","ובענין זה של בדיקה במימי אדמה, נמסר: \u0003כי אתו לקמיה\u0004 \u0005[כאשר באו לפני]\u0006 \u0003רבה בר אבוה\u0004 לבדוק במימי אדמה, \u0003אמר להו\u0004 \u0005[היה אומר להם]:\u0006 דווקא אם הבדיקה נעשית \u0003במקומה\u0004 (במקום שממנו נלקחה האדמה) \u0003שנינו,\u0004 אבל אם נלקחה האדמה למקום אחר — שוב אין בודקים בה. ועוד נמסר כי \u0003ר' חנינא פלי קורטא דגרגשתא ובדיק ביה\u0004 \u0005[היה מפורר גוש אדמה ובודק בו]\u0006 בלא לערבו במים. ומסופר, \u0003לייט עליה\u0004 \u0005[היה מקלל עליו,\u0006 על הנוהג כן\u0005]\u0006 \u0003ר' ישמעאל בר' יוסי\u0004 שייענש \u0003ב\u0004מחלת ה\u0003אסכרה.\u0004"],["והסביר ר' ישמעאל בר' יוסי שאמנם \u0003ר' חנינא הוא\u0004 שרשאי לבדוק כך, משום \u0003דחכים\u0004 \u0005[שחכם]\u0006 הוא, ואולם \u0003כולי עלמא\u0004 \u0005[כל העולם,\u0006 שאר בני האדם\u0005]\u0006 — \u0003לאו חכימי הכי\u0004 \u0005[אינם חכמים כך],\u0006 להבחין בבדיקה כמותו.","ועוד בענין חכמת ר' חנינא בבדיקת מראות דמים, \u0003אמר ר'\u0004 \u0003יוחנן: חכמתא\u0004 \u0005[חכמתו]\u0006 של \u0003ר' חנינא גרמא\u0004 \u0005[גרמה]\u0006 \u0003לי דלא אחזי דמא\u0004 \u0005[שלא אראה דמים]\u0006 לבודקם. שכן כאשר בדקתי בדמים ו\u0003מטמינא\u0004 \u0005[הייתי מטמא]\u0006 — הוא היה \u0003מטהר,\u0004 וכאשר \u0003מטהרנא\u0004 \u0005[הייתי מטהר]\u0006 — הוא היה \u0003מטמא.\u0004 ובאופן שונה \u0003אמר ר'\u0004 \u0003אלעזר: ענוותנותא\u0004 \u0005[ענוותנותו]\u0006 של \u0003ר' חנינא\u0004 היא ש\u0003גרמא\u0004 \u0005[גרמה]\u0006 \u0003לי דחזאי דמא\u0004 \u0005[שאראה דמים],\u0006 שכך אמרתי לעצמי: \u0003ומה ר'\u0004 \u0003חנינא\u0004 ש\u0003ענותן הוא\u0004 — \u0003מחית נפשיה\u0004 \u0005[הוריד,\u0006 הכניס \u0005עצמו]\u0006 \u0003לספק וחזי\u0004 \u0005[וראה]\u0006 מראות דמים וקבע את דינם, \u0003אנא\u0004 \u0005[אני]\u0006 שאיני ענוותן כמותו — \u0003לא אחזי\u0004 \u0005[אראה]?!\u0006","ועוד מדברי חכמים על עצמם בענין בדיקת מראות דמים, \u0003אמר ר'\u0004 \u0003זירא: טבעא\u0004 \u0005[טבע]\u0006 בני האדם של \u0003בבל גרמא\u0004 \u0005[גרם]\u0006 \u0003לי\u0004 ש\u0003לא חזאי דמא\u0004 \u0005[אראה דמים],\u0006 \u0003דאמינא\u0004 \u0005[ש\u0006כך \u0005אמרתי]\u0006 לעצמי: אפילו \u0003בטבעא\u0004 \u0005[בטבע]\u0006 בני האדם \u0003לא ידענא\u0004 \u0005[איני יודע],\u0006 \u0003בדמא ידענא\u0004 \u0005[בדם יודע אני]?!\u0006","ושואלים על כך: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מתוך דברי ר' זירא אלו \u0003דבטבעא תליא מלתא\u0004 \u0005[שבטבע\u0006 האדם תלוי הדבר\u0005],\u0006 שמשתנה צבע הדם לפי טבע האדם, ולכן מי שאינו יודע בטבע האדם, אל יראה דמים, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה הוא\u0004 ש\u0003ידע בטבעא\u0004 \u0005[בטבע]\u0006 האדם \u0003ולא ידע\u0004 להבחין \u0003בדמא\u0004 \u0005[בדמים]\u0006 השונים! ומשיבים: \u0003כל שכן קאמר\u0004 \u0005[הוא,\u0006 ר' זירא \u0005אמר\u0006 לעצמו\u0005]:\u0006 \u0003ומה רבה\u0004 ש\u0003ידע בטבעא\u0004 \u0005[בטבע]\u0006 האדם — \u0003לא חזא דמא\u0004 \u0005[לא ראה דמים],\u0006 \u0003ואנא\u0004 \u0005[ואני]\u0006 שאיני יודע בטבע — \u0003אחזי\u0004 \u0005[אראה]?!\u0006","ומסופר, \u0003עולא אקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004עיר \u0003פומבדיתא\u0004 שבבבל מקום מגורי רב יהודה. \u0003אייתו לקמיה דמא\u0004 \u0005[הביאו לפניו דם]\u0006 לבדיקה, \u0003ולא חזא\u0004 \u0005[ולא ראה].\u0006 ש\u0003אמר\u0004 לעצמו: \u0003ומה ר'\u0004 \u0003אלעזר דמרא דארעא דישראל הוה\u0004 \u0005[שאדונה של ארץ ישראל היה],\u0006 \u0003כי מקלע לאתרא\u0004 \u0005[כאשר הזדמן למקום]\u0006 בו גר \u0003ר' יהודה\u0004 — \u0003לא חזי דמא\u0004 \u0005[לא ראה דמים],\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 — \u0003אחזי\u0004 \u0005[אראה]?!\u0006","\u0003ו\u0004מסבירים: \u0003אמאי קרו ליה\u0004 \u0005[מדוע קראו לו,\u0006 לר' אלעזר\u0005]\u0006 \u0003\"מרא דארעא דישראל\"\u0004 \u0005[אדונה של ארץ ישראל]?\u0006 — שכך היה מעשה \u0003דההיא אתתא דאייתא דמא לקמיה\u0004 \u0005[שאשה אחת שהביאה דם לפני]\u0006 \u0003ר' אלעזר\u0004 לבדיקה. \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003ר' אמי קמיה\u0004 \u0005[לפניו].\u0006 ראה ר' אמי ש\u0003ארחיה\u0004 \u0005[הריחו]\u0006 ר' אלעזר לדם זה, ו\u0003אמר לה\u0004 לאשה השואלת אותו: \u0003האי\u0004 \u0005[זה]\u0006 \u0003דם חימוד הוא\u0004 שנתאותה לבעלה וראתה דם מחמת התאווה ולא דם נדה. ומסופר כי \u0003בתר דנפקה, אטפל לה\u0004 \u0005[אחר שיצאה\u0006 מלפני ר' אלעזר, \u0005הצטרף אליה]\u0006 \u0003ר' אמי,\u0004 ושאל כיצד ראתה אכן דם זה. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003בעלי היה בדרך וחמדתיו.\u0004 \u0003קרי עליה\u0004 \u0005[היה\u0006 ר' אמי \u0005קורא עליו,\u0006 על ר' אלעזר\u0005]\u0006 את הכתוב: \u0003\"סוד ה'\u0004 \u0003ליראיו\u0004 ובריתו להודיעם\" (תהלים כה, יד), שהקדוש ברוך הוא מגלה ליראיו דברים נסתרים.","ועוד מסופר כי \u0003אפרא הורמיז אמיה\u0004 \u0005[אמו]\u0006 של \u0003שבור מלכא\u0004 \u0005[המלך]\u0006 \u0003שדרה דמא לקמיה\u0004 \u0005[שלחה דם לפני]\u0006 \u0003רבא\u0004 לבדיקה, שרצתה להתגייר והיתה שומרת דיני נדה, ובאותה שעה \u0003הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003רב עובדיה קמיה\u0004 \u0005[לפניו].\u0006 ראה רב עובדיה ש\u0003ארחיה\u0004 \u0005[הריחו]\u0006 רבא לדם זה, ו\u0003אמר לה: האי\u0004 \u0005[זה]\u0006 \u0003דם חימוד הוא.\u0004 \u0003אמרה ליה לבריה\u0004 \u0005[לו לבנה]:\u0006 \u0003תא חזי\u0004 \u0005[בוא ראה]\u0006 \u0003כמה חכימי יהודאי\u0004 \u0005[חכמים\u0006 הם \u0005היהודים]\u0006 שהרי כפי שאמר כך אכן היה! \u0003אמר לה: דלמא\u0004 \u0005[שמא]\u0006 היה רבא באותה שעה \u0003כסומא בארובה\u0004 היוצא ממנה אף שאינו יודע ורואה את דרך היציאה, שבמקרה זיהה דם זה, ואין זה מחכמתו.","ומסופר ש\u0003הדר שדרה ליה שתין מיני דמא\u0004 \u0005[חזרה שלחה לו\u0006 אפרא הורמיז לרבא, \u0005ששים מיני דמים\u0006 שונים, טמאים וטהורים\u0005],\u0006 \u0003וכולהו אמרינהו\u0004 \u0005[וכולם אמרם\u0006 רבא כפי שהם\u0005].\u0006 ומסופר: \u0003ההוא בתרא\u0004 \u0005[אותו\u0006 דם \u0005אחרון]\u0006 ששלחה אפרא הורמיז \u0003דם כנים הוה\u0004 \u0005[היה],\u0006 \u0003ולא ידע\u0004 רבא מה טיבו. \u0003אסתייע מילתא\u0004 \u0005[הסתייע הדבר]\u0006 \u0003ושדר\u0004 \u0005[ושלח]\u0006 \u0003לה\u0004 כמתנה \u0003סריקותא דמקטלא כלמי\u0004 \u0005[מסרק ההורג כינים].\u0006 \u0003אמרה: יהודאי\u0004 \u0005[יהודים],\u0006 \u0003בתווני דלבא יתביתו\u0004 \u0005[בחדרי הלב,\u0006 בתוך תוכו של האדם, \u0005אתם יושבים]!\u0006","ועוד בדברי חכמים על עצמם בענין בדיקת דמים, \u0003אמר רב יהודה: מרישא הוה חזינא דמא\u0004 \u0005[בתחילה הייתי רואה דמים]\u0006 לבדיקה, ואולם \u0003כיון\u0004 ש\u0003אמרה לי אמיה\u0004 \u0005[אמו]\u0006 של \u0003יצחק ברי\u0004 \u0005[בני],\u0006 כלומר, אשתי שכך נוהגת היא: \u0003האי טיפתא קמייתא לא מייתינן לה קמייהו דרבנן\u0004 \u0005[טפה ראשונה זו\u0006 של דם שאני רואה \u0005אין אני מביאתה לפני חכמים]\u0006 \u0003משום דזהימא\u0004 \u0005[שמלוכלכת]\u0006 היא — \u0003לא חזינא\u0004 \u0005[אין אני רואה]\u0006 עוד דם לבדיקה, שהרי ייתכן שלטיפה הראשונה היה מראה טמא ומחמת חשש זה אינני בודק דמים.","ואולם \u0003בין\u0004 דם שראתה האשה היולדת לאחר שנסתיימו ימי הטוהר (ארבעים — ליולדת זכר ושמונים — ליולדת נקבה) ה\u0003טמאה\u0004 בו \u0003ל\u0004דם שרואה היולדת בתוך ימי הטוהר שעדיין היא \u0003טהורה\u0004 בו, \u0003ודאי חזינא\u0004 \u0005[רואה אני],\u0006 וקובע לפי צבעו אם דם טמא או טהור הוא, שהרי ברור שדם הוא זה.","ומסופר כי \u0003ילתא\u0004 אשת ר' נחמן \u0003אייתא דמא לקמיה\u0004 \u0005[הביאה דם\u0006 לבדיקה \u0005לפני]\u0006 \u0003רבה בר בר חנה\u0004 — \u0003וטמי לה\u0004 \u0005[וטימא אותה].\u0006 \u0003הדר אייתא\u0004 \u0005[חזרה הביאה]\u0006 את הדם \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה\u0004 — \u0003ודכי לה\u0004 \u0005[וטיהר אותה].\u0006","ושואלים על כך: \u0003והיכי עביד הכי\u0004 \u0005[וכיצד עשה\u0006 רב יצחק בנו של רב יהודה \u0005כך]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003חכם שטימא\u0004 דבר שבא לפניו לדין — שוב \u0003אין חברו רשאי לטהר\u0004 אותו דבר. ובדומה לכך, אם החכם הראשון \u0003אסר\u0004 — שוב \u0003אין חבירו רשאי להתיר!\u0004","ומשיבים: \u0003מעיקרא טמויי הוה מטמי לה\u0004 \u0005[בתחילה\u0006 אכן אף רב יצחק בנו של רב יהודה \u0005טימא אותה],\u0006 ואולם \u0003כיון\u0004 ש\u0003אמרה ליה\u0004 \u0005[לו]\u0006 ילתא לרב יצחק בנו של רב יהודה ש\u0003כל יומא\u0004 \u0005[יום]\u0006 בכל פעם שהביאה לרבה בר בר חנה דם לבדיקה, הוא \u0003הוה מדכי\u0004 \u0005[היה מטהר]\u0006 \u0003לי\u0004 בדם \u0003כי האי גונא\u0004 \u0005[כעין זה],\u0006 \u0003ו\u0004רק \u0003האידנא\u0004 \u0005[בזמן זה]\u0006 \u0003הוא\u0004 טימא אותה, משום \u0003דחש בעיניה\u0004 \u0005[שחושש,\u0006 סובל \u0005בעיניו].\u0006 ומששמע כך רב יצחק בנו של רב יהודה, \u0003דכי לה\u0004 \u0005[טיהר אותה].\u0006","ושואלים: \u0003ומי מהימני\u0004 \u0005[והאם נאמנים]\u0006 אנשים לטעון כן? ומשיבים: \u0003אין\u0004 \u0005[כן].\u0006 ומביאים ראיה לדבר, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 כך ברייתא\u0005]:\u0006 \u0003נאמנת אשה לומר \"כזה\u0004 (כמראה זה) \u0003ראיתי ואבדתיו\u0004 לעד הבדיקה\".","ובענין זה של נאמנות אשה לטעון כך, \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לבני בית המדרש\u0005]\u0006 שאלה זו: במקרה שאשה אומרת לחבירתה המראה לה דם \"מראה \u0003כזה טיהר איש פלוני חכם\",\u0004 האם נאמנת היא בכך, או לא?","ומביאים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003נאמנת אשה לומר \"כזה ראיתי ואבדתיו\"\u0004 והרי שאשה בקיאה ונאמנת במראה דם! ודוחים את הראיה: אין זו ראיה, שהרי \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 — \u0003דליתיה לקמה\u0004 \u0005[שאינו לפניה]\u0006 ולכן הקלו בה.","ומביאים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה שמסופר ש\u0003ילתא אייתא דמא לקמיה\u0004 \u0005[הביאה דם לפני]\u0006 \u0003רבה בר בר חנה\u0004 לבדיקה, \u0003וטמי לה\u0004 \u0005[וטימא אותה].\u0006 חזרה והביאה אותו הדם \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה\u0004 — \u0003ודכי לה\u0004 \u0005[וטיהר אותה].\u0006 \u0003ו\u0004יש לשאול: \u0003היכי עביד הכי\u0004 \u0005[כיצד עשה כך\u0006 רב יצחק בנו של רב יהודה\u0005]\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003חכם שטימא\u0004 — \u0003אין חבירו רשאי לטהר,\u0004 וככל שדנו בדבר למעלה,","\u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 בהסבר לדבר כי בתחילה אכן רב יצחק בנו של רב יהודה \u0003טמויי\u0004 \u0005[לטמא]\u0006 \u0003הוה מטמי לה\u0004 \u0005[היה מטמא אותה],\u0006 ואולם \u0003כיון\u0004 ש\u0003אמרה ליה\u0004 \u0005[לו]\u0006 ש\u0003כל יומא\u0004 \u0005[יום],\u0006 בכל פעם שהיתה מביאה לרבה בר בר חנה דם לראייה, \u0003מדכי לה כי האי גונא\u0004 \u0005[מטהר אותה\u0006 בדם \u0005כעין זה],\u0006 \u0003ו\u0004רק \u0003האידנא\u0004 \u0005[הפעם]\u0006 \u0003הוא\u0004 שטימא אותה משום ש\u0003חש בעיניה\u0004 \u0005[בעיניו]\u0006 — \u0003הדר דכי לה\u0004 \u0005[חזר\u0006 רב יצחק בנו של רב יהודה ו\u0005טיהר אותה],\u0006 ויש להסיק איפוא: \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מהימנא לה\u0004 \u0005[נאמנת היא]\u0006 האשה בכך!","ודוחים: אין להביא ראיה מכאן, שכן \u0003רב יצחק בר יהודה\u0004 שטיהר אותה — \u0003אגמריה\u0004 \u0005[על לימודו]\u0006 \u0003סמך\u0004 בזה שטיהרה. ואולם לא רצה לפסוק לה כן בתחילה, משום כבודו של רבה בר בר חנה שטימא אותה. ואולם משעה ששמע את דבריה אלו, פסק לה כפי שסבר. ואין איפוא ראיה מכאן כי נאמנת האשה בדבריה במקום שבו יש ספק בדינה.","ועוד מסופר כי \u0003רבי ראה דם בלילה\u0004 — \u0003וטימא\u0004 אותו, וחזר ו\u0003ראה\u0004 אותו שוב \u0003ביום\u0004 לאחר שהתייבש — \u0003וטיהר\u0004 אותו, ושוב חזר ו\u0003המתין שעה אחת\u0004 וראהו פעם נוספת — ו\u0003חזר וטימא\u0004 אותו. \u0003אמר: אוי לי שמא טעיתי!\u0004","ותוהים על כך: מדוע אמר רבי \u0003\"שמא טעיתי\",\u0004 והלא \u0003ודאי טעה! דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003לא יאמר חכם \"אילו היה לח\u0004 — \u0003היה ודאי טמא\",\u0004","\u0003אלא\u0004 כך \u0003אמר\u0004 רבי: כלל הוא זה ש\u0003אין לו לדיין אלא מה שעיניו רואות,\u0004 ולכן \u0003מעיקרא אחזקיה\u0004 \u0005[בתחילה החזיקו]\u0006 רבי את הדם הזה \u0003בטמא, כיון דחזא לצפרא דאשתני\u0004 \u0005[שראה בבוקר שהשתנה]\u0006 צבעו \u0003אמר (ליה\u0004 \u0005[לו]\u0006\u0003): ודאי טהור הוה\u0004 \u0005[היה]\u0006 אף בלילה \u0003ו\u0004אולם \u0003בלילה\u0004 סברתי ש\u0003הוא\u0004 טמא מפני ש\u0003לא אתחזי שפיר\u0004 \u0005[לא נראה יפה].\u0006 ואולם \u0003כיון דחזא דהדר אשתני\u0004 \u0005[שראה\u0006 לאחר המתנה קצרה \u0005שחזר\u0006 הדם ו\u0005השתנה],\u0006 \u0003אמר\u0004 רבי: \u0003האי\u0004 \u0005[\u0006דם \u0005זה]\u0006 \u0003טמא הוא, ומפכח\u0004 \u0005[ומתבהר]\u0006 \u0003הוא דקא מפכח ואזיל\u0004 \u0005[שהוא הולך ומתבהר].\u0006","ועוד בדרכי ראיית הדם על ידי חכמים מסופר כי \u0003רבי בדיק\u0004 \u0005[היה בודק]\u0006 מראה דמים \u0003לאור הנר.\u0004 \u0003ר'\u0004 \u0003ישמעאל בר' יוסף בדיק\u0004 \u0005[היה בודק]\u0006 \u0003ביום המעונן ביני עמודי\u0004 \u0005[בין עמודי\u0006 בית המדרש\u0005].\u0006 \u0003אמר רב אמי בר שמואל: וכולן אין בודקין אותן אלא בין חמה לצל.\u0004 \u0003רב נחמן אמר\u0004 בשם \u0003רבה בר אבוה:\u0004 עומד הבודק \u0003ב\u0004מקום בו מאיר אור ה\u0003חמה, ובצל ידו,\u0004 שמסוכך בידו על הדם הנבדק, ומטיל עליו צל, שכך נראה הדבר ביותר.","\u0003ו\u0004עוד שנינו במשנתנו בין המראות הטמאים: \u0003כ\u0004יין ה\u0003מזוג\u0004 שהוא נמזג מ\u0003שני חלקים\u0004 מים וחלק אחד יין, מן היין השרוני. ובענין זה \u0003תנא\u0004 \u0005[שנה]\u0006 החכם:"],["יין המזוג \u0003השרוני\u0004 לענין בדיקת דמים \u0003נידון כ\u0004יין ה\u0003כרמלי\u0004 ה\u0003חי, ולא\u0004 ה\u0003מזוג,\u0004 ה\u0003חדש\u0004 — \u0003ולא\u0004 ה\u0003ישן.\u0004","ועוד בענין זה \u0003אמר רב יצחק בר אבודימי: וכולן,\u0004 כל מראה הדמים הנראים כיין המזוג, \u0003אין בודקין אותן אלא בכוס טבריא פשוט.\u0004 ובהסבר הדבר \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003אמר אביי:\u0004 כוס רגילה \u0003של כל העולם כולו,\u0004 עשויה באופן כזה שהכוס ה\u0003מחזיק\u0004 (הנועד להכיל) \u0003לוג\u0004 יין בתוכו — \u0003עושין אותו מ\u0004כמות חומר שמשקלה \u0003מנה\u0004 (מאה), ואילו הכוס שנועדה להכיל בתוכה \u0003שני לוגין\u0004 — \u0003עושין אותו ממאתים.\u0004 ולעומת זאת, \u0003כוס טבריא פשוט, אפילו מחזיק שני לוגין\u0004 — \u0003עושין אותו ממנה.\u0004 \u0003ו\u0004משום כך, \u0003איידי דקליש\u0004 \u0005[כיון שקלוש]\u0006 החומר ממנו נעשית הכוס — שקופה היא יותר ולכך \u0003ידיע ביה\u0004 \u0005[נודע,\u0006 ניכר \u0005בו]\u0006 מידת האדמומית שבמראה היין שבתוכו \u0003טפי\u0004 \u0005[יותר],\u0006 ולכן רק בו יש לבדוק.","","האשה המעוברת \u0003המפלת חתיכה\u0004 של בשר ללא צורה מוגדרת, מה דינה? \u0003אם יש עמה\u0004 עם החתיכה הזו \u0003דם\u0004 — הרי האשה \u0003טמאה\u0004 טומאת נדה, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — הריהי \u0003טהורה,\u0004 שאינה נדה ואינה נחשבת כיולדת בשל הפלת חתיכה זו. \u0003ר' יהודה אומר: בין כך\u0004 (שיש עם החתיכה דם), \u0003ובין כך\u0004 (שאין עמה דם) — הרי האשה \u0003טמאה\u0004 טומאת נדה, שבודאי היה עמה דם ואבד. \u0003המפלת\u0004 דבר שצורתו \u0003כמין קליפה,\u0004 או \u0003כמין שערה,\u0004 או \u0003כמין עפר,\u0004 או \u0003כמין יבחושין\u0004 (ממיני היתושים), והיה מראיהם של כל אלו \u0003אדומים,\u0004 מה דינה? \u0003תטיל\u0004 אותם \u0003למים, אם נמוחו\u0004 (נתמסמסו) — דם הוא זה, והריהי \u0003טמאה\u0004 טומאת נדה, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003טהורה.\u0004 ועוד, \u0003המפלת\u0004 חתיכה שצורתה \u0003כמין דגים,\u0004 או כ\u0003חגבים,\u0004 או כ\u0003שקצים ורמשים,\u0004 מה דינה? \u0003אם יש עמהם דם\u0004 — \u0003טמאה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003טהורה.\u0004 \u0003המפלת\u0004 דבר שצורתו כ\u0003מין בהמה\u0004 או כמין \u0003חיה ו\u0004כן כמין \u0003עוף, בין\u0004 אלו בעלי חיים \u0003טמאין בין טהורין, אם\u0004 יש בו סימני \u0003זכר\u0004 — הרי זו טמאה ו\u0003תשב\u0004 עליו ימי טומאה וימי טהרה, כדין \u0003ל\u0004יולדת \u0003זכר, ואם\u0004 יש בחתיכה זו סימני \u0003נקבה\u0004 — הרי זו טמאה, ו\u0003תשב\u0004 ימי טומאה וימי טהרה, כדינים הנוהגים \u0003ל\u0004יולדת \u0003נקבה.\u0004","","","","\u0003ואם אין ידוע\u0004 מינו של הולד שהפילה — הרי זו טמאה ו\u0003תשב לזכר ולנקבה,\u0004 שנוהגת לחומרה כיולדת זכר וכיולדת נקבה, והרי היא איפוא טמאה שבועיים (כיולדת נקבה), ונוהגת ימי טהרה שלושים ושלושה ימים בלבד (כיולדת זכר), אלה \u0003דברי ר'\u0004 \u0003מאיר, וחכמים אומרים: כל שאין בו מצורת אדם\u0004 — \u0003אינו\u0004 נחשב \u0003ולד\u0004 לענין טומאת לידה.","שנינו במשנתנו שאשה המפלת חתיכה שאין עמה דם, חכמים מטמאים אותה ור' יהודה מטהר. ובהסבר מחלוקתם \u0003אמר רב יהודה, אמר שמואל: לא טימא ר'\u0004 \u0003יהודה\u0004 במפלת חתיכה שאין עמה דם משום טומאת לידה, \u0003אלא\u0004 משום שנחשבת החתיכה עצמה לדם, ודין זה הוא רק \u0003בחתיכה\u0004 שהמראה שלה הוא כמראה \u0003של ארבעת מיני דמים\u0004 טמאים, \u0003אבל\u0004 המפלת חתיכה שהמראה שלה כ\u0003של שאר מיני דמים\u0004 — אף ר' יהודה מודה שהריהי \u0003טהורה.\u0004 \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 שיש להעמיד את מחלוקת ר' יהודה וחכמים באופן אחר: המפלת חתיכה שאין עמה דם, שהמראה שלה הוא כמראה \u0003של ארבעת מיני דמים\u0004 — לא נחלקו בדבר, ול\u0003דברי הכל,\u0004 ואף לשיטת חכמים, הריהי \u0003טמאה.\u0004 וכן במקרה שהמראה של החתיכה הוא כמראה \u0003של שאר מיני דמים\u0004 — לא נחלקו בדבר, ול\u0003דברי הכל,\u0004 ואף לדברי ר' יהודה, הריהי \u0003טהורה.\u0004","","\u0003לא נחלקו אלא\u0004 במקרה \u0003ש\u0004האשה \u0003הפילה\u0004 חתיכת בשר שאין עמה צורה, \u0003ו\u0004היא עצמה \u0003אינה יודעת מה הפילה,\u0004 שאין החתיכה לפנינו, וכגון שאבדה. ובכך נחלקו: ש\u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003זיל בתר\u0004 \u0005[לך אחר]\u0006 \u0003רוב חתיכות, ורוב חתיכות של (מיני) ארבעת מיני דמים הויין\u0004 \u0005[הינן].\u0006 \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003רוב חתיכות של ארבעת מיני דמים.\u0004 \u0003ושואלים על דרכי ההסבר הללו של שמואל ושל ר' יוחנן:\u0004 \u0003איני\u0004 \u0005[האמנם כך]\u0006 הוא? \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רב הושעיא מנהרדעא, אתא ואייתי מתניתא בידיה\u0004 \u0005[בא והביא ברייתא בידו]\u0006 שלדברי חכמים בה שנינו: האשה \u0003המפלת חתיכה אדומה,\u0004 או \u0003שחורה,\u0004 או \u0003ירוקה, ו\u0004כן חתיכה \u0003לבנה, אם יש עמה דם\u0004 — הריהי \u0003טמאה, ואם לאו\u0004 \u0005[לא]\u0006 — הריהי \u0003טהורה.\u0004 ואילו \u0003ר' יהודה אומר\u0004 כי \u0003בין כך\u0004 (שיש עימה דם) \u0003ובין כך\u0004 (שאין עימה דם) — הריהי \u0003טמאה.\u0004 ומכאן \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003ל\u0004דרך הסברו של \u0003שמואל בחדא\u0004 \u0005[ב\u0006קושיה \u0005אחת],\u0006 \u0003ול\u0004דרך הסברו של \u0003ר' יוחנן\u0004 יש \u0003ב\u0004דברי ברייתא זו \u0003תרתי\u0004 \u0005[שתי\u0006 קושיות\u0005],\u0006 ומפרטים: קשה \u0003ל\u0004הסברו של \u0003שמואל בחדא\u0004 \u0005[באחת]\u0006 — שכן \u0003אמר שמואל\u0004 כי \u0003לא טימא ר'\u0004 \u0003יהודה אלא בחתיכה של ארבעת מיני דמים\u0004 בלבד, ולא בחתיכה ירוקה או לבנה, \u0003והא קתני\u0004 \u0005[והרי שונה\u0006 התנא בברייתא\u0005]\u0006 אף חתיכה \u0003ירוקה ולבנה,\u0004 שהיא טהורה לדעת חכמים, \u0003ופליג\u0004 \u0005[וחלק]\u0006 עליהם \u0003ר' יהודה!\u0004","","","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בדחיית קושיה זו, ש\u0003כי פליג\u0004 \u0005[כאשר חלק]\u0006 \u0003ר' יהודה\u0004 על חכמים, אין זה אלא בחתיכה \u0003אדומה ושחורה\u0004 בלבד, \u0003ו\u0004אילו בחתיכה \u0003ירוקה ולבנה לא\u0004 חלק ר' יהודה, שאף הוא מסכים שהן טהורות — אין לומר כן, שהרי \u0003אלא\u0004 מעתה שאף ר' יהודה מודה בחתיכה \u0003ירוקה ולבנה,\u0004 אם כן, \u0003למאן קתני לה\u0004 \u0005[ל\u0006שיטת \u0005מי שנה אותה]?\u0006","\u0003אילימא רבנן\u0004 \u0005[אם תאמר:\u0006 לשיטת \u0005חכמים]\u0006 — \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי אף חתיכה \u0003אדומה ושחורה מטהרי רבנן\u0004 \u0005[מטהרים חכמים],\u0006 \u0003ירוקה ולבנה מיבעיא\u0004 \u0005[צריך\u0006 לומר\u0005]\u0006 שלדעת חכמים היא טהורה? \u0003אלא\u0004 האם \u0003לאו\u0004 \u0005[לא]\u0006 נשנו הדברים אלא \u0003ל\u0004השמיענו את שיטת \u0003ר' יהודה,\u0004 שחכמים מטהרים, \u0003ו\u0004אילו ר' יהודה \u0003פליג\u0004 \u0005[חולק]\u0006 עליהם וסבור שטמאה. ושלא כהסברו של שמואל. \u0003ו\u0004מלבד קושיה זו על דרך הסברו של שמואל, שהריהי אף שאלה על דרך הסברו של ר' יוחנן, ישנה \u0003תו\u0004 \u0005[עוד]\u0006 קושיה מדברי הברייתא הזו \u0003ל\u0004דרך להסברו של \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 בדינה של חתיכה \u0003של ארבעת מיני דמים\u0004 כי ל\u0003דברי הכל\u0004 הריהי \u0003טמאה.\u0004 וקשה על כך, שכן \u0003הא קתני\u0004 \u0005[הרי הוא,\u0006 התנא שבברייתא, \u0005שונה]\u0006 חתיכה \u0003אדומה ו\u0004חתיכה \u0003שחורה,\u0004 שהן בכלל ארבעה מיני דמים, \u0003ו\u0004בכל זאת \u0003פליגי רבנן\u0004 \u0005[חולקים חכמים]\u0006 על ר' יהודה המטמא, והריהם מטהרים!","","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ביישוב קושיה זו ש\u0003כי פליגי רבנן\u0004 \u0005[כאשר חולקים חכמים]\u0006 בברייתא על ר' יהודה — הרי זה רק בחתיכה \u0003ירוקה ו\u0004בחתיכה \u0003לבנה, אבל\u0004 בחתיכה \u0003אדומה ו\u0004בחתיכה \u0003שחורה\u0004 — \u0003לא\u0004 חולקים חכמים בדבר, שאף הם סבורים שהריהן טמאות. \u0003אלא\u0004 מעתה, \u0003אדומה ושחורה למאן קתני לה\u0004 \u0005[ל\u0006שיטת \u0005מי, הוא\u0006 התנא שבברייתא \u0005שנה אותה]?\u0006","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי לשיטת \u0003ר' יהודה\u0004 נשנו הדברים — אין לומר כן, שהרי \u0003השתא\u0004 \u0005[עכשיו]\u0006 סבור ר' יהודה כי חתיכה \u0003ירוקה ולבנה\u0004 הריהי \u0003טמאה, אדומה ושחורה מיבעיא\u0004 \u0005[צריך]\u0006 ר' יהודה לומר שהיא טמאה? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 נשנו הדברים לשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003ו\u0004להשמיענו כי \u0003פליגי\u0004 \u0005[חולקים]\u0006 חכמים בדבר זה על ר' יהודה, שהוא מטמא והם מטהרים. והרי זו איפוא קושיה נוספת על דרך הסברו של ר' יוחנן האומר שבחתיכות אלה הכל מודים שהן טמאות.","\u0003אלא אמר רב נחמן בר יצחק\u0004 הסבר אחר במחלוקת חכמים ור' יהודה: \u0003ב\u0004שאלה האם \u0003אפשר ל\u0004מצב זה שתהיה \u0003פתיחת הקבר\u0004 (רחם) \u0003בלא\u0004 יציאת \u0003דם קמיפלגי\u0004 \u0005[הם חולקים],\u0006 \u0003ובפלוגתא דהני תנאי\u0004 \u0005[ובמחלוקת של אלו התנאים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003קשתה\u0004 (היתה האשה מתקשה ללדת) \u0003שנים\u0004 ימים בתוך אחד עשר ימי זיבה, \u0003ול\u0004יום ה\u0003שלישי הפילה, ואינה יודעת מה הפילה\u0004 (אם נפל או רוח), ואם יצא ממנה דם כאשר הפילה —"],["\u0003הרי זו\u0004 בכלל \u0003ספק לידה\u0004 (שמא דינה כיולדת, כיון שהפילה נפל), ובכלל \u0003ספק זיבה\u0004 (שמא אין היא יולדת, כיון שהפילה רוח, ואפשר שיצא ממנה דם). ולכך הריהי \u0003מביאה קרבן\u0004 (ככל יולדת או זבה), \u0003ו\u0004אולם קרבן זה \u0003אינו נאכל\u0004 מפני הספק שמא היא פטורה מהקרבן, ואין חטאת העוף (שדינה במליקה) מותרת באכילה אלא אם היה זה קרבן. שאלמלא כן הרי העוף נבילה. הרי שחכמים סבורים כי אפשר לפתיחת הקבר בלא יציאת דם.","ואילו \u0003ר' יהושע אומר\u0004 ש\u0003מביאה קרבן\u0004 (אם משום שהיא יולדת אם משום שהיא זבה), \u0003ונאכל\u0004 קרבן זה, כיון שברור לנו שיצא דם, \u0003שאי אפשר לפתיחת הקבר בלא\u0004 שתהיה עם כך גם יציאת \u0003דם.\u0004 ונמצאנו למדים כי מחלוקת תנאים ראשונים היא אם אפשר לפתיחת הקבר בלא יציאת דם, ובכך נחלקו אף חכמים ור' יהודה שבמשנתנו.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 של מהלך הדברים בסוגיה לעיל, \u0003אמרי לה\u0004 \u0005[אומרים אותה,\u0006 את הסוגיה הזו\u0005]. בהסבר מחלוקתם של חכמים ור' יהודה במשנתנו\u0006 \u0003אמר רב יהודה, אמר שמואל: לא טימא ר'\u0004 \u0003יהודה\u0004 את האשה המפלת חתיכה שאין עמה דם משום טומאת לידה, \u0003אלא\u0004 משום שנחשבת החתיכה עצמה לדם, ורק \u0003בחתיכה\u0004 שהמראה שלה הוא כמראה \u0003של ארבעה מיני דמים\u0004 טמאים, \u0003אבל\u0004 המפלת חתיכה שהמראה שלה כ\u0003של שאר מיני דמים\u0004 — \u0003טהורה.\u0004","ושואלים על הסבר זה: \u0003איני\u0004 \u0005[האמנם כך]\u0006 הוא? \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003רב הושעיא מנהרדעא, אתא ואייתי מתניתא בידיה\u0004 \u0005[בא והביא ברייתא בידו]\u0006 שבה שנינו: האשה \u0003המפלת חתיכה אדומה, ושחורה, ירוקה, ולבנה, אם יש עמה דם\u0004 — הריהי \u0003טמאה, ואם לאו\u0004 \u0005[לא]\u0006 — הריהי \u0003טהורה.\u0004 אלו דברי חכמים, ואילו \u0003ר' יהודה אומר\u0004 כי \u0003בין כך\u0004 (שיש דם עם החתיכה) \u0003ובין כך\u0004 (שאין דם עם החתיכה) — הריהי \u0003טמאה.\u0004","\u0003קתני\u0004 \u0005[והרי שונה הוא,\u0006 התנא בברייתא\u0005]\u0006 מלבד חתיכה שהיא \u0003אדומה ו\u0004חתיכה שהיא \u0003שחורה\u0004 אף חתיכה שהיא \u0003ירוקה ו\u0004חתיכה שהיא \u0003לבנה,\u0004 שכל אלה הן טהורות לדעת חכמים, \u0003ופליג\u0004 \u0005[וחלק]\u0006 עליהם \u0003ר' יהודה!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בדחיית קושיה זו, ש\u0003כי פליג\u0004 \u0005[כאשר חלק]\u0006 \u0003ר' יהודה\u0004 על חכמים, אין זה אלא בדינה של חתיכה \u0003אדומה ושחורה\u0004 בלבד, \u0003אבל\u0004 בחתיכה \u0003ירוקה ולבנה לא\u0004 חלק ר' יהודה, שאף הוא סבור באלה שהן טהורות — אין לומר כן, שהרי \u0003אלא\u0004 מעתה שאף ר' יהודה מודה בחתיכה \u0003ירוקה ולבנה,\u0004 אם כן, \u0003מאן קתני לה\u0004 \u0005[\u0006כשיטת \u0005מי שנה אותה]?\u0006","\u0003אילימא לרבנן\u0004 \u0005[אם תאמר: ל\u0006שיטת \u0005חכמים]\u0006 — \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי אף חתיכה \u0003אדומה ושחורה קא מטהרי רבנן\u0004 \u0005[מטהרים חכמים],\u0006 \u0003ירוקה ולבנה מיבעיא\u0004 \u0005[צריך\u0006 לומר\u0005]\u0006 שלדעתם היא טהורה? \u0003אלא\u0004 האם \u0003לאו\u0004 \u0005[לא]\u0006 נשנו הדברים אלא \u0003ל\u0004שיטת \u0003ר' יהודה,\u0004 שחכמים אמנם מטהרים חתיכה ירוקה ולבנה, \u0003ו\u0004אילו ר' יהודה \u0003פליג\u0004 \u0005[חולק]!\u0006 עליהם וסבור שהריהי טמאה. ושלא כשמואל.","\u0003אלא אמר רב יהודה\u0004 הסבר אחר: מחלוקת חכמים ור' יהודה היא \u0003ב\u0004שאלה האם \u0003אפשר לפתיחת הקבר\u0004 (רחם) שתהיה \u0003בלא\u0004 יציאת \u0003דם קמיפלגי\u0004 \u0005[הם חולקים],\u0006 \u0003ובפלוגתא דהני תנאי\u0004 \u0005[ובמחלוקת של אלו התנאים],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003קשתה\u0004 (היתה מתקשה ללדת) \u0003שנים\u0004 ימים בתוך אחד עשר ימי זיבה, \u0003ול\u0004יום ה\u0003שלישי הפילה, ואינה יודעת מה הפילה\u0004 (אם נפל או רוח) — \u0003הרי זו ספק לידה ספק זיבה, מביאה קרבן ואינו נאכל.\u0004","\u0003ר'\u0004 \u0003יהושע אומר: מביאה קרבן ונאכל, לפי שאי אפשר לפתיחת הקבר בלא דם.\u0004","שנינו במשנתנו שהאשה המפלת חתיכה שאין בה צורת ולד, אם נמצא בה דם הריהי טמאה, ואם לא נמצא בה דם הריהי טהורה. ומביאים עוד מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בענין זה: \u0003המפלת חתיכה, סומכוס אומר משום\u0004 (בשם) ר' מאיר, וכן היה ר' \u0003שמעון בן מנסיא אומר כדבריו:\u0004 החכם הבודק חתיכה זו הריהי \u0003קורעה\u0004 (חותכה) ובודק את תוכה: \u0003אם יש דם בתוכה\u0004 — הריהי \u0003טמאה, ואם לאו\u0004 \u0005[לא]\u0006 נמצא דם בתוכה — הריהי \u0003טהורה.\u0004","ומשווים הלכה זו שבברייתא לדברי במשנתנו: הלכה זו הריהי \u0003כ\u0004דברי \u0003רבנן\u0004 \u0005[חכמים\u0006 שבמשנתנו\u0005],\u0006 \u0003ו\u0004עוד \u0003עדיפא מדרבנן\u0004 \u0005[עדיפה\u0006 היא \u0005מ\u0006הלכה זו שאמרו חכמים]. ומפרטים: הלכה זו הריהי \u0003כ\u0004דברי \u0003רבנן\u0004 \u0005[חכמים\u0006 שבמשנתנו\u0005],\u0006 שלא כדברי ר' יהודה — \u0003דאמרי\u0004 \u0005[ש\u0006כן \u0005אומרים,\u0006 סבורים\u0005]\u0006 הם כי \u0003אפשר לפתיחת הקבר בלא דם,\u0004 ולכך אם נמצא בחתיכה דם נטמאת בכך האשה. \u0003ו\u0004עוד \u0003עדיפא\u0004 \u0005[עדיפה]\u0006 הלכה זו שבברייתא \u0003מדרבנן\u0004 \u0005[מ\u0006הלכה זו שאמרו חכמים] — \u0003דאינהו סברי\u0004 \u0005[ש\u0006כן \u0005הם,\u0006 חכמים שבמשנתנו \u0005סבורים]\u0006 כי דווקא אם נמצא הדם \u0003עמה,\u0004 עם החתיכה ומחוצה לה — \u0003אין\u0004 \u0005[כן]\u0006 נטמאת האשה. ואולם אם לא נמצא הדם אלא \u0003בתוכה\u0004 בלבד — \u0003לא\u0004 נטמאת בכך האשה. \u0003ו\u0004אילו \u0003סומכוס\u0004 ושאר התנאים שבברייתא \u0003סבר\u0004 \u0005[סבור]\u0006 כי \u0003אפילו\u0004 אם נמצא הדם \u0003בתוכה\u0004 הריהי טמאה.","\u0003ו\u0004עוד \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 בדינה של האשה \u0003המפלת חתיכה\u0004 שאין בה צורת ולד, ש\u0003ר' אחא אומר: קורעה\u0004 ובודק את פנים החתיכה, \u0003אם תוכה מאדים,\u0004 אף שלא נמצא בתוכה דם — הריהי \u0003טמאה, ואם לאו\u0004 \u0005[לא]\u0006 היה צבעו של תוכה אדום — הריהי \u0003טהורה.\u0004","ומשווים הלכה זו לדברי סומכוס שבברייתא הקודמת: הלכה זו \u0003כ\u0004דברי \u0003סומכוס,\u0004 שנדרשים אנו לבדיקה של פנים החתיכה. \u0003ו\u0004אולם הריהי \u0003עדיפא\u0004 \u0005[עדיפה]\u0006 \u0003מ\u0004הלכה זו שאמר \u0003סומכוס,\u0004 שכן לדעת ברייתא זו, אפילו אם נמצא רק מראה אדום בחתיכה, נטמאת בכך האשה.","\u0003ו\u0004מביאים עוד מדברי חכמים בענין זה, \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 בדינה של האשה \u0003המפלת חתיכה, ר'\u0004 \u0003בנימין אומר: קורעה\u0004 ובודק את תוך החתיכה: \u0003אם יש בה עצם\u0004 בתוכה — הרי זה מורה שוולד הפילה, ולכך \u0003אמו טמאה לידה.\u0004 \u0003אמר רב חסדא\u0004 בהסבר דברי ר' בנימין אלה: \u0003ובחתיכה לבנה\u0004 נאמרו הדברים, שהימצאותו של עצם בתוכה הריהי מוכיחה שוולד הפילה. \u0003וכן כי אתא זוגא\u0004 \u0005[כאשר בא זוג\u0006 תלמידי חכמים\u0005]\u0006 \u0003מן חדייב, אתא ואייתי מתניתא בידיה\u0004 \u0005[בא והביא משנה בידו]\u0006 כי \u0003המפלת חתיכה לבנה\u0004 — \u0003קורעה, אם יש בה עצם\u0004 — \u0003אמו טמאה לידה.\u0004","ומביאים עוד מדברי חכמים בענין זה, \u0003אמר ר'\u0004 \u0003יוחנן משום (בשם)\u0004 \u0003ר' שמעון בן יוחי:\u0004 האשה \u0003המפלת חתיכה\u0004 שאין בה צורה — \u0003קורעה,\u0004 ובודק את תוכה, \u0003אם יש בה דם אגור\u0004 (כנוס) — הריהי \u0003טמאה, ואם לאו\u0004 \u0005[לא]\u0006 — הריהי \u0003טהורה.\u0004 ומשווים את דברי ר' שמעון בן יוחאי לדברי התנאים שהובאו למעלה: הרי זה \u0003כ\u0004דעת \u0003סומכוס\u0004 לענין הבדיקה, שיכולה אשה להיטמא גם במציאת דם בתוך החתיכה. \u0003ו\u0004אולם הלכה זו של ר' שמעון בן יוחאי הריהי \u0003קילא מכולהו\u0004 \u0005[קלה מכולם,\u0006 מכל דברי החכמים שהובאו למעלה\u0005],\u0006 שלדעת ר' שמעון בן יוחאי אין היא נטמאת אלא אם נמצא דם כנוס בתוך החתיכה, ואילו לדעת החכמים הריהי נטמאת אף אם לא נמצא בתוכה דם כנוס.","ובבירור דברי ר' יוחנן בשם ר' שמעון בן יוחאי מביאים מה ש\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' ירמיה מר' זירא:\u0004 האשה \u0003הרואה דם\u0004 שיצא מבית הרחם, \u0003ב\u0004אמצעות \u0003שפופרת,\u0004 שהכניסה קנה חלול באותו המקום, ונמצא בתוכו דם, \u0003מהו\u0004 דינה להיטמא בדם זה. וצדדי השאלה: מה שנאמר \"ואשה כי תהיה זבה דם יהיה זובה בבשרה שבעת ימים תהיה בנדתה...\" (ויקרא טו, יט), האם \u0003\"בבשרה\"\u0004 ש\u0003אמר רחמנא\u0004 \u0005[הכתוב]\u0006 לשון מיעוט היא ולהורות שהיא נטמאת רק בדם שעבר דרך בשרה, \u0003ולא ב\u0004דם שעבר דרך \u0003שפופרת.\u0004 \u0003או דלמא\u0004 \u0005[שמא],\u0006 \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"בבשרה\" מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמדנו הלכה אחרת: \u0003שמטמאה\u0004 האשה בראיית דם שנמצא \u0003מבפנים\u0004 (בתוך גופה) \u0003כ\u0004דם הנמצא \u0003בחוץ\u0004 לגופה. שכיון שיצא הדם מהמקור אל הפרוזדור, גם כשלא יצא הדם לחוץ הריהי טמאה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לר' ירמיה: \u0003\"בבשרה\" אמר רחמנא\u0004 \u0005[הכתוב]\u0006 — להורות שנטמאת רק אם ראתה דם שעבר דרך בשרה, \u0003ולא בשפופרת.\u0004 והוכחה לדבר, שכך יש לדרוש את הכתוב הזה: \u0003דאי\u0004 \u0005[שאם]\u0006 תאמר כי הכתוב \u0003\"בבשרה\" מבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללמדנו רק לענין \u0003שמטמאה מבפנים כבחוץ\u0004 — \u0003אם כן נימא קרא\u0004 \u0005[יאמר הכתוב]\u0006 \u0003\"בבשר\", מאי\u0004 \u0005[מה]\u0006 בא ללמדנו הכתוב \u0003\"בבשרה\"? שמע מינה תרתי\u0004 \u0005[למד מכאן שתי\u0006 דרשות\u0005].\u0006","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר'\u0004 \u0003יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי\u0004 בדינה של האשה \u0003המפלת חתיכה\u0004 שאין בה צורת ולד, ש\u0003קורעה\u0004 ובודק: \u0003אם יש בה דם אגור\u0004 — הריהי \u0003טמאה, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003טהורה.\u0004 הרי שאף שלא נראה הדם אלא בתוך החתיכה הריהי נטמאת בכך. ומעתה, אף הרואה דם דרך שפופרת תיטמא בכך!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך עכשיו,\u0006 איך אתה משוה\u0005],\u0006 \u0003התם\u0004 \u0005[שם,\u0006 בדם הנמצא בחתיכה\u0005]\u0006 — הריהי נטמאת בו, משום שכך הוא \u0003דרכה של אשה לראות דם בחתיכה,\u0004 והרי זה בכלל \"בבשרה\". מה שאין כן \u0003הכא\u0004 \u0005[כאן,\u0006 בדם הנמצא בשפופרת\u0005]\u0006 — אין היא נטמאת בו, שהרי \u0003אין דרכה של אשה לראות דם בשפופרת.\u0004","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי דינו של הדם הנמצא ב\u0003שפופרת,\u0004 מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא.\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003המפלת חתיכה, אף על פי ש\u0004החתיכה עצמה \u0003מלאה\u0004 בתוכה \u0003דם, אם יש עמה\u0004 מבחוץ \u0003דם\u0004 — הריהי \u0003טמאה, ואם לאו\u0004 \u0005[לא]\u0006 — הריהי \u0003טהורה.\u0004 \u0003ר'\u0004 \u0003אליעזר אומר:\u0004 בא הכתוב \"\u0003בבשרה\",\u0004 ובלשון מיעוט, להורות כי דווקא באופן זה היא נטמאת, \u0003ו\u0004אולם היא \u0003לא\u0004 נטמאת בדם הנמצא \u0003בשפיר\u0004 (מעטפת העור בה נתון העובר במעי אמו), \u0003ולא\u0004 בדם הנמצא \u0003בחתיכה.\u0004","ולפני שהובאו המשך דברי הברייתא הזו, מבררים: מה הוסיף \u0003ר' אליעזר\u0004 על דברי החכם שקדם לו, שהרי מה שאמר \u0003היינו\u0004 \u0005[זהו]\u0006 מה שאמר \u0003תנא קמא\u0004 \u0005[התנא הראשון],\u0006 שאף הוא לא טימא מחמת דם הנמצא בחתיכה! ומכאן שיש לתקן את לשון דברי ר' אליעזר, שכך \u0003אימא\u0004 \u0005[אמור]\u0006 בברייתא: כך היא ההלכה לדעת התנא הראשון, \u0003ש\u0004הרי \u0003ר' אליעזר אומר\u0004 כשהכתוב \u0003\"בבשרה\"\u0004 בא למעט: \u0003ולא בשפיר ולא בחתיכה,\u0004 שאין הדם הנמצא בהם מטמא.","ומביאים את המשך הברייתא, \u0003וחכמים אומרים:\u0004 המפלת חתיכה מלאה דם \u0003אין זה דם נדה אלא דם חתיכה.\u0004 ושואלים: מה חידשו חכמים? והרי \u0003תנא קמא נמי טהורי מטהר\u0004 \u0005[התנא הראשון גם כן מטהר]\u0006 את הדם שבחתיכה! \u0003אלא דפלי פלויי איכא בינייהו\u0004 [במקרה שהחתיכה \u0005מבוקעת יש ביניהם]\u0006 הבדל,","\u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]\u0006 שיש לדייק מלשון הכתוב \"דם \u0003בבשרה\"\u0004 מטמא — \u0003ולא\u0004 דם כשהוא \u0003ב\u0004תוך \u0003שפיר ולא\u0004 דם \u0003בחתיכה. ו\u0004לשיטתו \u0003הוא הדין ל\u0004דם הנמצא ב\u0003שפופרת\u0004 שאין הוא מטמא. \u0003ו\u0004אולם \u0003הני מילי\u0004 \u0005[אלה הדברים]\u0006 אמורים רק \u0003היכא דשיעא\u0004 \u0005[היכן ש\u0006החתיכה היא \u0005חלקה]\u0006, והדם אשר בתוכה לא נגע ברחם. \u0003אבל\u0004 כאשר החתיכה היא \u0003פלי פלויי\u0004 \u0005[מבוקעת]\u0006 — הריהי \u0003טמאה.\u0004 ו\u0003מאי טעמיה\u0004 \u0005[מה הטעם]\u0006 שנטמאת בחתיכה שכזו? \u0003\"בבשרה\" קרינא ביה\u0004 \u0005[קוראים אנו בה]\u0006.","\u0003ואתו רבנן למימר\u0004 \u0005[ובאו חכמים לומר]\u0006 כחולקים על דברים אלה, ש\u0003אף על גב דפלי פלויי\u0004 \u0005[אף על פי ש\u0006החתיכה \u0005מבוקעת]\u0006 — הריהי טהורה, וטעם הדבר: ש\u0003אין זה דם נדה אלא דם חתיכה.\u0004 ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 לדעת חכמים, כל שהוא \u0003דם נדה ודאי,\u0004 הריהו \u0003טמא, ואפילו\u0004 זה הנמצא \u0003בשפופרת נמי\u0004 \u0005[גם כן]\u0006 טמא. הרי איפוא שנחלקו תנאים בדם הנמצא בשפופרת.","\u0003אמר אביי\u0004 בדחיית הצעה זו: בדם הנמצא \u0003בשפופרת\u0004 — \u0003כולי עלמא\u0004 \u0005[כל\u0006 הדעות\u0005]\u0006 \u0003לא פליגי\u0004 \u0005[אינן חלוקות]\u0006 ש\u0003טהורה\u0004 היא."],["אכן \u0003כי פליגי\u0004 \u0005[כאשר חולקים\u0006 התנא הראשון בשיטת ר' אליעזר וחכמים\u0005]\u0006 — הרי זה \u0003בחתיכה,\u0004 כשהיא מבוקעת. ש\u0003מר\u0004 \u0005[חכם זה,\u0006 התנא הראשון, וכר' אליעזר\u0005]\u0006 \u0003סבר\u0004 כי \u0003דרכה של אשה לראות דם בחתיכה,\u0004 ולכן דם הנראה בבקעים שבחתיכה הריהו דם טמא, והרי זה בכלל הכתוב \"בבשרה\" (ויקרא טו, יט). \u0003ו\u0004אילו \u0003מר\u0004 \u0005[חכם זה,\u0006 חכמים\u0005]\u0006 \u0003סבר\u0004 כי \u0003אין דרכה של אשה לראות דם בחתיכה,\u0004 והדם הנראה בבקעים שבחתיכה אינו דם נדה.","\u0003רבא אמר\u0004 הצעה אחרת בהסבר מחלוקתם של התנא הראשון וחכמים: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין דרכה של אשה לראות דם בחתיכה,\u0004 ולכן אין הדם הנראה בבקעים שבחתיכה דם נדה.","\u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן]\u0006 עוסקים \u0003באשה\u0004 שהיא אמנם \u0003טהורה\u0004 ואינה נדה, שאין זו נחשבת ראיה המטמאת. \u0003ו\u0004בשאלה האם ה\u0003מקור\u0004 (בית הרחם), \u0003מקומו טמא\u0004 כשלעצמו, וטיפת הדם הנמצאת על החתיכה שנגעה במקור נטמאה ומטמאה את האשה (בטומאת ערב), \u0003קמיפלגי\u0004 \u0005[הם חלוקים].\u0006 ש\u0003ר' אליעזר סבר\u0004 כי אמנם ה\u0003אשה טהורה\u0004 מטומאת נדה (שהרי אין זו נחשבת לראיית דם נדה), \u0003ו\u0004אולם ה\u0003דם טמא,\u0004 ומטמא את האשה ואת הטהרות שנגעה בהן — \u0003דהא אתי\u0004 \u0005[שהרי בא]\u0006 הדם \u0003דרך\u0004 ה\u0003מקור,\u0004 ונטמא. \u0003ו\u0004אילו \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 כי ה\u0003אשה טהורה,\u0004 שלא נטמאה כלל ואף לא טומאת ערב, \u0003ו\u0004כן אף ה\u0003מקור מקומו\u0004 — \u0003טהור,\u0004 ולא נטמאו טהרות שנגעה בהן.","ומביאים עוד בעיה דומה. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבה מרב הונא:\u0004 איש \u0003הרואה קרי\u0004 (שכבת זרע) שיצאה מגופו \u0003ב\u0004אמצעות \u0003קיסם\u0004 (חתיכת עץ) שהושחלה אל תוך פי האמה, והוצא הזרע עליה, \u0003מהו\u0004 דינו לענין טומאת קרי? וצדדי השאלה: האם כיון שבטומאת קרי \u0003\"ממנו\" אמר רחמנא\u0004 \u0005[המקרא]\u0006 (\"איש אשר תצא ממנו שכבת זרע\". ויקרא כב, ד) — להדגיש כי רק \u0003עד דנפיק\u0004 \u0005[שיצא]\u0006 \u0003מבשרו\u0004 הריהו נטמא, \u0003ולא\u0004 אם ראה \u0003בקיסם.\u0004 \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר כי \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"ממנו\"\u0004 בא להורות שהריהו נטמא בכל אופן \u0003עד שתצא טומאתו\u0004 ממנו ו\u0003לחוץ, ואפילו\u0004 כשיצא \u0003בקיסם נמי\u0004 \u0005[גם כן]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא: \u0003תיפוק ליה\u0004 \u0005[ייצא לו,\u0006 יילמד הדין\u0005],\u0006 שהרי \u0003הוא\u0004 (זרע) \u0003עצמו אינו מטמא\u0004 בטומאת קרי \u0003אלא ב\u0004זמן שיש בו כשיעור של \u0003חתימת פי האמה,\u0004 ואילו ביציאת זרע באמצעות קיסם, אין כדי שיעור זה, ואין הוא נטמא בכך.","אמר לו רבה לרב הונא: \u0003למימרא\u0004 \u0005[האם יש לומר]\u0006 מכאן שאין טומאת קרי משום שראה האדם זרע שיצא ממנו, אלא משום ש\u0003נוגע הוי\u0004 \u0005[הינו]\u0006 הזרע בבשר האבר. ואם כן הוא, \u0003אלא מעתה\u0004 — הרואה קרי \u0003אל יסתור\u0004 (יבטל ימי ספירת שבעה נקיים, להצריך ספירה מחדש) \u0003בזיבה!\u0004","ו\u0003אלמה תניא\u0004 \u0005[מדוע שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב בטומאת הזב \u0003\"זאת תורת הזב ואשר תצא ממנו שכבת זרע\u0004 לטמאה בה\" (שם טו, לב) — השווה הכתוב את הזב ובעל הקרי, ללמדנו: \u0003מה\u0004 ראיית \u0003זיבה\u0004 בתוך ספירת שבעת ימי נקיים \u0003סותרת\u0004 את מנין הימים הנקיים, ומצריכה ספירה נוספת — \u0003אף\u0004 ראיית \u0003שכבת זרע\u0004 (קרי) בתוך ספירת שבעת ימי נקיים של הזב \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003סותר?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לרבה בתשובה: אין להקשות מדין \u0003סתירה,\u0004 שכן \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 \u0003ש\u0004אף הרואה זרע \u0003סותר\u0004 — \u0003לפי שאי אפשר לה\u0004 לשכבת זרע היוצאת מן הזב \u0003בלא\u0004 שיהיו בה \u0003צחצוחי\u0004 (טיפות) \u0003זיבה.\u0004","ומקשה רבה על כך: \u0003אלא מעתה\u0004 לפי טעם זה, \u0003תסתור\u0004 ראיית שכבת זרע בזב הסופר שבעה נקיים, את \u0003כל\u0004 ימי ה\u0003שבעה,\u0004 ולא רק את היום שבו נראתה שכבת הזרע! \u0003אלמה תניא\u0004 \u0005[מדוע שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \u0003\"זאת תורת הזב\u0004 ואשר תצא ממנו שכבת זרע לטמאה בה\" — \u0003מה זיבה סותרת, אף שכבת זרע סותר.\u0004","\u0003אי\u0004 \u0005[או]\u0006 שמא נאמר: \u0003מה זיבה סותרת\u0004 את \u0003כל שבעה\u0004 הימים, וצריך להתחיל בספירה מחדש של שבעה נקיים, \u0003אף שכבת זרע נמי\u0004 \u0005[גם כן]\u0006 תהא \u0003סותר\u0004 את \u0003כל\u0004 ה\u0003שבעה,\u0004 ולא רק אותו היום? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"לטמאה בה\"\u0004 — \u0003אין לך בה\u0004 (בסתירה שבראיית שכבת זרע) \u0003אלא מה שאמור בה\u0004 (בטומאה שבראיית שכבת זרע), וכשם שטומאת שכבת זרע היא יום אחד בלבד, הריהי אף \u0003סותרת יום אחד\u0004 בלבד?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא בתשובה: \u0003גזירת הכתוב היא, זיבה גמורה\u0004 ש\u0003לא ערבה\u0004 (מעורבת) \u0003בה שכבת זרע\u0004 — הריהי \u0003סותרת כל שבעה, צחצוחי זיבה\u0004 ש\u0003ערבה\u0004 (מעורבת) \u0003בה שכבת זרע\u0004 — \u0003לא סותרת אלא יום אחד\u0004 בלבד.","ובענין דומה \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' יוסי בר' חנינא מר' אלעזר:\u0004 אשה הרואה \u0003דם יבש מהו\u0004 דינה, לענין נדה? וצדדי השאלה: האם כיון שבטומאת נדה \"ואשה \u0003כי יזוב זב דמה\u0004 ימים רבים\" (ויקרא טו, כה), \u0003אמר רחמנא\u0004 \u0005[המקרא]\u0006 — והרי זה מורה כי אין היא נטמאת אלא \u0003עד דמידב דייב ליה\u0004 \u0005[ש\u0006הדם \u0005יזוב,\u0006 יזל, \u0005לו],\u0006 שלכן כשהוא \u0003לח\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מטמא, אבל כשהוא \u0003יבש\u0004 — \u0003לא\u0004 מטמא. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"כי יזוב זב דמה\"\u0004 לא בדווקא אמר כן אלא רק כי \u0003אורחא דמילתא\u0004 \u0005[דרך הדבר]\u0006 \u0003היא\u0004 שבאה ראיית האשה בדם הלח, \u0003ו\u0004אולם \u0003לעולם אפילו\u0004 בדם ה\u0003יבש נמי\u0004 \u0005[גם כן]\u0006 נטמאת האשה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר לר' יוסי בר' חנינא בתמיהה: הרי כבר \u0003תניתוה\u0004 \u0005[שנינו\u0006 בברייתא \u0005אותה הלכה\u0006\u0005]\u0006 שדנת בה, שכן שנינו כי \u0003דם הנדה ו\u0004כן \u0003בשר המת מטמאין\u0004 בין שהם \u0003לחים ו\u0004בין שהם \u0003יבשים.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוסי בר' חנינא לר' אלעזר בהסבר בעייתו: בדם שהיה בשעת יציאתו \u0003לח ו\u0004אחר כך \u0003נעשה יבש\u0004 — \u0003לא קא מיבעיא\u0004 \u0005[נשאלה]\u0006 \u0003לי\u0004 שאלתי, וברור שהוא טמא. \u0003כי מיבעיא\u0004 \u0005[כאשר נשאלה]\u0006 \u0003לי\u0004 שאלתי — בדם שהריהו \u0003יבש מעיקרא\u0004 \u0005[מתחילה,\u0006 משעת יציאתו].","אמר לו ר' אלעזר: אף \u0003הא, נמי תניתוה\u0004 \u0005[\u0006בכגון זה גם כן שנינו אותה]. שכן שנינו במשנה שבתחילת פרקנו בדינה של האשה \u0003המפלת כמין קליפה, כמין שערה, כמין עפר, כמין יבחושין אדומין\u0004 — \u0003תטיל למים,\u0004"],["\u0003אם\u0004 הם \u0003נמוחו\u0004 במים — אשה זו \u0003טמאה.\u0004 הרי איפוא פתרון גם לשאלתך זו, שהרי אף שבתחילה היו הדמים הללו יבשים, אם נימוחו רק לאחר מכן, בהטלתם למים — מטמאים הם. ודנים בראיה זו, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא הדין, והדם היבש מתחילתו אף הוא מטמא, מעתה יהא הדין שגם \u0003בלא\u0004 ש\u0003נמוחו\u0004 הדמים הללו במים, \u0003נמי\u0004 \u0005[גם כן]\u0006 יטמאו, ומדוע נזקקים אנו לבדיקה זו? \u0003אמר רבה\u0004 בתשובה: נזקקים אנו לבדיקה זו, ל\u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא נמוחו\u0004 במים, שבכגון זה ודאי אינם דמים, אלא מין \u0003בריה בפני עצמה היא.\u0004","ושואלים על הנאמר במשנה: \u0003ומי איכא כי האי גוונא\u0004 \u0005[והאם יש\u0006 בנמצא \u0005כעין זה],\u0006 שתפיל אשה צורות שכאלה? ומשיבים: אכן \u0003אין\u0004 \u0005[כן],\u0006 יש שאשה מפלת צורות שכאלה. \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 שעניינה בכעין זה, שכך \u0003אמר ר'\u0004 \u0003אלעזר בר' צדוק: שני מעשים\u0004 (מקרים שהתרחשו) \u0003העלה\u0004 (הביא עמו לדיון לפני חכמים) \u0003אבא,\u0004 ר' צדוק, \u0003מ\u0004היישוב \u0003טבעין\u0004 שבו התרחשו המקרים \u0003ל\u0004מקום מושבם של חכמים ב\u0003יבנה:\u0004","\u0003מעשה באשה\u0004 אחת \u0003שהיתה מפלת כמין קליפות אדומות, ובאו\u0004 אנשי המקום \u0003ושאלו את אבא\u0004 אם נטמאת האשה בכך. \u0003ואבא שאל לחכמים, וחכמים שאלו לרופאים\u0004 מה הסיבה שבגללה אשה זו מפילה כמין קליפות אדומות. \u0003ואמרו להם\u0004 הרופאים לחכמים כי ל\u0003אשה זו מכה\u0004 (פצע) \u0003יש לה בתוך מעיה, שממנה\u0004 היא \u0003מפלת כמין קליפות\u0004 אדומות. ופסקו חכמים כי \u0003תטיל\u0004 אותן \u0003למים,\u0004 ו\u0003אם\u0004 יימצא ש\u0003נמוחו\u0004 בהם — הריהי \u0003טמאה.\u0004","\u0003ושוב\u0004 אירע \u0003מעשה באשה\u0004 אחת \u0003שהיתה מפלת כמין שערות אדומות, ובאה ושאלה את אבא\u0004 מהו דינה, אם נטמאת היא בהן. \u0003ואבא שאל לחכמים, וחכמים\u0004 שאלו \u0003לרופאים, ואמרו להם: שומא יש לה בתוך מעיה, שממנה\u0004 היא \u0003מפלת כמין שערות אדומות.\u0004 וקבעו בה חכמים כי \u0003תטיל\u0004 אותן \u0003למים,\u0004 ו\u0003אם\u0004 יימצא ש\u0003נמוחו\u0004 בהם — הריהי \u0003טמאה.\u0004","ומביאים עוד בענין בדיקת דברים שהפילה אשה וספק אם דם הם על ידי הטלתם במים, \u0003אמר ריש לקיש: ו\u0004אין נעשית בדיקה זו אלא \u0003ב\u0004מים \u0003פושרין\u0004 בלבד. ומביאים ראיה לדבריו, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003תטיל למים, ובפושרין.\u0004 \u0003רבן שמעון בן גמליאל אומר: ממעכתו\u0004 לדבר הנבדק בלחץ האצבעות של היד האחת, כאשר הוא ניתן \u0003ב\u0004תוך \u0003רוק\u0004 הנמצא \u0003על גבי הצפורן\u0004 של כף היד השנית. ומבררים: \u0003מאי בינייהו\u0004 \u0005[מה,\u0006 איזה הבדל להלכה יש \u0005ביניהם,\u0006 בין חכמים לבין רבן שמעון בן גמליאל\u0005]?\u0006 \u0003אמר רבינא\u0004 בתשובה: דינו של הדבר ה\u0003מעוך על ידי הדחק\u0004 (בלחץ) \u0003איכא בינייהו\u0004 \u0005[יש ביניהם].\u0006 שלדעת חכמים רק אם נימוח מעצמו, הריהו נחשב לדם. ולא אם נימוח כתוצאה מלחיצה עליו. ואילו לדעת רבן שמעון בן גמליאל אף אם נימוח על ידי לחיצה, הריהו נחשב כדם.","ודנים עוד בדיני הבדיקה בהטלה למים. \u0003התם תנן\u0004 \u0005[שם,\u0006 במסכתנו להלן נד,ב, \u0005שנינו]\u0006 בדינם של השרץ והנבילה שיבשו, שאין הם מטמאים במצבם זה. ואולם אם שרו אותם במים, ושבה לחותם, כפי שהיתה מקודם, הריהם מטמאים מעתה. ו\u0003כמה\u0004 זמן \u0003היא\u0004 משך \u0003שרייתן\u0004 של השרץ והנבילה שיבשו \u0003ב\u0004מים \u0003פושרין\u0004 — \u0003מעת לעת.\u0004 ומעתה יש לברר, \u0003הכא\u0004 \u0005[כאן],\u0006 לענין בדיקת הדם, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003מי בעינא\u0004 \u0005[האם צריכים אנו]\u0006 אף בבדיקה זו להשרותו במים פושרים כדי \u0003מעת לעת, או לא?\u0004","וצדדי הבעיה: מצד אחד יש לומר, כי דווקא ב\u0003שרץ ונבלה, דאקושי\u0004 \u0005[שמתקשים]\u0006 כשהם מתייבשים — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 משך שהות במים כדי \u0003מעת לעת.\u0004 \u0003אבל דם, דרכיך\u0004 \u0005[שרך]\u0006 הוא, ואין דרכו להתקשות אף כשהוא מתייבש — \u0003לא\u0004 נצרכים אנו למשך זמן כה רב. ואם לא נימוח אף בפחות מעת לעת, יודעים אנו בו שאין הוא דם. \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לומר כי \u0003לא שנא\u0004 \u0005[לא שונה]\u0006 דינה של בדיקה זו מדינה של בדיקת השרץ והנבילה שהתייבשו, שאף בבדיקת הדם צריכים אנו להשרותו במים מעת לעת? ומסכמים: בעיה זו לא נפתרה, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנתנו כי \u0003המפלת כמין דגים\u0004 חגבים שקצים ורמשים, אם יש עמהם דם — הריהי טמאה, ואם לאו — הריהי טהורה. ונשנתה הלכה זו בסתם, וללא חולקים בדבר. ושואלים: \u0003וליפלוג נמי\u0004 \u0005[ויחלוק גם כן]\u0006 \u0003ר' יהודה\u0004 על חכמים \u0003בהא\u0004 \u0005[בזה],\u0006 כדרך שחלק עליהם בראשית המשנה, בענין המפלת חתיכה, שלדעתו בין יש עימה דם ובין עימה דם הריהי טמאה!","\u0003אמר ריש לקיש\u0004 בתשובה: אמנם כן, אף הלכה זו \u0003במחלוקת\u0004 חכמים ור' יהודה היא \u0003שנויה, ו\u0004הדעה המובאת במשנתנו דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 ושלא כדעת ר' יהודה. \u0003ו\u0004אילו \u0003ר' יוחנן אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 כי הלכה זו הריהי אף כדעת \u0003ר' יהודה.\u0004 ואולם יש לומר כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יהודה התם\u0004 \u0005[שם,\u0006 בראשית משנתנו\u0005],\u0006 שהאשה המפלת חתיכה טמאה, גם אם לא היה עם החתיכה דם, \u0003אלא\u0004 דווקא \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003חתיכה\u0004 שהפילה האשה — \u0003דעביד\u0004 \u0005[ש\u0006כן \u0005עשוי]\u0006 ה\u0003דם דקריש והוי\u0004 \u0005[שיקרש ויהיה]\u0006 \u0003חתיכה, אבל\u0004 שיקרש הדם ויהיה לצורה כעין \u0003בריה,\u0004 כדמות דגים וחגבים וכיוצא באלה — \u0003לא הוי\u0004 \u0005[נהיה].\u0006","\u0003ו\u0004מבררים: \u0003להך לישנא\u0004 \u0005[לאותו לשון]\u0006 ש\u0003אמר ר'\u0004 \u0003יוחנן\u0004 בדף הקודם בהסבר מחלוקתם של חכמים ור' יהודה, ש\u0003ב\u0004שאלה האם \u0003אי אפשר לפתיחת הקבר בלא דם קמיפלגי\u0004 \u0005[הם חולקים],\u0006 שלדעת ר' יהודה כל פתיחת רחם כרוכה ביציאת דם, מעתה \u0003לפלוג נמי\u0004 \u0005[שיחלוק גם כן]\u0006 \u0003ר' יהודה בהא\u0004 \u0005[בזה,\u0006 במפלת כמין בריה\u0005]!\u0006","ומשיבים: \u0003מאן דמתני הך לישנא\u0004 \u0005[מי ששונה לשון זו],\u0006 שאמר ר' יוחנן בהסבר מחלוקתם של ר' יהודה וחכמים בדין המפלת חתיכה, \u0003מתני הכי\u0004 \u0005[שונה כך]\u0006 בענייננו, בדין המפלת כמין בריה: \u0003ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]\u0006 כי אין הנאמר במשנתנו דעת הכל, אלא \u0003במחלוקת\u0004 היא \u0003שנויה, ו\u0004הנשנה במשנתנו כ\u0003רבנן היא.\u0004","עוד שנינו במשנתנו כי \u0003המפלת כמין בהמה\u0004 חיה ועוף, בין טמאים בין טהורים, אם זכר — תשב לזכר, ואם נקבה — תשב לנקבה, ואם אין ידוע — תשב לזכר ולנקבה. אלו דברי ר' מאיר.","ודנים בדבריו, \u0003אמר רב יהודה, אמר שמואל: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' מאיר,\u0004 שהרי לא הפילה האשה כצורת אדם — \u0003הואיל ו\u0004בתורה במעשה הבריאה, \u0003נאמרה\u0004 אף \u0003בו\u0004 (בבעלי החיים) הלשון \u0003יצירה כ\u0004דרך שנאמרה בבריאת ה\u0003אדם\u0004 (\"ויצר ה' אלהים מן האדמה כל חית השדה ואת כל עוף השמים\". בראשית ב, יט), וכיון שנאמרה גם בבריאת האדם (\"וייצר ה' אלהים את האדם\". שם ז), למדים גזירה שווה ללמד מזה לזה.","ותוהים: \u0003אלא מעתה,\u0004 לטעם זה, אף \u0003המפלת דמות תנין, תהא אמו טמאה לידה, הואיל ונאמר\u0004 אף \u0003בו\u0004 בבריאת התנין, לשון שמשמעה \u0003יצירה כ\u0004דרך שנאמר בבריאת ה\u0003אדם, ש\u0004כן \u0003נאמר \"ויברא אלהים את התנינם הגדולים\"\u0004 (שם א, כא)!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003דנין\u0004 (למדים בגזירה שווה) דבר שנאמר בו לשון \u0003יצירה מ\u0004דבר שנאמר בו לשון \u0003יצירה, ואין דנין\u0004 דבר שנאמר בו לשון \u0003בריאה מ\u0004דבר שנאמר בו לשון \u0003יצירה.\u0004","ומקשים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה,\u0006 מה בכך\u0005]?\u0006 \u0003הא תנא דבי\u0004 \u0005[הרי שנה\u0006 חכם \u0005בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל\u0004 גזירה שווה בין הכתוב האמור בנגעי בתים \u0003\"ושב הכהן\"\u0004 (ויקרא יד, לט) לכתוב \u0003\"ובא הכהן\"\u0004 (שם מד) — ללמד: \u0003זו היא שיבה זו היא ביאה\u0004 לענין גזירה שווה, שאף שנבדלות הן המלים בצורתן הריהן נדרשות לגזירה שווה. ומעתה, נדרוש כיוצא בזה גם במלים בריאה ויצירה!","\u0003ועוד\u0004 יש לשאול: \u0003נגמר\u0004 \u0005[נלמד]\u0006 גזירה שווה לענין המפלת תנין, מן הלשונות הזהות \u0003בריאה\u0004 האמורה בבריאת התנין (\"ויברא אלהים את התנינים הגדולים\"), \u0003מבריאה\u0004 האמורה בבריאת האדם, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ויברא אלהים את האדם בצלמו\"\u0004 (בראשית א, כז)!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: אין למדים גזירה שווה זו, שכן הכתוב \u0003\"ויברא\"\u0004 האמור בבריאת האדם — \u0003לגופיה\u0004 \u0005[לגופו]\u0006 הוא נכתב, וללמדנו מעשה בריאת האדם. בעוד שהכתוב \u0003\"וייצר\"\u0004 האמור בבריאת האדם הריהו \u0003לאפנויי\u0004 (להיפנות, כפנוי לדרשה ממנו), \u0003ו\u0004לכך \u0003דנין\u0004 דבר שנאמר בו לשון \u0003יצירה\u0004 (בבריאת בעלי החיים) \u0003מ\u0004דבר שנאמר בו לשון \u0003יצירה\u0004 (בבריאת האדם).","ושואלים: \u0003אדרבה\u0004 \u0005[היפך\u0006 הדברים\u0005]:\u0006 הלשון האמור בבריאת האדם \u0003\"וייצר\"\u0004 — הריהו \u0003לגופיה\u0004 \u0005[לגופו],\u0006 ואילו הלשון \u0003\"ויברא\"\u0004 האמור בבריאת האדם — הריהו \u0003לאפנויי\u0004 \u0005[להיפנות],\u0006 \u0003ודנין\u0004 דבר שנאמר בו לשון \u0003בריאה\u0004 כתנינים, \u0003מ\u0004דבר שנאמר בו לשון \u0003בריאה\u0004 כאדם!","ומשיבים: \u0003אלא\u0004 זהו הסברם של דברים: הלשון \u0003\"וייצר\"\u0004 — הריהו \u0003מופנה\u0004 (פנוי לדרשה) \u0003משני צדדין, מ\u0004\u0003ופנה גבי\u0004 \u0005[אצל]\u0006 \u0003אדם ומופנה גבי\u0004 \u0005[אצל]\u0006 \u0003בהמה.\u0004 בעוד שהלשון \u0003\"ויברא\"\u0004 — רק \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003אדם\u0004 הוא \u0003מופנה,\u0004 ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תנינים\u0004 הוא \u0003אינו מופנה.\u0004 ולכך יש לגזור גזירה שווה מאדם לבעלי חיים, ולא מאדם לתנינים.","ומבררים: \u0003מאי\u0004 \u0005[מה,\u0006 במה\u0005]\u0006 הלשון \"וייצר\" \u0003מופנה גבי\u0004 \u0005[אצל]\u0006 \u0003בהמה? אילימא מדכתיב\u0004 \u0005[אם תאמר]\u0006 שכיון שנאמר \u0003\"ויעש אלהים את חית הארץ\u0004 למינה ואת הבהמה למינה\" (שם כה), \u0003וכתיב\u0004 \u0005[וכתוב]\u0006 שוב בדומה \"וייצר [ה'] \u0003אלהים מן האדמה כל חית השדה\",\u0004 ולכך הלשון \"ויצר\" הריהו מופנה אצל הבהמה — \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003תנין נמי\u0004 \u0005[גם כן]\u0006 הלשון \"ויברא\" הריהו \u0003אפנויי\u0004 \u0005[להיפנות]\u0006 \u0003מופנה, דכתיב\u0004 \u0005[ש\u0006כן \u0005כתוב]\u0006 \"ויעש אלהים את חית הארץ למינה ואת הבהמה למינה \u0003ואת כל רמש האדמה\u0004 למינהו\", \u0003וכתיב\u0004 \u0005[ו\u0006שוב \u0005כתוב]\u0006 \u0003\"ויברא אלהים את התנינים הגדולים\".\u0004 ונמצא איפוא כי גם הלשון \"ויברא\" הריהו מופנה משני צדדים!","ומשיבים: הכתוב \"ואת כל רמש האדמה\" אינו עוסק בתנינים, שכן \u0003\"רמש\u0004 האדמה\" \u0003דכתיב התם\u0004 \u0005[שכתוב שם]\u0006 — של \u0003יבשה הוא.\u0004 ולכך נדרשים בעלי החיים מאדם, שגזירה שווה המופנה משני צדדים היא, ואין נדרשים התנינים מאדם, שגזירה שווה המופנה מצד אחד היא. ושואלים: \u0003ומאי נפקא מינה\u0004 \u0005[ומה יוצא מזה,\u0006 מה בכך\u0005]\u0006 \u0003בין\u0004 גזירה שווה ה\u0003מופנה מצד אחד ל\u0004גזירה שווה ה\u0003מופנה משני צדדין?\u0004","ומשיבים: \u0003נפקא מינה\u0004 \u0005[יוצא מכאן,\u0006 יש חשיבות לדבר\u0005]\u0006 לענין זה ש\u0003אמר רב יהודה אמר שמואל משום\u0004 \u0005[בשם]\u0006 \u0003ר' ישמעאל\u0004 בכללי לימוד גזירה שווה: \u0003כל גזרה שוה שאינה מופנה כל עיקר\u0004 — \u0003אין למדין הימנה\u0004 כלל. וכל גזירה שווה ה\u0003מופנה מצד אחד, ל\u0004דעת \u0003ר' ישמעאל\u0004 — \u0003למדין\u0004 ממנה \u0003ואין מושיבין\u0004 (משיבים, מקשים) עליה מן הסברה. ואילו \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 — אמנם \u0003למדין\u0004 ממנה \u0003ו\u0004אולם גם \u0003משיבין\u0004 עליה בפירכה שמן הסברה. וכל גזירה שווה ה\u0003מופנה משני צדדין, דברי הכל\u0004 — \u0003למדין\u0004 ממנה \u0003ואין משיבין\u0004 עליה.","\u0003ו\u0004שואלים: לדעת \u0003ר' ישמעאל, מאי איכא\u0004 \u0005[מה,\u0006 איזה הבדל \u0005יש]\u0006 \u0003בין\u0004 גזירה שווה ה\u0003מופנה מצד אחד ל\u0004גזירה שווה ה\u0003מופנה משני צדדין,\u0004 שהרי לדעתו בזו ובזו למדים ואין משיבים? ומשיבים: \u0003נפקא מינה\u0004 \u0005[יוצא מכאן,\u0006 יש חשיבות לדבר\u0005]\u0006 לענין \u0003דהיכא דאיכא\u0004 \u0005[שהיכן שיש]\u0006 גזירה שווה ה\u0003מופנה מצד אחד ו\u0004גזירה שווה ה\u0003מופנה משני צדדין\u0004 — \u0003שבקינן\u0004 \u0005[עוזבים,\u0006 מניחים, \u0005אנו]\u0006 את הגזירה שווה ה\u0003מופנה מצד אחד\u0004"],["\u0003וילפינן\u0004 \u0005[ולמדים אנו]\u0006 מן הגזירה השווה ה\u0003מופנה משני צדדין.\u0004 \u0003ולהכי אפניה רחמנא\u0004 \u0005[ולכך הפנתה התורה]\u0006 לשון \u0003ל\u0004ענין לימוד דין ה\u0003בהמה\u0004 מדין האדם בגזירה שווה המופנה \u0003משני צדדין, כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא נגמר\u0004 \u0005[נלמד]\u0006 \u0003מן\u0004 גזירה שווה ה\u0003מופנה מצד אחד\u0004 ולענין לימוד התנינים מהאדם.","למעלה הובאו כללי דרישת גזירה שווה. ומביאים נוסח דברים אחר בענין זה. \u0003רב אחא בריה\u0004 \u0005[בנו של]\u0006 \u0003רבא מתני לה משמיה\u0004 \u0005[שונה אותה משמו]\u0006 של \u0003ר' אלעזר,\u0004 ונוסח זה נוטה יותר \u0003לקולא\u0004 \u0005[להקל]:\u0006 \u0003כל גזרה שוה שאינה מופנה כל עיקר\u0004 — אמנם \u0003למדין\u0004 ממנה, \u0003ו\u0004אולם גם \u0003משיבין\u0004 עליה. וכל גזירה שווה ה\u0003מופנה מצד אחד, ל\u0004דעת \u0003ר' ישמעאל\u0004 — \u0003למדין\u0004 ממנה \u0003ואין משיבין\u0004 עליה. ואילו \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 — אמנם \u0003למדין\u0004 ממנה, \u0003ו\u0004אולם גם \u0003משיבין\u0004 עליה. וגזירה שווה ה\u0003מופנה משני צדדין,\u0004 ל\u0003דברי הכל\u0004 — \u0003למדין\u0004 ממנה \u0003ואין משיבין\u0004 עליה.","\u0003ו\u0004לנוסח דברים זה, שואלים: \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 הסבורים שגזירה שווה שאינה מופנה כל עיקר וגזירה שווה המופנה מצד אחד, למדים מהן ומשיבים עליהן, אם כן \u0003מאי איכא\u0004 \u0005[מה,\u0006 איזה הבדל \u0005יש]\u0006 \u0003בין\u0004 גזירה שווה ה\u0003מופנה מצד אחד ל\u0004גזירה שווה \u0003שאינה מופנה כל עיקר?\u0004","ומשיבים: \u0003נפקא מינה\u0004 \u0005[יוצא מזה,\u0006 יש חשיבות בדבר\u0005]\u0006 לענין \u0003היכא דמשכחת לה\u0004 \u0005[היכן שנמצאת לה]\u0006 גזירה שווה ה\u0003מופנה מצד אחד ו\u0004כן גזירה שווה שאינה מופנה כל עיקר, ולאו להאי אית ליה פירכא ולא לזו יש לה פירכה], \u0003ולאו להאי אית ליה פירכא\u0004 \u0005[ולא לזו יש לה פירכה]\u0006 — \u0003שבקינן\u0004 \u0005[עוזבים,\u0006 מניחים, \u0005אנו]\u0006 את הגזירה שווה \u0003שאינה מופנה כל עיקר, וגמרינן\u0004 \u0005[ולמדים אנו]\u0006 \u0003מ\u0004גזירה שווה ה\u0003מופנה מצד אחד.\u0004","ומסבירים לענייננו: \u0003והכא\u0004 \u0005[וכאן,\u0006 בגזירה שווה הנלמדת מהאדם\u0005]\u0006 \u0003מאי פירכא איכא\u0004 \u0005[מה,\u0006 איזו \u0005פירכה יש]\u0006 שבגללה אמרו חכמים למעלה שאין ללמוד מגזירה שווה לעניינם של התנינים מהאדם, שכן הוא גזירה שווה המופנה מצד אחד, שיש להשיב עליה. ומסבירים: \u0003משום דאיכא למיפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך]\u0006 באופן זה: \u0003מה לאדם\u0004 — \u0003שכן\u0004 הריהו \u0003מטמא\u0004 אף \u0003מחיים\u0004 (בהיותו בחיים), תאמר בבעלי חיים, שאין בהם טומאה אלא במותם, לכשייעשו נבילה.","למעלה הובא הסבר שיטתו של ר' מאיר במשנתנו המטמא את האשה המפלת כמין בהמה חיה ועוף, ומוסיפים: \u0003וכן אמר ר'\u0004 \u0003חייא בר אבא, אמר ר'\u0004 \u0003יוחנן: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 בשיטת \u0003ר' מאיר\u0004 — \u0003הואיל ונאמרה בו,\u0004 בבריאת בעלי החיים הללו, הלשון \u0003\"יצירה\" כ\u0004מו שנאמר בבריאת ה\u0003אדם.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אמי: אלא מעתה,\u0004 לפי טעם זה האשה \u0003המפלת\u0004 כ\u0003דמות הר,\u0004 תהא \u0003אמו טמאה לידה,\u0004 ככל יולדת ולד, \u0003ש\u0004הרי אף בבריאת ההרים \u0003נאמר\u0004 לשון \"יצירה\", שכן כתוב \u0003\"כי הנה יוצר הרים ובורא רוח\"\u0004 (עמוס ד, יג)! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא בר אבא לר' אמי בדחיית שאלתו: וכדמות \u0003הר מי קא\u0004 \u0005[האם היא]\u0006 \u0003מפלת?\u0004 שהרי החתיכה שמפילה האשה אינה יכולה להיות גדולה כל כך, אלא כדמות \u0003אבן\u0004 בלבד \u0003היא דקא\u0004 \u0005[שהיא]\u0006 \u0003מפלת,\u0004 ו\u0003ההוא\u0004 \u0005[אותו]\u0006 אבן \u0003\"גוש\"\u0004 היא \u0003איקרי\u0004 \u0005[נקראת]\u0006 ולא \"הר\".","הוסיף ושאל ר' אמי את ר' חייא בר אבא, \u0003אלא מעתה,\u0004 לפי טעם זה בהסבר שיטתו של ר' מאיר, אף \u0003המפלת רוח,\u0004 חתיכה שעדיין לא נקבעה צורתה, שטרם נרקמו איברים, \u0003תהא אמו טמאה לידה,\u0004 כיולדת ולד, \u0003הואיל ונאמרה בו,\u0004 בבריאת הרוח, הלשון \u0003\"בריאה\" כ\u0004דרך שנאמר בבריאת ה\u0003אדם, דכתיב\u0004 \u0005[ש\u0006כן \u0005כתוב]\u0006 \u0003\"ובורא רוח\"! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאין לדרוש כן, מפני שהיא גזירה שווה \u0003לא מופנה,\u0004 שכן נדרש הכתוב הזה לעצמו, להשמיענו ענין בריאת הרוח — אין זה כך, שהרי \u0003מדהוה ליה למכתב\u0004 \u0005[מתוך שהיה לו לכתוב]\u0006 \u0003\"יוצר הרים ורוח\", וכתיב\u0004 \u0005[וכתוב]\u0006 \"יוצר הרים \u0003ובורא רוח\",\u0004 \u0003שמע מינה לאפנויי\u0004 \u0005[למד ממנה\u0006 כי בא הכתוב הנוסף \u0005להיפנות]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא בר אבא לר' אמי, בתשובה: אין גוזרים גזירה שווה שכזו, שכן כלל הוא ש\u0003דנין\u0004 (למדים בגזירה שווה) \u0003דברי תורה מדברי תורה, ואין דנין\u0004 (למדים בגזירה שווה) \u0003דברי תורה מדברי קבלה\u0004 (הנביאים והכתובים), ואף פסוק זה, \"ובורא רוח\" מן הנביאים הוא.","ומביאים עוד הסבר בשיטתו של ר' מאיר המטמא את המפלת דמות בהמה חיה ועוף. (אמר) רבה בר בר חנה, אמר ר' \u0003יוחנן: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' מאיר\u0004 — \u0003הואיל ועיניהם\u0004 של בריות אלה הריהן \u0003דומות כ\u0004עיניהם \u0003של\u0004 בני \u0003אדם.\u0004","ושואלים: \u0003אלא מעתה,\u0004 לפי טעם זה, אף \u0003המפלת\u0004 כ\u0003דמות נחש תהא אמו טמאה לידה, הואיל וגלגל עינו\u0004 של נחש הריהי \u0003עגולה כשל אדם! וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[אכן כך]\u0006 הוא דינה של המפלת כדמות נחש, \u0003ליתני\u0004 \u0005[שישנה]\u0006 אם כן התנא במשנתנו \u0003נחש!\u0004","ומשיבים: לא שנה כן התנא במשנתנו, שכן \u0003אי תנא\u0004 \u0005[אם היה שונה]\u0006 \u0003נחש\u0004 במשנתנו, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי דווקא \u0003ב\u0004מפלת כדמות \u0003נחש הוא דפליגי רבנן עליה\u0004 \u0005[שחולקים חכמים עליו],\u0006 על \u0003ר' מאיר\u0004 — שהרי \u0003לא כתיב ביה\u0004 \u0005[נאמר בו]\u0006 לשון \u0003\"יצירה\", אבל\u0004 המפלת כדמות \u0003בהמה וחיה\u0004 — \u0003לא פליגי\u0004 \u0005[אינם חולקים]\u0006 על ר' מאיר, \u0003דכתיבא ביה\u0004 \u0005[ש\u0006כן \u0005כתובה בו]\u0006 הלשון \u0003\"יצירה\".\u0004","\u0003ו\u0004שואלים עוד: כיצד אומרים אנו שעיניהן של הבהמות הריהן כעיניו של אדם, \u0003הא גבי\u0004 \u0005[הרי אצל]\u0006 הלכות \u0003מומין קתני לה\u0004 \u0005[שנינו אותה]\u0006 הלכה: \u0003את שגלגל עינו עגול כשל אדם\u0004 הריהו בעל מום. הרי שאין עיניהן דומות לעיניהם של בני אדם! ומשיבים: \u0003לא קשיא\u0004 \u0005[\u0006זה \u0005לא קשה],\u0006 שכן יש להבדיל, \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שעיניהן של הבהמות הריהן דומות לעיניהם של בני אדם — הרי זה דווקא \u0003באוכמא\u0004 \u0005[ב\u0006חלק \u0005השחור\u0006 שבעין, באישון\u0005],\u0006 ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאין עיני הבהמות דומות לעיניהם של בני אדם — הרי זה \u0003בציריא\u0004 \u0005[מקום מושבה של העין].\u0006","\u0003ר' ינאי אמר\u0004 הסבר אחר בשיטתו של ר' מאיר המטמא את המפלת דמות חיה בהמה ועוף: \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ר' מאיר\u0004 — \u0003הואיל ועיניהם\u0004 של בריות אלה \u0003הולכות לפניהם\u0004 (מתבוננות קדימה להן), \u0003כשל\u0004 עיניהם של בני \u0003אדם,\u0004 מה שאין כן בדגים ובנחש. ושואלים על כך: \u0003והרי עוף,\u0004 ש\u0003אין עיניו הולכות לפניו, ו\u0004בכל זאת \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' מאיר\u0004 ש\u0003טמא! אמר אביי\u0004 בתשובה: אכן לשיטת ר' מאיר מדובר רק \u0003ב\u0004זו המפלת דמות כשל העופות \u0003קריא וקיפופא,\u0004 שעיניהם של אלה מתבוננות קדימה, \u0003ו\u0004אילו \u0003בשאר עופות\u0004 — \u0003לא\u0004 טימא ר' מאיר.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על תירוץ זה, ממה ששנינו, ר' חנינא בן אנטיגנוס אומר: נראין דברי ר' \u0003מאיר\u0004 מדברי חכמים \u0003ב\u0004דינה של המפלת כדמות \u0003בהמה וחיה, ו\u0004נראים \u0003דברי חכמים\u0004 מדברי ר' מאיר \u0003ב\u0004מפלת כדמות \u0003עופות.\u0004","ומעתה יש לדון בדברים: \u0003מאי\u0004 \u0005[מהן]\u0006 \u0003עופות\u0004 אלה השנויים בדבריו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בקריא וקיפופא, מאי שנא\u0004 \u0005[במה שונה,\u0006 נבדל\u0005]\u0006 דינם של \u0003בהמה וחיה,\u0004 שהכריע בהן כדעת ר' מאיר — שכן \u0003עיניהן הולכות לפניהן כשל אדם,\u0004 ב\u0003קריא וקיפופא\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 יש להכריע כדברי ר' מאיר, שהרי אף אלה עיניהם הולכות לפניהם!","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 הוא שהכוונה \u0003בשאר עופות\u0004 — \u0003מכלל\u0004 \u0005[מכאן נסיק]\u0006 כי \u0003ר' מאיר פליג\u0004 \u0005[חולק]\u0006 על חכמים אף \u0003בשאר עופות,\u0004 שאין עיניהם הולכות לפניהם!","ומשיבים: אין להקשות מדברי ברייתא זו, שכן \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרים\u0006 דבריה, \u0005וכך היא שנויה\u0006 כתיקנה\u0005]:\u0006 \u0005ר' חנינא בן (אנטיגנוס) אומר: נראין דברי ר'\u0006 \u0003מאיר בבהמה וחיה, והוא הדין לקריא וקיפופא, ו\u0004נראים \u0003דברי חכמים בשאר עופות, שאף ר'\u0004 \u0003מאיר לא נחלק עמהם אלא בקריא וקיפופא, אבל בשאר עופות\u0004 — \u0003מודי להו\u0004 \u0005[מודה להם].\u0006","\u0003ו\u0004כראיה להסברו זה של אביי, מצאנו כי \u0003התניא\u0004 \u0005[הרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003אלעזר בר' צדוק: המפלת מין בהמה וחיה, לדברי ר'\u0004 \u0003מאיר\u0004 — הרי זה כ\u0003ולד, ולדברי חכמים\u0004 — \u0003אינו ולד.\u0004 והמפלת \u0003ב\u0004דמות \u0003עופות\u0004 — הרי זו החתיכה \u0003תיבדק.\u0004","ויש לברר: \u0003ל\u0004דברי \u0003מאן\u0004 \u0005[מי]\u0006 שנינו ש\u0003תיבדק? לאו\u0004 \u0005[האם לא]\u0006 \u0003לדברי ר'\u0004 \u0003מאיר,\u0004 ש\u0003אמר\u0004 כי המפלת כדמות \u0003קריא וקיפופא\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נטמאת בכך, ואילו המפלת כדמות \u0003שאר עופות\u0004 — \u0003לא\u0004 נטמאת, ולכך צריכים אנו לבדוק לאלו מן העופות הריהי דומה, שאם עיניה בקידמת פניה הריהי טמאה.","\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: לא,\u0004 אין זו ראיה. שכן אפשר לומר כי הכוונה היא ש\u0003תיבדק ל\u0004דעתם של \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003דאמרי\u0004 \u0005[שאמרו]\u0006 כי המפלת כדמות \u0003קריא וקיפופא\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מטמאת, אף שאין המפלת בהמה וחיה מטמאת, ואילו המפלת כדמות \u0003שאר עופות\u0004 — \u0003לא\u0004 מטמאת,","\u0003ומאי שנא\u0004 \u0005[ובמה שונה,\u0006 נבדל\u0005]\u0006 האשה המפלת כדמות \u0003קריא וקיפופא\u0004 שנטמאת לדעת חכמים, \u0003מ\u0004המפלת כדמות \u0003בהמה וחיה\u0004 שאינה נטמאת לדעת חכמים? — \u0003הואיל ויש להן\u0004 לקריא וקיפופא \u0003לסתות כ\u0004דרך שיש לבני \u0003אדם.\u0004","ודנים עוד בשיטת ר' מאיר המטמא את המפלת כדמות בהמה, שלדעתו נחשב הוא כולד. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' ירמיה מר' זירא: ל\u0004שיטתו זו של \u0003ר' מאיר,\u0004 ש\u0003אמר\u0004 כי \u0003בהמה\u0004 הנמצאת \u0003במעי אשה, ולד מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא,\u0004 מעתה יש לברר דעתו במקרה ש\u0003קבל בה אביה\u0004 (של אותו ולד, בדמות בהמה, ממין נקבה) מאיש \u0003קידושין\u0004 (כסף שעל ידו מתקדשת היא לו), \u0003מהו\u0004 הדין. והסביר את שאלתו: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכך,\u0006 לענין מה\u0005]?\u0006 — \u0003לאיתסורי\u0004 \u0005[להיאסר]\u0006 מעתה האיש המקדש אותה \u0003באחותה,\u0004 שהרי אחות אשתו היא.","ותוהים: \u0003למימרא דחיי\u0004 \u0005[האם נאמר\u0006 מכאן \u0005שחיה]\u0006 היא אותה חתיכה שבדמות בהמה, שהרי אין איסור אחות אשתו אלא בחיי אשתו. \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה, אמר רב: לא אמרה ר' מאיר\u0004 את שיטתו זו, שהמפלת כמין בהמה הריהי נטמאת בה, \u0003אלא\u0004 רק \u0003הואיל ובמינו מתקיים.\u0004 וכגון בהמה גמורה מתקיימת, ובמינו הוא שמתקיים, אבל עובר בהמה במעי אשה, אינו מתקיים! \u0003אמר רב אחא בר יעקב: עד כאן\u0004 (כך, על ידי שאלתו זו) \u0003הביאו ר' ירמיה לר' זירא לידי גיחוך,\u0004 שאף ר' ירמיה לא שאל כן אלא רק כדי להביא שחוק לר' זירא, \u0003ו\u0004אולם ר' זירא \u0003לא גחיך\u0004 \u0005[גיחך].\u0006","למעלה הובאו דברי רב בהסבר שיטתו של ר' מאיר, וכדחיה לשאלתו של ר' ירמיה, ועתה דנים בהם \u0003גופא\u0004 \u0005[לגופם].\u0006 \u0005אמר רב יהודה, אמר רב: לא אמרה ר' מאיר אלא הואיל ובמינו מתקיים.\u0006 \u0003אמר רב ירמיה מדפתי:\u0004"],["\u0003אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 שאין חתיכה בדמות בהמה חיה ועוף המצויה במעי האשה מתקיימת, שכן שנינו במשנה במסכת בכורות בכלל אלה שנחשבים כבכור לענין ירושה, ולא לענין פדיון אצל הכהן, גם את האשה \u0003המפלת\u0004 חתיכה הנראית \u0003כמין בהמה\u0004 או כמין \u0003חיה ו\u0004כן כמין \u0003עוף (\u0004שכן ולד מעליא \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא\u0004 זה\u0003),\u0004 והילד הנולד אחריו בכור לענין נחלה, אבל לא לענין פדיון בכור, אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004 \u0003וחכמים אומרים\u0004 כי אין הראשון פוטר את הבא אחריו מפדיון \u0003עד שיהא בו מצורת אדם.\u0004 שכל שאין לו צורת אדם, אינו נחשב לולד להחשיבו כ\"פטר רחם\" האמור במצות פדיון בכור (שמות יג, ב).","\u0003ו\u0004הכל מודים כי האשה \u0003המפלת\u0004 חתיכה כמין \u0003סנדל\u0004 (ולד חסר צורה), \u0003או שליא\u0004 (מעין כיס שהעובר מצוי בתוכו ברחם אמו), בלא ולד, \u0003או שפיר\u0004 (עובר) \u0003מרוקם,\u0004 שניכרת בו צורת ולד, \u0003ו\u0004כן אם הפילה ולד \u0003היוצא מחותך,\u0004 שחתכוהו בעודו ברחם אמו מפני שסיכן את חייה, או מפני שלא הצליחו לילד את אמו — \u0003הבא\u0004 (הנולד) \u0003אחריו\u0004 הריהו נחשב \u0003בכור ל\u0004ענין \u0003נחלה\u0004 (ירושה), שכן הקודם לו אינו נחשב כבכור לאב, לרשת נחלה. \u0003ו\u0004אולם \u0003אינו\u0004 נחשב \u0003בכור ל\u0004ענין פדיונו בידי \u0003כהן,\u0004 מפני שאינו בכלל \"פטר רחם\". \u0003ו\u0004מעתה \u0003אי סלקא דעתך דחיי\u0004 \u0005[אם עולה על דעתך\u0006 לומר \u0005שיכול לחיות]\u0006 הדבר שצורתו כמין בהמה חיה ועוף, \u0003הבא אחריו בכור לנחלה מי הוי\u0004 \u0005[האם\u0006 אמנם \u0005הינו\u0006 בכור לכך\u0005]? אמר רבא\u0006","בדחיית ראייתו של רב ירמיה מדפתי: \u0003לעולם\u0004 יש מקום לומר \u0003דחיי\u0004 \u0005[שחי,\u0006 מתקיים\u0005]\u0006 הדבר שצורתו כמין חיה בהמה ועוף, \u0003ו\u0004הטעם שאינו נחשב כבכור לענין נחלה, שכן \u0003שאני התם\u0004 \u0005[שונה,\u0006 מיוחד הוא הדין \u0005שם,\u0006 לענין בכורה לנחלה\u0005],\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין בכורה לנחלה \"לתת לו פי שנים בכל אשר ימצא לו כי הוא \u0003ראשית אונו\u0004 לו משפט הבכורה\" (דברים כא, יז) — אין הדברים אמורים אלא ב\u0003מי שלבו\u0004 של האב \u0003דוה\u0004 (אבל) \u0003עליו\u0004 אם מת (\"אונו\" במשמעות אנינות ואבלותו), \u0003יצא זה\u0004 הנפל בצורת בהמה חיה ועוף, \u0003שאין לבו\u0004 של האב \u0003דוה עליו.\u0004","ודנים עוד בשיטת ר' מאיר. \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב אדא בר אהבה מאביי: ל\u0004שיטת \u0003ר' מאיר,\u0004 ש\u0003אמר\u0004 כי חתיכה בדמות \u0003בהמה\u0004 הנמצאת \u0003במעי אשה\u0004 — כ\u0003ולד מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא\u0004 נחשב, יש לברר, דמות \u0003אדם\u0004 הנמצאת \u0003במעי בהמה\u0004 כשרה \u0003מאי\u0004 \u0005[מה]\u0006 דינה? ומסבירים: \u0003למאי נפקא מיניה\u0004 \u0005[מה יוצא מזה,\u0006 לאיזה ענין המדובר — \u0003לאשתרויי\u0004 \u0005[להתירה]\u0006 את אותה חתיכה \u0003באכילה,\u0004 אם נשחטה הבהמה, וכדין עובר הנמצא במעי אמו שנשחטה שמותר באכילה, אף שהוא עצמו לא נשחט.","ומציעים: \u0003ותפשוט ליה מהא\u0004 \u0005[ותיפתר לו\u0006 לרב אדא בר אהבה שאלתו, \u0005מ\u0006הלכה \u0005זו]\u0006 שאמר \u0003ר' יוחנן,\u0004 שכך \u0003אמר ר'\u0004 \u0003יוחנן: השוחט את הבהמה, ומצא בה דמות יונה\u0004 — \u0003אסורה באכילה.\u0004 שאין שחיטת האם מועילה אלא לעובר שהוא בן מינה, ולא לנמצא במעיה שאינו בן מינה. ומכאן שאף דמות אדם הנמצאת במעי בהמה אינה ניתרת באכילה על ידי שחיטת האם!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך עכשיו\u0006 אתה משווה את הדברים\u0005]?\u0006 \u0003התם\u0004 \u0005[שם,\u0006 בדמות יונה הנמצאת במעי הבהמה\u0005]\u0006 — \u0003לא פרסות\u0004 (פרסה שסועה הנראית כשתים) \u0003איכא\u0004 \u0005[יש]\u0006 ליונה, \u0003ולא פרסה\u0004 אחת איכא \u0005[יש]\u0006 לה. אבל \u0003הכא\u0004 \u0005[כאן,\u0006 בדמות אדם במעי הבהמה\u0005]\u0006 — \u0003נהי\u0004 \u0005[אכן]\u0006 \u0003פרסות ליכא\u0004 \u0005[אין]\u0006 לו לאדם, ואולם \u0003פרסה מיהא איכא\u0004 \u0005[לפחות יש]\u0006 לאדם. ולא נפתרה איפוא בעיה זו.","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003חכמים\u0004 חולקים על ר' מאיר הסבור כי המפלת נפל שצורתו כדמות בהמה חיה ועוף הריהי טמאת לידה, ואילו הם \u0003אומרים\u0004 כי \u0003כל שאין בו\u0004 מצורת אדם — אין הוא נחשב ולד. ובהסבר מחלוקתם \u0003אמר רב ירמיה בר אבא, אמר רב: הכל\u0004 (ואף חכמים) \u0003מודים\u0004 שאם היה \u0003גופו\u0004 של הדבר שהפילה האשה כשל \u0003תייש ו\u0004אולם \u0003פניו\u0004 היו כשל \u0003אדם\u0004 — הרי זה נחשב כוולד \u0003אדם,\u0004 ונטמאת בו טומאת לידה, אף לדעת חכמים. וכן הכל (אף ר' מאיר) סבורים כי אם היה \u0003גופו\u0004 כשל \u0003אדם ו\u0004אולם \u0003פניו\u0004 כשל \u0003תייש\u0004 — הרי זה נחשב כ\u0003ולא כלום,\u0004 שהרי פניו של נפל זה אינם כשל אדם.","\u0003לא נחלקו אלא שפניו\u0004 של הדבר שהפילה היו אמנם כשל \u0003אדם, ו\u0004אולם \u0003נברא בעין אחת כבהמה,\u0004 ובעין השנית כאדם. \u0003ש\u0004בזה \u0003ר' מאיר אומר\u0004 כי מאחר ויש בו חלק \u0003מצורת אדם,\u0004 הריהו נחשב כולד אדם, ונטמאת בו. \u0003ו\u0004אילו \u0003חכמים אומרים\u0004 שאינו נחשב כולד אדם אלא אם כן היו בפניו \u0003כל צורת אדם,\u0004 ואין האשה נטמאת בכך.","\u0003אמר לו לרב ירמיה בר אבא\u0004 בשאלה על דבריו: \u0003והא איפכא תניא\u0004 \u0005[והרי ההיפך\u0006 מדבריך, \u0005שנינו\u0006 בברייתא\u0005],\u0006 שכך שנינו, \u0003ר' מאיר אומר:\u0004 אין האשה נטמאת אלא אם כן היה בדבר שהפילה \u0003כל צורת\u0004 אדם. \u0003וחכמים אומרים\u0004 שהריהי נטמאת אף אם היה בו חלק \u0003מצורת\u0004 אדם. והרי איפוא ש\"כל צורת אדם\" משמעו: כל שהוא מצורת אדם, ואפילו כל פניו היו כשל תייש אלא שנברא בעין אחת או בלסת אחת כשל אדם. ואילו לדעת חכמים האומרים \"מצורת אדם\", משמעו: שאין האשה נטמאת אלא אם כן היה בדבר שהפילה מקצת צורת אדם הניכרת, וכגון שהיה חצי פרצופו כשל אדם! \u0003אמר להו\u0004 \u0005[להם]\u0006 רב ירמיה בר אבא לחכמים: \u0003אי תניא\u0004 \u0005[אם\u0006 כך היא \u0005שנויה]\u0006 — כך היא \u0003תניא\u0004 \u0005[שנויה],\u0006 שאני שמעתי מפי רב כפי שאמרתי, ואולם אתם שישנה ברייתא זו בידכם, לכו אחריה.","למעלה הובאו שתי הצעות פירוש במחלוקת ר' מאיר וחכמים, של רב ושל הברייתא. ומביאים עוד בענין זה. \u0003אמר ר'\u0004 \u0003ירמיה בר אבא, אמר ר'\u0004 \u0003יוחנן:\u0004 אין האשה המפילה ולד נטמאת בו אלא אם כן היו פניו דומים לפני אדם בכל חלקי הפנים. שאם היו בפניו ה\u0003מצח, והגבינים\u0004 (גבות העינים), \u0003והעינים, והלסתות, וגבות הזקן\u0004 (סנטר), אינה נטמאת \u0003עד שיהו כולם כאחד\u0004 דומים לשל אדם. \u0003רבא אמר\u0004 שכך אמר החכם \u0003חסא\u0004 בענין זה: האשה שהפילה דמות שבפניו \u0003מצח, והגבן, והעין, והלסת, וגבת הזקן\u0004 אינה טמאה \u0003עד שיהו כולם כאחת\u0004 דומים לשל אדם. ואולם אין צורך שיהיו שתי גבותיו ושתי עיניו ולסתותיו דומות לשל אדם, שלענין זה די במראה אדם מצד אחד של פניו.","ומסבירים: \u0003ולא פליגי\u0004 \u0005[חלוקים]\u0006 ר' יוחנן וחסא, ששניהם סבורים כדעת חכמים החולקים על ר' מאיר, ואולם \u0003הא\u0004 \u0005[זה,\u0006 ר' יוחנן\u0005]\u0006 שאמר שהריהי נטמאת רק כאשר היה מראה פניו של הולד דומה בכל חלקיו לשל אדם — הריהו \u0003כמאן דאמר\u0004 \u0005[כמי שאמר]\u0006 בהסבר דברי חכמים שהאשה נטמאת רק כאשר היה בולד \u0003כל צורת\u0004 פנים של אדם. ואילו \u0003הא\u0004 \u0005[זה,\u0006 חסא] שאמר שהריהי נטמאת אף שהיה דומה בעין אחת ובלסת אחת — הריהו \u0003כמאן דאמר\u0004 \u0005[כמי שאמר]\u0006 בהסבר דברי חכמים שהאשה נטמאת אף כאשר היה בולד מראה של חלק \u0003מצורת\u0004 פני אדם.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי חסא שצריך שיהיה לפחות צד אחד של הפנים, על כל איבריו, דומה לשל אדם, כדי שתיטמא בכך האשה. ממה ששנינו בברייתא: \u0003צורת פנים\u0004 של הולד, \u0003שאמרו\u0004 בה חכמים שנטמאת בה האשה — הכוונה היא, \u0003אפילו פרצוף אחד מן הפרצופין, ח\u0004 \u0003וץ מן האוזן.\u0004 ודנים בדברי הברייתא: \u0003למימרא דמחד נמי סגי\u0004 \u0005[האם\u0006 אין כוונת הדברים \u0005לומר ש\u0006אבר \u0005אחד\u0006 בפרצוף הדומה לשל אדם \u0005גם כן די\u0006 בו\u0005]\u0006 כדי להחשיבו כולד ולטמא את אמו!","\u0003אמר אביי\u0004 בתשובה: \u0003כי תניא\u0004 \u0005[כאשר נשנתה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 רק \u0003לעכב תניא\u0004 \u0005[נשנתה].\u0006 שאין די שצורת צד אחד של פני הולד דומה לשל אדם, כדי שתיטמא האשה בכך. אלא חייב שיהיו באותו צד כל האיברים דומים לשל אדם. ואם היה אחד בהם אינו דומה לשל אדם, אין האשה נטמאת בכך. \u0003וכמאן דאמר\u0004 \u0005[וכמי שאומר]\u0006 כי לדעת חכמים אינה נטמאת עד שיהיו פני הולד דומים ב\u0003כל\u0004 לצורת פני אדם. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006 תירוץ אחר\u0005]:\u0006 \u0003לעולם\u0004 סבורה ברייתא זו \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]\u0006 שהאשה נטמאת אף כאשר היו פני הולד דומים כחלק \u0003מצורת\u0004 פני אדם, \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש השנוי בברייתא \"אפילו פרצוף \u0003אחד\" —\u0004 \u0003אחד אחד\u0004 מכל האיברים הכפולים בפני אדם, שדי בעין אחת ובלסת אחת ובגבה אחת.","ועוד בענין דומה, \u0003אמר רבא:\u0004 הפילה ולד ש\u0003נברא בעין אחת\u0004 בלבד, \u0003ובירך אחד\u0004 בלבד, אם נמצאות עין זו וירך זו \u0003מן הצד\u0004 של הגוף, וכדרך שנמצאים הם בגופו של אדם רגיל — \u0003אמו טמאה\u0004 טומאת לידה, שולד אדם הוא. ואם נמצאות הן \u0003באמצע\u0004 הגוף — הרי \u0003אמו טהורה,\u0004 שאינו נחשב כולד אדם.","ועוד בענין זה, \u0003אמר רבא:\u0004 אם הפילה ולד ש\u0003ושטו נקוב,\u0004 אף שהוא נחשב כטריפה — \u0003אמו טמאה\u0004 טומאת לידה, ואולם אם \u0003ושטו אטום\u0004 (סתום) — \u0003אמו טהורה,\u0004 שכאמור הלאה — אינו נידון כאדם.","ומביאים עוד בענין זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003המפלת גוף אטום\u0004 (סתום) — \u0003אין אמו טמאה לידה.\u0004 \u0003ו\u0004מסבירים: \u0003איזהו גוף אטום? רבי אומר:\u0004 כל שחסר בו איבר חיוני עד \u0003כדי שינטל\u0004 כרגיל \u0003מן\u0004 האדם החי וימות כתוצאה מכך.","ומפרטים: \u0003וכמה\u0004 (איזה שיעור) \u0003ינטל מן החי, ו\u0004על ידי כך \u0003ימות,\u0004 שאי אפשר לו לגוף להתקיים באופן זה? \u0003ר' זכאי אומר:\u0004"],["ברגל — אם נחתכה זו \u0003עד\u0004 למעלה מן \u0003הארכובה\u0004 (ברך) בבעל החיים, הריהו מת בכך, ואף גוף אטום נחשב כמת, ואין המפלת דמות שכזו נטמאת בטומאת לידה. ואילו \u0003ר' ינאי אומר:\u0004 בעל החיים נחשב למת, רק כאשר נחתכו רגליו \u0003עד ל\u0004מקום \u0003נקביו.\u0004 ואילו \u0003ר' יוחנן אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' יוסי בן יהושע\u0004 כי אין בעל החיים נחשב כמת אלא אם כן נחתכו רגליו \u0003עד מקום טבורו.\u0004","ומסבירים במה נחלקו חכמים אלה: \u0003בין ר'\u0004 \u0003זכאי לר' ינאי איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל זה, האם ה\u0003טרפה\u0004 (מי שסופה למות בשל מכה שישנה באחת מאיבריה) \u0003חיה\u0004 (עשויה לחיות מעבר לשנים עשר חדשים), ש\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' ינאי, \u0005סבור]\u0006 כי ה\u0003טרפה חיה,\u0004 ולכן אם נחתכו רגלי בעל חי רק עד למעלה מהברך אף שהוא טריפה, אינו נחשב כמת, והמפלת כדמותו טמאה טומאת לידה. ואולם אם נחתכו רגליו עד למקום נקביו, כיון שיצור חי מת בכך, אף המפלת כדמותו אינה נטמאת בכך טומאת לידה. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' זכאי, \u0005סבור]\u0006 כי \u0003טרפה אינה חיה,\u0004 ומשום כך אף המפלת כדמות זה שנחתכו רגליו עד למעלה מהארכובה אינה טמאה.","ואולם \u0003בין ר'\u0004 \u0003ינאי לר' יוחנן\u0004 אף ששניהם סבורים כי הטריפה חיה, \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לענין שיטתו של \u0003ר' אלעזר,\u0004 שכן \u0003אמר ר'\u0004 \u0003אלעזר\u0004 שכל בהמה ש\u0003ניטל ירך וחלל שלה\u0004 — הריהי נחשבת כ\u0003נבלה,\u0004 לענין טומאת נבילות. שר' ינאי סבור כר' אלעזר, ולכך אם נחתכו הרגלים עד למקום הנקבים הריהו נחשב כמת בכך. ואילו לדעת ר' יוחנן אין בעל החיים נחשב כמת אלא כן ניטלו רגליו עד מקום טבורו.","ועוד בהסבר מחלוקתם של ר' זכאי ור' ינאי ור' יוחנן, \u0003אמר רב פפא\u0004 ה\u0003מחלוקת\u0004 היא רק באופן שנחתך גופו של בעל החיים \u0003מלמטה ל\u0004כיוון \u0003מעלה,\u0004 מרגליו כלפי ראשו. \u0003אבל\u0004 כאשר נחתך הגוף \u0003מלמעלה ל\u0004כיוון \u0003מטה\u0004 — \u0003אפילו\u0004 נחתך \u0003כל דהו\u0004 \u0005[שהוא]\u0006 מגולגלתו, המפלת דמות שכזו הינה \u0003טהורה.\u0004 שודאי שאין זה חי. ומוסיפים: \u0003וכן אמר רב גידל, אמר ר'\u0004 \u0003יוחנן: המפלת את\u0004 הדבר \u0003שגולגלתו אטומה\u0004 (חסרה) — הרי \u0003אמו טהורה\u0004 (שאינה טמאה טומאת לידה).","\u0003ו\u0004מביאים עוד בדבר זה משמו של ר' יוחנן, \u0003אמר רב גידל, אמר ר'\u0004 \u0003יוחנן: המפלת\u0004 דבר שמראהו \u0003כמין אפקתא דדיקלא\u0004 \u0005[מוצאי הדקל,\u0006 החלק המפוצל שבו\u0005]\u0006 — \u0003אמו טהורה.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בדינה של האשה \u0003המפלת מי שפניו מוסמסים\u0004 (מעוכים במקצת), ש\u0003ר' יוחנן אמר\u0004 שהריהו נחשב כולד, ולכך \u0003אמו טמאה\u0004 טומאת לידה, ואילו \u0003ריש לקיש אמר\u0004 כי אין הוא נחשב כולד, ולכך \u0003אמו טהורה\u0004 מטומאת לידה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו בברייתא: האשה \u0003המפלת יד חתוכה\u0004 (שניכרים בה עיצובי האצבעות) \u0003ו\u0004כן המפלת \u0003רגל חתוכה\u0004 — \u0003אמו טמאה לידה,\u0004 שודאי באו אלה מן הדבר שהיה בראשיתו ולד גמור, \u0003ואין חוששין שמא מגוף אטום\u0004 (חסר, שאינו ולד) \u0003באתה\u0004 (באה יד או רגל זו). \u0003ו\u0004יש לדון בדברים הללו: \u0003אם איתא\u0004 \u0005[יש]\u0006 מקום לומר כדבריך, שהמפלת מי שפניו מוסמסים אינה נטמאת בכך — \u0003ליתני\u0004 \u0005[שישנה]\u0006 התנא בברייתא \"אין חוששים \u0003שמא מגוף אטום או ממי שפניו מוסמסין\u0004 באה\"!","ובהסבר המחלוקת \u0003אמר רב פפי: ב\u0004אשה המפלת מי ש\u0003פניו מוסמסין\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל,\u0006 הן ר' יוחנן והן ריש לקיש, \u0005אינם חלוקים\u0006 בדבר\u0005],\u0006 שאמו \u0003טמאה\u0004 בכך. ואולם \u0003כי פליגי\u0004 \u0005[כאשר נחלקו] — הרי זה\u0006 \u0003ב\u0004מפלת מי ש\u0003פניו טוחות\u0004 (שאין כל צורה ניכרת בהן), \u0003ו\u0004עוד הוסיף רב פפא, כי \u0003איפכא איתמר\u0004 \u0005[\u0006באופן \u0005הפוך נאמר]\u0006 הדבר, ש\u0003ר' יוחנן אמר\u0004 כי \u0003אמו\u0004 של המפלת מי שפניו טוחות \u0003טהורה, ו\u0004אילו \u0003ריש לקיש אמר\u0004 ש\u0003אמו טמאה.\u0004","ושואלים: \u0003ולותביה\u0004 \u0005[ויקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן מהא\u0004 \u0005[מ\u0006ברייתא \u0005זו]\u0006 באופן שהקשה ר' יוחנן לריש לקיש בלשון הקודמת, שאם אכן המפלת מי שפניו טוחות הריהי טהורה, היה לברייתא לומר שאין חוששים באשה המפלת יד חתוכה שמא באה מגוף אטום או ממי שפניו טוחות! ומתרצים: \u0003משום דשני ליה\u0004 \u0005[שיכול היה,\u0006 ר' יוחנן, \u0005להשיב לו,\u0006 לריש לקיש\u0005]\u0006 ולומר: לא אמרה כן הברייתא, כי \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003גוף אטום, היינו\u0004 \u0005[זהו]\u0006 \u0003מי שפניו טוחות.\u0004","ומוסרים כי \u0003בני ר'\u0004 \u0003חייא נפיק לקרייתא\u0004 \u0005[יצאו לכפרים]\u0006 להשגיח על שדות אביהם. כששבו, \u0003אתו לקמיה דאבוהון\u0004 \u0005[באו לפני אביהם],\u0006 \u0003אמר להם: כלום בא מעשה\u0004 שיש לדון בו \u0003לידכם? אמרו לו:\u0004 מקרה של אשה שהפילה מי שצורת \u0003פנים טוחות\u0004 לו, \u0003בא לידינו, וטימאנוה\u0004 בטומאת לידה.","\u0003אמר להם: צאו וטהרו מה שטמאתם.\u0004 \u0003שכן\u0004 \u0003מאי דעתייכו\u0004 \u0005[מה\u0006 היתה \u0005דעתכם]\u0006 כשטמאתם אותה — כי \u0003לחומרא\u0004 \u0005[להחמיר]\u0006 באתם, ואולם \u0003חומרא דאתיא\u0004 \u0005[החמרה שבאה]\u0006 \u0003לידי קולא\u0004 \u0005[הקלה]\u0006 \u0003היא\u0004 זו, \u0003דקיהביתו\u0004 \u0005[ש\u0006כן \u0005נותנים אתה]\u0006 \u0003לה\u0004 בכך \u0003ימי טוהר,\u0004 שתיחשב כשאר היולדות, ואם תראה דם בשלושים ושלושה הימים שלאחר ימי טומאתה, הריהי טהורה (כדינה של היולדת זכר).","ועוד \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בדינה של \u0003המפלת בריה שיש לה שני גבים ושני שדראות.\u0004 \u0003אמר רב:\u0004 לענין טומאת לידה \u0003באשה\u0004 המפילה ולד שכזה — \u0003אינו\u0004 נחשב כ\u0003ולד,\u0004 ואינה נטמאת בו. ו\u0003בבהמה\u0004 ולד כזה — \u0003אסור באכילה.\u0004 \u0003ו\u0004אילו \u0003שמואל אמר\u0004 כי \u0003באשה\u0004 — הריהו נחשב \u0003ולד,\u0004 ונטמאת בו אמו. וכן \u0003בבהמה\u0004 — הריהו \u0003מותר באכילה.\u0004","ומסבירים, \u0003במאי קמיפלגי\u0004 \u0005[במה הם חולקים]?\u0006 — \u0003ב\u0004דעתו של \u0003רב חנין בר אבא,\u0004 שכן \u0003אמר רב חנין בר אבא:\u0004 נאמר \"אך את זה לא תאכלו ממעלי הגרה וממפריסי הפרסה השסועה\" (דברים יד, ח). ו\u0003\"השסועה\"\u0004 שאמר הכתוב זו \u0003בריה שיש לה שני גבין ושני שדראות.\u0004","ובדבר זה נחלקו, ש\u0003רב אמר\u0004 כי סוג כזה של \u0003בריה בעלמא\u0004 \u0005[בעולם,\u0006 בחיים\u0005]\u0006 — \u0003ליתא\u0004 \u0005[איננו],\u0006 \u0003וכי אגמריה רחמנא\u0004 \u0005[וכאשר לימ דו הקדוש ברוך הוא]\u0006 \u0003למשה\u0004 את ההלכה הזו — לענין בריה הנמצאת \u0003במעי אמה אגמריה\u0004 \u0005[לימד ו],\u0006 שהיא אסורה באכילה. \u0003ו\u0004אילו \u0003שמואל אמר:\u0004 סוג כזה של \u0003בריה בעלמא\u0004 \u0005[בעולם]\u0006 \u0003איתא\u0004 \u0005[ישנו],\u0006 \u0003וכי אגמריה רחמנא\u0004 \u0005[וכאשר לימ דו הקדוש ברוך הוא]\u0006 \u0003למשה\u0004 שאסורה היא בריה שכזו — לענין בריה המצויה \u0003בעלמא אגמריה\u0004 \u0005[בעולם לימ דו],\u0006 שהיא אסורה באכילה, \u0003אבל\u0004 בריה כזו הנמצאת \u0003במעי אמה\u0004 — \u0003שריא\u0004 \u0005[מותרת]\u0006 באכילה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב שימי בר חייא לרב\u0004 ממה ששנינו בדיני הכהן בעל המום, ש\u0003ר' חנינא בן אנטיגנוס אומר\u0004 כי \u0003כל\u0004 כהן \u0003שיש לו שני גבין ושני שדראות\u0004 — הריהו \u0003פסול לעבודה,\u0004 \u0003אלמא דחיי\u0004 \u0005[הרי נסיק\u0006 מכאן \u0005שחי]\u0006 הוא יצור שכזה שיש לו שני גבים ושתי שדרות, אלא שבעל מום הוא! \u0003וקשיא\u0004 \u0005[וקשה]\u0006 איפוא \u0003לרב.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב לרב שימי, בתשובה לשאלתו: \u0003שימי את\u0004 \u0005[אתה],\u0006 שיפה שאלת. אבל אין דברי ר' חנינא בן אנטיגנוס אמורים במי שיש לו שתי שדרות, שהרי בריה שכזו אינה חיה, אלא במי \u0003ששדרתו עקומה,\u0004 ונראה כמי שיש לו שתי שדרות.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד ממה ששנינו בברייתא: \u0003יש בעוברין\u0004 שיצאו לאויר העולם \u0003שהן אסורין\u0004 באכילה משום איסור נבילה. ואלה הם: העובר שנולד בהיותו רק \u0003בן ארבעה\u0004 חדשים להריונו \u0003ל\u0004בהמה ה\u0003דקה\u0004 (צאן, עזים וכבשים), וכן זה הנולד בהיותו רק \u0003בן שמנה\u0004 חדשים להריונו \u0003ל\u0004בהמה ה\u0003גסה\u0004 (בקר, פרים ופרות). ואין הדברים אמורים אלא בעובר זה שנולד \u0003הימנו\u0004 (בשיעור זמן זה) \u0003ולמטה\u0004 (ופחות) מכך — הריהו \u0003אסור\u0004 באכילה. \u0003יצא\u0004 מכלל דינם של שאר עוברים, \u0003מי שיש לו שני גבין ושני שדראות.\u0004","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יצא\"? לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ש\u0003יצא\u0004 זה שיש לו שני גבים ושתי שדרות \u0003מכלל עוברין, שאפילו במעי אמן\u0004 הריהם \u0003אסורין,\u0004 ושלא כשיטת שמואל המתיר עובר שכזה באכילה.","ומסבירים: את הברייתא הזו, \u0003רב מתרץ לטעמיה\u0004 \u0005[מסביר לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003ו\u0004כן \u0003שמואל מתרץ לטעמיה\u0004 \u0005[מסביר לטעמו,\u0006 לשיטתו\u0005].\u0006 ומפרטים: \u0003רב מתרץ לטעמיה\u0004 \u0005[מסביר לטעמו,\u0006 לשיטתו\u0005],\u0006 ובאופן זה: \u0003בן ארבעה\u0004 חדשים \u0003ל\u0004בהמה \u0003דקה,\u0004 וכן בן שמונה חדשים \u0003ל\u0004בהמה \u0003גסה, הימנו ולמטה\u0004 — הריהו \u0003אסור.\u0004","\u0003במה דברים אמורים?\u0004 — רק \u0003כשיצא\u0004 כבר העובר \u0003לאויר העולם, אבל\u0004 כל עוד הוא \u0003במעי אמו\u0004 — הריהו \u0003שרי\u0004 \u0005[מותר]\u0006 באכילה. \u0003יצא מי שיש לו שני גבין ושני שדראות,\u0004 ש\u0003אפילו\u0004 בהיותו \u0003במעי אמו\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 הריהו \u0003אסור\u0004 באכילה."],["\u0003ו\u0004כן \u0003שמואל מתרץ לטעמיה\u0004 \u0005[מסביר\u0006 את הברייתא \u0005לטעמו,\u0006 לשיטתו\u0005],\u0006 ובאופן זה: \u0003בן ארבעה\u0004 חדשים \u0003ל\u0004בהמה ה\u0003דקה,\u0004 וכן \u0003בן שמנה\u0004 חדשים \u0003ל\u0004בהמה ה\u0003גסה,\u0004 כל ש\u0003הימנו ולמטה\u0004 (פחות מכך) — הריהו \u0003אסור\u0004 באכילה. \u0003במה דברים אמורים?\u0004 — דווקא \u0003ב\u0004זה \u0003שלא כלו לו חדשיו, אבל כלו לו חדשיו\u0004 — הריהו \u0003מותר\u0004 באכילה. ואולם \u0003יצא\u0004 מכלל זה \u0003מי שיש לו שני גבין ושני שדראות,\u0004 ש\u0003אף על גב\u0004 ש\u0003כלו לו חדשיו, אם יצא לאויר העולם\u0004 — הריהו \u0003אסור\u0004 באכילה, וכל עוד הוא \u0003במעי אמו\u0004 — הריהו \u0003שרי\u0004 \u0005[מותר]\u0006 באכילה.","ובאותו ענין \u0003תני תנא קמיה\u0004 \u0005[שנה שונה המשניות לפני]\u0006 \u0003רב: המפלת בריית גוף שאינו חתוך,\u0004 שאין בו חיתוך איברים וצורה, אלא הריהו חלק ושטוח, \u0003ו\u0004כן המפלת \u0003בריית ראש שאינו חתוך, יכול\u0004 ש\u0003תהא אמו טמאה לידה?\u0004 \u0003תלמוד לומר \"אשה כי תזריע וילדה זכר\u0004 וטמאה שבעת ימי כימי נדת דוותה תטמא. \u0003וביום השמיני ימול\u0004 בשר ערלתו\" (ויקרא יב, ב—ג) — דין טומאת לידה נאמר רק על לידת","מי שראוי להגיע \u0003לברית\u0004 מילתו ב\u0003שמנה\u0004 ימים ללידתו. \u0003יצאו\u0004 מכלל דין טומאת הלידה \u0003אלו, שאינן ראויין\u0004 להתקיים עד \u0003לברית שמנה.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב\u0004 לשונה המשניות שלפניו: \u0003וסיים בה,\u0004 בברייתא זו, \u0003הכי\u0004 \u0005[כך],\u0006 \"יצאו אלו \u0003ו\u0004מי \u0003שיש לו שני גבין ושני שדראות.\u0004 שלדעת רב המפלת ולד שיש לו שני גבים ושתי שדרות אינה נטמאת בכך.","ומסופר כי \u0003ר' ירמיה בר אבא סבר למעבד עובדא כוותיה\u0004 \u0005[חשב לעשות,\u0006 לקבוע הלכה \u0005למעשה כמותו,\u0006 כשיטתו\u0005]\u0006 של שמואל, ולטמא אשה שילדה מי שיש לו שני גבים ושתי שדרות, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא\u0004 לר' ירמיה: \u0003מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 שאתה מבקש להורות כך — שכן רצונך \u0003ל\u0004נהוג \u0003חומרא\u0004 \u0005[החמרה]?\u0006 ואולם \u0003חומרא דאתי\u0004 \u0005[החמרה שבאה]\u0006 \u0003לידי קולא\u0004 \u0005[הקלה]\u0006 \u0003הוא, דקיהבת\u0004 \u0005[ש\u0006כן \u0005נתת]\u0006 \u0003לה\u0004 בכך דמי טוהר, שאם תראה אותה אשה דם בשלושים ושלושה הימים (ביולדת זכר) שלאחר ימי טומאתה תבוא לטהר עצמה. \u0003עביד מיהא כותיה\u0004 \u0005[עשה לפחות כמותו,\u0006 כשיטתו\u0005]\u0006 של \u0003רב, דקיימא לן\u0004 \u0005[ש\u0006כלל \u0005עומד,\u0006 מקובל \u0005לנו]:\u0006 \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב באיסורי\u0004 \u0005[באיסורים],\u0006 \u0003בין לקולא\u0004 \u0005[להקלה]\u0006 \u0003בין לחומרא\u0004 \u0005[להחמרה].\u0006","למעלה הובאו דברי הברייתא בדינם של עוברים הנולדים קודם זמנם לבהמה הדקה ולבהמה הגסה. ובענין זה מביאים עוד מה ש\u0003אמר רבא: הרי אמרו\u0004 חכמים כי \u0003אשה יולדת\u0004 כרגיל \u0003לתשעה\u0004 חדשי הריון \u0003ו\u0004כן \u0003יולדת לשבעה\u0004 חדשי הריון, ואילו היולדת לשמונה חדשי הריון — אין הולד מתקיים, שנפל הוא. וכן ב\u0003בהמה\u0004 ה\u0003גסה\u0004 שהיא \u0003יולדת לתשעה\u0004 חדשי עיבור, ואם ילדה לשמונה חדשי עיבור, אין הולד מתקיים, שנפל הוא. ומעתה יש לברר האם אף הבהמה הגסה \u0003יולדת לשבעה, או\u0004 שהיא \u0003לא ילדה\u0004 \u0005[יולדת]\u0006 לשבעה חדשי עיבור?","\u0003אמר רב נחמן בר יצחק: תא שמע\u0004 \u0005[בוא\u0006 ושמע] ראיה לדבר ממה ששנינו בברייתא זו: \u0003הימנו ולמטה\u0004 (פחות מכך) — הולד \u0003אסור\u0004 באכילה משום איסור נבילה. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מתייחסים הדברים לבהמה ה\u0003גסה?!\u0004 והרי איפוא ראיה שאין הבהמה הגסה יולדת לשבעה! ודוחים: \u0003לא,\u0004 הדברים מתייחסים רק לבהמה ה\u0003דקה,\u0004 שדרכה ללדת לחמישה חדשי עיבור.","ותוהים על הדחיה: \u0003האי מאי\u0004 \u0005[זה מה\u0006 תשובה היא\u0005]?\u0006 שכן \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שדברי הברייתא מתייחסים לבהמה ה\u0003גסה\u0004 — מעתה מובן מדוע \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003הואיל ובאשה\u0004 הנולד בפחות מתשעה חדשי הריון הריהו \u0003חיי\u0004 \u0005[חי],\u0006 וכדרך הנולד לשבעה, אם כן מסתבר לומר כי הנולד \u0003בבהמה\u0004 הגסה קודם זמן עיבורו הרגיל, \u0003נמי חיי\u0004 \u0005[גם כן חי],\u0006 ולא ייאסר באכילה. לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 התנא בברייתא, \u0005משמיע לנו]\u0006 \u0003דלא חיי\u0004 \u0005[שאינו חי].\u0006","\u0003אלא אי אמרת אדקה איתמר\u0004 \u0005[אם אומר אתה שעל\u0006 בהמה \u0005דקה נאמר],\u0006 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר, וכי זו הנולדת \u0003בת תלתא ירחי\u0004 \u0005[שלשה חודשים]\u0006 של עיבור \u0003מי קא חיי\u0004 \u0005[האם היא חיה]?\u0006","ומשיבים: יש מקום להעמיד את הדברים כמתייחסים לבהמה הדקה, ועדיין \u0003אצטריך\u0004 \u0005[נצרך]\u0006 הדבר להיאמר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 ש\u0003כל\u0004 הנולד \u0003בציר תרי ירחי חיי\u0004 \u0005[פחות שני חודשים חיה],\u0006 כזה הנולד לשלושה חדשי עיבור, לכן \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 התנא שבברייתא, \u0005משמיע לנו]\u0006 שאין זה חי, ולכך הריהו אסור באכילה כנבילה.","ועוד בדיני המפלת ולד שאין צורתו מוגמרת. \u0003אמר רב יהודה, אמר שמואל: המפלת דמות לילית\u0004 (שדה, שיש לו פרצוף אדם ויש לו כנפיים) — \u0003אמו טמאה לידה.\u0004 שכן \u0003ולד הוא\u0004 זה, \u0003אלא שיש לו כנפים.\u0004 ומביאים ראיה לדבר, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אמר ר'\u0004 \u0003יוסי: מעשה\u0004 שאירע בישוב \u0003סימוני ב\u0004אשה \u0003אחת שהפילה דמות לילית, ובא מעשה לפני חכמים\u0004 לדון בו, \u0003ואמרו\u0004 חכמים: \u0003ולד הוא, אלא שיש לו כנפים.\u0004","ועוד כיוצא בזה, בדינה של \u0003המפלת\u0004 כ\u0003דמות נחש, הורה חנינא בן אחיו של ר'\u0004 \u0003יהושע\u0004 כי \u0003אמו טמאה לידה.\u0004 ומסופר כי הלך ר' י \u0003וסף וספר\u0004 את הדברים (שכך הורה חנינא בן אחיו של ר' יהושע) \u0003לפני רבן גמליאל, שלח לו\u0004 רבן גמליאל ל\u0003ר' יהושע: הנהג\u0004 (קח אתך) את \u0003בן אחיך ובא\u0004 אלי, שרצה לנזוף בו על הוראתו זו!","ומסופר כי \u0003ב\u0004עת \u0003הליכתן\u0004 לרבן גמליאל \u0003יצתה\u0004 (יצאה) כלת (ר') \u0003חנינא לקראתו\u0004 של ר' יהושע, \u0003אמרה לו\u0004 בשאלה: \u0003רבי,\u0004 אשה \u0003המפלת כמין נחש מהו\u0004 דינה לענין טומאת לידה? \u0003אמר לה: אמו טהורה.\u0004 \u0003אמרה לו: והלא משמך אמרה לי חמותי\u0004 כי \u0003אמו\u0004 של המפלת כמין נחש \u0003טמאה? ו\u0004הוסיפה חמותי ואמרה לי כי ר' יהושע \u0003אמר לה\u0004 \u0003מאיזה טעם\u0004 הורה כן — \u0003הואיל וגלגל עינו\u0004 של הנחש הריהו \u0003עגול כשל אדם! מתוך דבריה נזכר ר'\u0004 \u0003יהושע\u0004 שאכן כך הורה. עמד ו\u0003שלח לו לרבן גמליאל: מפי הורה חנינא.\u0004","\u0003אמר אביי, שמע מינה\u0004 \u0005[למד ממנה,\u0006 ממעשה זה\u0005]\u0006 כי \u0003צורבא מרבנן\u0004 \u0005[תלמיד חכם]\u0006 ש\u0003אמר מילתא\u0004 \u0005[דבר]\u0006 הלכה — \u0003לימא\u0004 \u0005[שיאמר]\u0006 \u0003בה\u0004 גם \u0003טעמא\u0004 \u0005[הטעם]\u0006 לדבר זה שאמר, משום \u0003דכי מדכרו ליה\u0004 \u0005[שכאשר יזכירו לו]\u0006 — על ידי כך הריהו \u0003מדכר\u0004 \u0005[נזכר],\u0006 וכדדך שאירע כן לר' יהושע.","\u0003ה\u0004אשה ה\u0003מפלת שפיר\u0004 (מעטפת העור בה שרוי העובר במעי אמו) והוא \u0003מלא מים,\u0004 או שהוא \u0003מלא דם,\u0004 או שהוא \u0003מלא גנונים\u0004 (גוונים שונים) — הרי זו \u0003אינה חוששת\u0004 שמא היה זה \u0003ולד.\u0004 \u0003ו\u0004אולם \u0003אם היה\u0004 שפיר זה בשלב התפתחות שהוא כבר \u0003מרוקם\u0004 (שנרקמה בו צורת עובר) — הרי זו נוהגת ככל יולדת ולד. ומאחר שספק הוא מהו מינו של עובר זה, יש להחמיר בה שתנהג הן כיולדת זכר והן כיולדת נקבה. ולכן \u0003תשב\u0004 ימי טהרה כמו \u0003ל\u0004יולדת \u0003זכר,\u0004 שלושים ושלושה ימים בלבד, \u0003ו\u0004אולם \u0003ל\u0004ענין ימי טומאה תשב כיולדת \u0003נקבה,\u0004 שבועיים ולא שבעה ימים בלבד. האשה \u0003המפלת\u0004 חתיכת בשר ללא צורת פני אדם אלא כ\u0003סנדל או\u0004 המפלת \u0003שליא\u0004 (הנרתיק בו מונח העובר בהיותו במעי אמו) — אף זו מחמירים בה מן הספק, ויהא דינה ש\u0003תשב\u0004 ימי טומאה וטהרה כמו \u0003ל\u0004יולדת \u0003זכר ול\u0004יולדת \u0003נקבה.\u0004","שנינו במשנתנו שהמפלת שפיר מלא מים או מלא דם, או מלא גנונים — אינה חוששת לולד. ושואלים על כך: \u0003בשלמא\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 שאין חוששים לולד בשפיר המלא \u0003דם, ו\u0004כן בשפיר המלא \u0003מים,\u0004 שהרי \u0003לא כלום היא,\u0004 שאין דבר זה סימן לולד. \u0003אלא\u0004 המפלת שפיר מלא \u0003גנונים\u0004 — \u0003ניחוש\u0004 \u0005[נחשוש]\u0006 בו \u0003שמא ולד הוה\u0004 \u0005[היה]\u0006 \u0003ונימוח? אמר אביי:\u0004 אין לחשוש שנימוח הולד, משום ש\u0003כמה יין חי\u0004 שהוא מרוכז מאוד, ויש בו כדי לפגוע בעובר שמעי אמו \u0003שתת\u0004 (שתתה) \u0003אמו של זה\u0004 שגרם \u0003שנימוח עוברה בתוך מעיה?\u0004","\u0003רבא אמר\u0004 הסבר אחר: \u0003\"מלא\u0004 גנונים\" \u0003תנן\u0004 \u0005[שנינו]\u0006 במשנתנו, ובמודגש ללמדנו שנוהג דין זה דווקא שהשפיר מלא, \u0003ו\u0004משום ש\u0003אם איתא דאתמוחי אתמח\u0004 \u0005[אם יש\u0006 מקום לומר \u0005שנמוח]\u0006 — הרי הוא היה \u0003מחסר חסר\u0004 \u0005[נחסר]\u0006 ולא היה מלא. \u0003רב אדא בר אהבה אמר\u0004 הסבר אחר: \u0003\"גוונים\" תנן\u0004 \u0005[שנינו],\u0006 \u0003ואם איתא דאתמוחי אתמח\u0004 \u0005[יש\u0006 מקום לומר \u0005שנמוח]\u0006 — \u0003כולה בחד גוונא הוי קאי\u0004 \u0005[הכל בגוון אחד היה עומד].\u0006","ובענין השפעת היין על גוף האדם, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אבא שאול אומר: קובר מתים הייתי, והייתי מסתכל\u0004 (מתבונן) \u0003בעצמות של\u0004 ה\u0003מתים.\u0004 וראיתי כי \u0003ה\u0004אדם שבחייו היה \u0003שותה יין חי\u0004 — גרם הדבר לכך ש\u0003עצמותיו שרופין,\u0004 וזה השותה יין \u0003מזוג\u0004 במים — \u0003עצמותיו סכויין\u0004 (שחורות), ואילו זה השותה יין \u0003כראוי\u0004 — \u0003עצמותיו משוחין\u0004 (שמנות, לא יבשות). \u0003ו\u0004עוד למדתי מהתבוננות בעצמות המתים כי \u0003כל מי ששתייתו מרובה מאכילתו\u0004 — \u0003עצמותיו שרופין,\u0004 ומי ש\u0003אכילתו מרובה משתייתו\u0004 — \u0003עצמותיו סכויין,\u0004 ואילו זה שאכילתו ושתייתו הינן \u0003כראוי\u0004 — \u0003עצמותיו משוחין.\u0004","ועוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אבא שאול אומר, ואיתימא\u0004 \u0005[ויש שאומר\u0006 דבר זה\u0005]\u0006 בשמו של ר' יוחנן: קובר מתים הייתי. \u0003פעם אחת רצתי אחר צבי, ונכנסתי ב\u0004תוך \u0003קולית\u0004 (עצם הירך) \u0003של מת\u0004 שהיתה כה גדולה עד ש\u0003רצתי אחריו\u0004 עוד \u0003שלש פרסאות\u0004 בתוך עצם הקולית, \u0003ו\u0004אל ה\u0003צבי לא הגעתי, ו\u0004אילו ה\u0003קולית לא כלתה.\u0004 \u0003כשחזרתי לאחורי,\u0004 וסיפרתי הדברים לחכמים, \u0003אמרו לי:\u0004 קולית זו \u0003של עוג מלך הבשן היתה.\u0004","ועוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בדומה, \u0003אבא שאול אומר: קובר מתים הייתי.\u0004 \u0003פעם אחת נפתחה מערה\u0004 המשמשת לקבורה \u0003תחתי\u0004 וצנחתי אל תוכה, \u0003ו\u0004נמצא ש\u0003עמדתי ב\u0004תוך \u0003גלגל עינו של מת עד חוטמי,\u0004 שכה גדולה היתה עין זו. ו\u0003כשחזרתי לאחורי,\u0004 וסיפרתי הדברים לחכמים, \u0003אמרו\u0004 לי: \u0003עין של אבשלום היתה\u0004 זו.","\u0003ושמא תאמר: אבא שאול ננס הוה\u0004 \u0005[היה],\u0006 ולכן אירע לו כך — אל תאמר כן, שהרי \u0003אבא שאול ארוך בדורו הוה\u0004 \u0005[היה],\u0006 \u0003ור' טרפון\u0004 היה \u0003מגיע\u0004 רק עד \u0003לכתפו, ור' טרפון\u0004 עצמו \u0003ארוך בדורו הוה\u0004 \u0005[היה],\u0006 \u0003ור' מאיר\u0004 היה \u0003מגיע\u0004 רק עד \u0003לכתפו,\u0004 ו\u0003ר' מאיר ארוך בדורו הוה\u0004 \u0005[היה]\u0006 \u0003ורבי מגיע לכתפו,\u0004 ו\u0003רבי ארוך בדורו הוה\u0004 \u0005[היה]\u0006","\u0003ור' חייא מגיע לכתפו, ור' חייא ארוך בדורו הוה\u0004 \u0005[היה]\u0006 \u0003ורב מגיע לכתפו,\u0004 ו\u0003רב ארוך בדורו הוה\u0004 \u0005[היה]\u0006 \u0003ורב יהודה מגיע לכתפו, ורב יהודה ארוך בדורו הוה\u0004 \u0005[היה]\u0006 \u0003ואדא דיילא\u0004 \u0003(השמש) מגיע לכתפו,\u0004"],["\u0003פרשתבינא\u0004 \u0005[מושל\u0006 העיר\u0005]\u0006 \u0003פומבדיתא קאי ליה\u0004 \u0005[היה עומד לו]\u0006 בצידו של \u0003אדא דיילא,\u0004 והיה מגיע רק \u0003עד פלגיה\u0004 \u0005[מחציתו],\u0006 \u0003וכולי עלמא קאי לפרשתבינא דפומבדיתא\u0004 \u0005[שהכל היו עומדים ל\u0006צידו של \u0005מושל פומבדיתא]\u0006 זה, והיו מגיעים רק \u0003עד חרציה\u0004 \u0005[מתניו].\u0006 ומכאן נסיק כמה גבוה היה אבא שאול, וכמה ענק היה גלגל עין זה של אבשלום.","שנינו במשנתנו דין המפלת שפיר המלא מים או דם או גנונים. ובענין דומה \u0003שאלו\u0004 התלמידים היושבים \u0003לפני רבי: המפלת שפיר מלא בשר מהו\u0004 דינה לענין טומאת לידה? \u0003אמר להם: לא שמעתי\u0004 מפי רבותי.","\u0003אמר לפניו ר'\u0004 \u0003ישמעאל בר' יוסי: כך אמר אבא\u0004 (ר' יוסי בן חלפתא, שהיה מרבותיו של רבי): הפילה שפיר \u0003מלא דם\u0004 — \u0003טמאה\u0004 טומאת \u0003נדה,\u0004 ואם הפילה שפיר \u0003מלא בשר\u0004 — הריהי \u0003טמאה\u0004 טומאת \u0003לידה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אילמלי\u0004 (אילו) מסורת זו שבידיך היתה כולה \u0003דבר חדש\u0004 (שלא אמרו חכם אחר), ואותה בלבד \u0003אמרת לנו משום\u0004 (בשם) \u0003אביך\u0004 — \u0003שמענוך\u0004 (היינו מקבלים ממך). ואולם \u0003עכשיו\u0004 שאמרת לנו בשמו שני דברים, דין המפלת שפיר מלא דם ודין המפלת שפיר מלא בשר —","\u0003מדהא קמייתא כיחידאה קאמר\u0004 \u0005[מ\u0006תוך \u0005שזו,\u0006 ההלכה \u0005הראשונה,\u0006 בדין המפלת שפיר מלא דם, \u0005כ\u0006חכם \u0005יחיד הוא אמר],\u0006 \u0003כסומכוס שאמר\u0004 כן \u0003משום\u0004 \u0005[בשם]\u0006 \u0003ר' מאיר,\u0004 אף שחלוקים עליו חכמים, \u0003הא נמי\u0004 \u0005[\u0006ב\u0005זו,\u0006 בהלכה השניה, בדין המפלת שפיר מלא בשר \u0005גם כן]\u0006 יש מקום לומר \u0003שמא כ\u0004שיטת חכם יחידי אחר, \u0003ר' יהושע, אמרה\u0004 אביך, ואין הלכה כר' יהושע.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003המפלת שפיר שאינו מרוקם\u0004 (שטרם נרקמה בו צורת עובר לאיבריו) — \u0003ר' יהושע אומר:\u0004 אף שטרם נרקמו איבריו הריהו נחשב \u0003ולד\u0004 בשל עורו, וטמאה אמו בטומאת לידה. \u0003וחכמים אומרים:\u0004 כיון שלא נרקמו איבריו, \u0003אינו\u0004 נחשב כ\u0003ולד.\u0004 ומעתה יש מקום לומר שכשיטת ר' יהושע אמר אביך ר' יוסי את דבריו בענין השפיר המלא בשר, שנחשב לוולד, וכיון שחלוקים חכמים על ר' יהושע, ואין הלכה כמותו, אפשר שאף מסורת זו שבידך אין הלכה כמותה.","ובהסבר מחלוקת זו שבין ר' יהושע וחכמים, \u0003אמר ר'\u0004 \u0003שמעון בן לקיש משום\u0004 \u0005[בשם]\u0006 \u0003ר' אושעיא: מחלוקת\u0004 זו הריהי דווקא \u0003ב\u0004שפיר שטרם נרקמו איבריו, ומי השפיר \u0003עכור.\u0004 שלדעת ר' יהושע מסתבר שהיה בשפיר ולד, ונימוח, והרי אלו מימיו, והאשה טמאה לידה. ולדעת חכמים אין בכך כדי להוכיח. \u0003אבל ב\u0004מקרה שמי השפיר הינם \u0003צלול\u0004 — ל\u0003דברי הכל,\u0004 ואף לר' יהושע, \u0003אינו\u0004 נחשב ל\u0003ולד.\u0004 \u0003ור' יהושע בן לוי אמר:\u0004 דווקא \u0003בצלול\u0004 היא המחלוקת שבין ר' יהושע וחכמים.","ודנו התלמידים בהבנת הסברו, וזו השאלה ש\u0003איבעיא להו\u0004 \u0005[נשאלה להם]:\u0006 מה כוונת דבריו של ר' יהושע בן לוי, האם דווקא \u0003בצלול\u0004 היא ה\u0003מחלוקת\u0004 שבין ר' יהושע לחכמים, \u0003אבל בעכור\u0004 — ל\u0003דברי הכל,\u0004 ואף לשיטת חכמים, הרי זה נחשב \u0003ולד, או דלמא\u0004 \u0005[שמא]\u0006 \u0003בין בזה\u0004 (בעכור) \u0003ובין בזה\u0004 (בצלול) \u0003מחלוקת,\u0004 שאף בעכור סבורים חכמים שאינו ולד. והשמיענו ר' יהושע בן לוי שר' יהושע סובר שאף בצלול הרי זה נחשב ולד. ונותרה שאלה זו ללא ממענה, ומסכמים: \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה, ללא פתרון. ודנים עתה בהסבריהם של ריש לקיש ור' יהושע בן לוי במחלוקת ר' יהושע וחכמים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא, \u0003את זו דרש ר' יהושע בן חנניא: \"ויעש ה' אלהים לאדם ולאשתו כתנות עור וילבשם\"\u0004 (בראשית ג, כא) — הרי \u0003מלמד\u0004 כתוב זה \u0003שאין הקדוש ברוך הוא עושה עור לאדם אלא אם כן נוצר\u0004 תחילה האדם, שקודם נוצרו האדם ואשתו, ורק לאחר מכן ניתן להם העור (\"לאדם ולאשתו כתנות עור\").","ונסיק מכאן: \u0003אלמא\u0004 \u0005[הרי איפוא]:\u0006 לשיטת ר' יהושע (הוא ר' יהושע בן חנניה שדרש כן) \u0003בעור תליא מילתא\u0004 \u0005[תלוי הדבר],\u0006 ו\u0003לא שנא\u0004 \u0005[משנה]\u0006 הדבר אם מימי השפיר \u0003עכור ולא שנא\u0004 \u0005[משנה]\u0006 אם הוא \u0003צלול.\u0004","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[זה נוח אם אומר אתה]\u0006 כהסבר ר' יהושע בן לוי במחלוקת ר' יהושע וחכמים ש\u0003בצלול\u0004 היא ה\u0003מחלוקת\u0004 בין ר' יהושע לחכמים, — הרי איפוא שלשיטת ר' יהושע נחשב השפיר כולד, בין בצלול ובין בעכור, ו\u0003היינו דאיצטריך קרא\u0004 \u0005[זהו שהוצרך הכתוב]\u0006 להשמיענו שכל שיש בו עור הריהו נחשב ולד. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כהסברו של ריש לקיש בשיטת ר' יהושע ש\u0003בעכור\u0004 היא ה\u0003מחלוקת\u0004 בין ר' יהושע לחכמים, אבל בצלול מודה ר' יהושע שאינו נחשב ולד — \u0003למה לי קרא\u0004 \u0005[כתוב]\u0006 להשמיענו זאת? והלא \u0003סברא בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא,\u0004 שנחשב ולד, ותטמא בו אמו בטומאת לידה! \u0003אלא שמע מינה\u0004 \u0005[למד ממנה,\u0006 מכאן\u0005]\u0006 כי \u0003בצלול\u0004 היא ה\u0003מחלוקת\u0004 שבין ר' יהושע וחכמים, וכהסברו של ר' יהושע בן לוי. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכך הוא.","ומעירים: \u0003וכן\u0004 כהסברו זה של ריש לקיש במחלוקת ר' יהושע וחכמים, \u0003אמר רב נחמן\u0004 שכך \u0003אמר רבה בר אבוה: מחלוקת\u0004 זו היא דווקא \u0003ב\u0004מפלת שפיר \u0003עכור, אבל ב\u0004מפלת שפיר \u0003צלול\u0004 — ל\u0003דברי הכל אינו ולד.\u0004","\u0003איתיביה\u0004 \u0005[הקשה]\u0006 על כך \u0003רבא לרב נחמן\u0004 ממה ששנינו במשנה במסכת בכורות שלא רק ולד ממש הנולד לבהמה המבכירה פוטר את הנולד אחריו מן הבכורה, \u0003אלא אמרו\u0004 חכמים שאף סימן ולד פוטר אותו. ומהו \u0003סימן ולד\u0004 זה? \u0003בבהמה דקה\u0004 — \u0003טינוף\u0004 (דם מזוהם המופרש מן הרחם) הריהו משמש כסימן לולד שהיה במעיה, ונמחה. ו\u0003ב\u0004בהמה \u0003גסה\u0004 — יציאתה של \u0003שליא\u0004 (נרתיק בו נמצא העובר במעי אמו). ואילו סימן לולד \u0003באשה\u0004 — יציאת \u0003שפיר ו\u0004כן יציאת \u0003שליא.\u0004","ונדייק בדברים אלו: דווקא יציאת שליה פוטרת מן הבכורה את הוולד הנולד אחר כך בבהמה גסה, \u0003ואילו\u0004 יציאת \u0003שפיר בבהמה\u0004 גסה — \u0003לא פטר\u0004 \u0005[אינה פוטרת].\u0006 ומעתה יש לשאול: \u0003אי אמרת בשלמא\u0004 \u0005[זה נוח אם אתה אומר]\u0006 ש\u0003ב\u0004שפיר \u0003צלול\u0004 היא ה\u0003מחלוקת\u0004 של ר' יהושע וחכמים — \u0003משום הכי\u0004 \u0005[כך]\u0006 אפשר להבין מדוע כך הוא הדין בבהמה גסה, שכן ב","\u0003אשה דרבי\u0004 \u0005[שריבה]\u0006 \u0003בה קרא\u0004 \u0005[הכתוב]\u0006 האמור למעלה, \"לאדם ולאשתו כתנות עור\" והרי שבעור תלוי הדבר, שכיון שיש לו עור הריהו נחשב כולד, אף בצלול. ומעתה נאמר: באשה שיש בה לימוד מיוחד זה — \u0003פטר\u0004 \u0005[פוטר]\u0006 \u0003בה\u0004 ה\u0003שפיר\u0004 את הנולד אחריו מן הבכורה, ואילו \u0003בבהמה\u0004 ש\u0003לא רבי\u0004 \u0005[ריבה]\u0006 בה \u0003קרא\u0004 \u0005[הכתוב]\u0006 — \u0003לא פטר\u0004 \u0005[פוטר]\u0006 \u0003בה\u0004 ה\u0003שפיר\u0004 את הנולד אחריו מקדושת בכורה.","\u0003אלא אי אמרת\u0004 \u0005[אומר אתה]\u0006 ש\u0003בעכור\u0004 היא \u0003מחלוקת\u0004 ר' יהושע וחכמים, ור' יהושע מן הסברה אמר שהשפיר העכור נחשב כולד, ואילו חכמים סבורים שאינו נחשב כולד, \u0003מכדי\u0004 \u0005[מכיון]\u0006 ש\u0003סברא הוא\u0004 יסוד שיטותיהם, \u0003מאי שנא\u0004 \u0005[במה שונה,\u0006 מיוחדת\u0005]\u0006 היא ה\u0003אשה\u0004 שהשפיר פוטר בה את הנולד אחריו, \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 היא ה\u0003בהמה\u0004 שאין השפיר פוטר בה את הנולד אחריו מן הבכורה?","ודוחים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שר' יהושע מפשט פשיט ליה \u0005[פשוט לו]\u0006 שהשפיר העכור נחשב ולד? אין זה כך, אלא \u0003ר' יהושע ספוקי מספקא ליה\u0004 \u0005[מסופק לו]\u0006 בדינו של השפיר העכור, \u0003ואזיל הכא לחומרא\u0004 \u0005[והולך כאן להחמיר],\u0006 \u0003והכא לחומרא\u0004 \u0005[וכאן להחמיר],\u0006 ובאופן זה:","\u0003גבי\u0004 \u0005[אצל,\u0006 בענין\u0005]\u0006 ה\u0003אשה\u0004 שהפילה שפיר עכור, כיון שענין \u0003דממונא\u0004 \u0005[של ממון]\u0006 \u0003הוא,\u0004 אם חייבים לפדות את הבן הנולד לאחר יציאת שפיר זה — הרי כלל הלכתי הוא שב\u0003ספק ממונא\u0004 \u0005[ממון]\u0006 — נוהגים \u0003לקולא\u0004 \u0005[להקל],\u0006 ומן הספק פוטר שפיר זה את הנולד אחריו מפדיונו.","ואילו \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003בהמה,\u0004 שענין \u0003דאיסורא\u0004 \u0005[של איסור]\u0006 \u0003הוא דאיכא\u0004 \u0005[שיש]\u0006 ביחס לולד שיוולד אחריו לבהמה זו, לגבי (לענין) ה\u0003גיזה ו\u0004ה\u0003עבודה\u0004 בו, שכן אין גוזזים ואין עובדים בבכור בהמה — כלל הלכתי הוא: בכל \u0003ספק איסורא\u0004 \u0005[איסור]\u0006 — נוהגים \u0003לחומרא\u0004 \u0005[להחמיר].\u0006 ולכן אין השפיר העכור פוטר את הנולד אחריו מן הבכורה. ו\u0003הכי נמי גבי\u0004 \u0005[כך גם כן אצל]\u0006 ה\u0003אשה\u0004 היולדת שפיר, אף שהקל בה לענין הנתינה לכהן, ביחס ל\u0003ספק טומאה\u0004 שיש בה — נוהגים בו \u0003לחומרא\u0004 \u0005[להחמיר].\u0006","ושואלים על הסבר זה: \u0003ומי מספקא ליה\u0004 \u0005[והאם מסופק הוא]\u0006 ר' יהושע בעניינה של היולדת שפיר, \u0003והא קרא קאמר\u0004 \u0005[והרי מקרא הוא אמר],\u0006 שממנו למד שנוהגת היא בשפיר ככל היולדת ולד! ומשיבים: דינו זה של ר' יהושע הוא רק \u0003מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 \u0003וקרא\u0004 \u0005[ומקרא]\u0006 זה שהביא — \u0003אסמכתא בעלמא\u0004 \u0005[סמך בלבד]\u0006 \u0003הוא.\u0004","ולאחר שהובאו שיטותיהם השונות של חכמים בדין האשה המפלת שפיר מלא בשר, מביאים מה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנינא בר שלמיא לרב: הא\u0004 \u0005[זו]\u0006 היא שיטת \u0003רבי\u0004 שענה לתלמידיו שלא שמע מרבותיו מה דינה של המפלת שפיר מלא בשר. ו\u0003הא\u0004 \u0005[זו]\u0006 היא שיטת \u0003ר' ישמעאל בר' יוסי\u0004 שאמר בשם אביו שהמפלת שפיר מלא בשר טמאה טומאת לידה. \u0003והא\u0004 \u0005[וזו]\u0006 היא שיטת \u0003ר' אושעיא\u0004 הסבור שנחלקו ר' יהושע וחכמים בשפיר שאינו מרוקם שהוא עכור, ולא שהוא צלול. \u0003והא\u0004 \u0005[וזו]\u0006 היא שיטת \u0003ר' יהושע בן לוי\u0004 הסבור שנחלקו ר' יהושע וחכמים במפלת שפיר שאינו מרוקם שהוא צלול, ומעתה יש לשאול: \u0003מר, כמאן סבירא ליה\u0004 \u0005[אדוני, כ\u0006שיטת \u0005מי הוא סבור]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אני אומר\u0004 ש\u0003אחד זה ואחד זה,\u0004 שבין שהוא עכור ובין שהוא צלול — האשה המפלת שפיר זה \u0003אינה חוששת\u0004 שהוא ולד.","\u0003ו\u0004אילו \u0003שמואל אמר: אחד זה ואחד זה\u0004 — \u0003חוששת.\u0004 \u0003ו\u0004מסבירים את שיטת שמואל, \u0003אזדא\u0004 \u0005[הולך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003דכי אתא\u0004 \u0005[ש\u0006כן \u0005כאשר בא]\u0006 \u0003רב דימי\u0004 והביא עמו מסורות הלכתיות רבות, \u0003אמר: מעולם לא דכו\u0004 \u0005[טיהרו]\u0006 חכמים אשה שהפילה \u0003שפיר\u0004 מטומאת לידה \u0003בנהרדעא\u0004 עירו של שמואל, \u0003לבר מההוא שפירא דאתא לקמיה\u0004 \u0005[מלבד שפיר אחד שבא לפני]\u0006 \u0003שמואל, דמנח עליה\u0004 \u0005[שהניח עליו]\u0006 \u0003חוט השערה מהאי גיסא\u0004 \u0005[מצד זה]\u0006 של השפיר, \u0003וחזיא מהאי גיסא\u0004 \u0005[וראהו מצד זה],\u0006 שכל כך שקוף היה השפיר הזה. \u0003אמר\u0004 שמואל: על סמך בדיקה זו: \u0003אם איתא\u0004 \u0005[יש]\u0006 ש\u0003ולד הואי\u0004 \u0005[היה]\u0006 — \u0003לא הוה זיג כולי האי\u0004 \u0005[לא היה שקוף כל כך].\u0006","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003אם היה\u0004 השפיר שהפילה כבר \u0003מרוקם\u0004 — הריהי טמאה טומאת לידה, ומספק יושבת ימי טומאה וימי טהרה כיולדת זכר וכיולדת נקבה. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003איזהו שפיר\u0004 המוגדר \u0003כמרוקם? אבא שאול אומר:\u0004 העובר \u0003תחלת ברייתו\u0004 (בריאתו, היווצרותו) הינה \u0003מראשו, ושתי עיניו\u0004 הריהן \u0003כשתי טיפין\u0004 (טיפות) \u0003של זבוב,\u0004 כשתי עיניו. ומעירים באשר להגדרה זו של השפיר המרוקם, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא:\u0004 ובלבד שתהיינה שתי עיניו של השפיר המרוקם \u0003מרוחקין זה מזה.\u0004 וממשיכים בתיאור השפיר המרוקם: \u0003שני חוטמין\u0004 (נחירי האף) של השפיר המרוקם הריהם \u0003כשתי טיפים של זבוב.\u0004","ואף בהגדרה זו \u0003תני\u0004 \u0005[שנה]\u0006 ומסייג אותה \u0003ר' חייא: ו\u0004בלבד שיהיו נחירי האף \u0003מקורבין זה לזה.\u0004 ועוד בהגדרת השפיר המרוקם: \u0003ו\u0004צורת \u0003פיו\u0004 הריהי כסדק צר מאוד ה\u0003מתוח\u0004 הנמתח לרוחב \u0003כ\u0004אילו היה \u0003חוט השערה.\u0004 \u0003וגויתו\u0004 (איבר המין הזכר), אם מזהים בו סימן מין, הריהו \u0003כעדשה, ואם היתה\u0004 זו ממין \u0003נקבה\u0004 — \u0003נדונה\u0004 (מובחנת) הוא סימן מינה בדמיונה \u0003כשעורה\u0004 הסדוקה \u0003לארכה.\u0004","\u0003ו\u0004עוד בהגדרתו: בשלב זה של התפתחות העובר, מלבד הראש המתפתח שבו, \u0003חתוך\u0004 (חיטוב) \u0003ידים ורגלים\u0004 עדיין \u0003אין לו.\u0004 \u0003ועליו,\u0004 על העובר בשלב זה \u0003מפורש בקבלה: \"הלא כחלב תתיכני וכגבינה תקפיאני עור ובשר תלבישני ועצמות וגידים תסוככני חיים וחסד עשית עמדי ופקדתך שמרה רוחי\"\u0004 (איוב י, י).","\u0003ו\u0004כאשר מבקשים לדעת מהו מינו, אם זכר או נקבה, \u0003אין בודקין אותו ב\u0004שטיפה ב\u0003מים,\u0004 משום \u0003שהמים עזין\u0004 (פעולתם חזקה מדי),"],["\u0003ו\u0004כתוצאה מכך, הריהם \u0003טורדין\u0004 (ממעכים) \u0003אותו\u0004 את השפיר, \u0003אלא בודקין אותו ב\u0004אמצעות \u0003שמן\u0004 — משום \u0003שהשמן\u0004 הריהו \u0003רך ומצחצחו\u0004 (מנקה ומבריק) את הדבר עליו הוא נמשח, וכך ניתן לראות היטב מהו מינו של שפיר זה. \u0003ו\u0004עוד בדין בדיקה זו: \u0003אין רואין\u0004 (בוחנים את השפיר) \u0003אלא ב\u0004אור ה\u0003חמה.\u0004","ושואלים: \u0003כיצד בודקין אותו?\u0004 ותוהים על עצם השאלה: \u0003כיצד בודקין אותו?\u0004 והרי זה \u0003כדאמרינן\u0004 \u0005[כמו שאמרנו]!\u0006 \u0003אלא\u0004 מסבירים את השאלה: \u0003במה בודקין אותו לידע אם זכר הוא אם נקבה היא?\u0004","\u0003אבא שאול בר נש, ואמרי לה\u0004 \u0005[ויש האומרים אותה]\u0006 בשמו של \u0003אבא שאול בר רמש, אומר:\u0004 האדם הבודק את השפיר \u0003מביא קיסם\u0004 (כפיס עץ דק) \u0003שראשו חלק, ומנענע\u0004 (מניע) אותו \u0003באותו מקום\u0004 (מקום הערוה), ורואה: \u0003אם\u0004 הקיסם \u0003מסכסך\u0004 (נתקל ומופרע) בזמן שמניעים אותו שם — \u0003בידוע שזכר הוא,\u0004 ואיבר המין הוא שמפריע לתנועת הקיסם. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שתנועת הקיסם אינה מופרעת — \u0003בידוע שנקבה היא.\u0004","\u0003אמר רב נחמן אמר רבה בר אבוה: לא שנו\u0004 חכמים אופן בדיקה זה \u0003אלא\u0004 רק כשמניעים אותו \u0003מלמטה למעלה.\u0004 \u0003אבל\u0004 אם הניעו את הקיסם \u0003מן הצדדין\u0004 (מצד לצד), אף אם הופרעה התנועה של הקיסם — אין זה מעיד שזכר הוא, שכן \u0003אימא\u0004 \u0005[\u0006יש מקום \u0005לומר]\u0006 שנקיבה היא, ו\u0003כותלי בית הרחם נינהו\u0004 \u0005[הם]\u0006 שהפריעו לתנועתו.","שנינו בברייתא זו בסימני השפיר המרוקם, שאם היה איבר המין כצורת שעורה לאורכה, הרי זו נקבה. ועל כך \u0003אמר רב אדא בר אהבה:\u0004 כך \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בנוסח שלם של הדברים: \u0003\"אם היתה נקבה\u0004 — \u0003נדונה כשעורה סדוקה\u0004 לאורכה\". \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב נחמן: ודילמא\u0004 \u0005[ושמא]\u0006 אין שעורה סדוקה זו אלא \u0003חוט של ביצים\u0004 (כעין חוט המפריד בין ביצי הזכר ונראה כסדק עמוק) המצוי בזכר \u0003נינהו\u0004 \u0005[הן]?\u0006 \u0003אמר אביי:\u0004 אין לומר כן, שהרי \u0003השתא\u0004 \u0005[עכשיו]\u0006 בשלב זה של ההתפתחות ה\u0003ביצים גופייהו לא ידיעי\u0004 \u0005[עצמן אינן ידועות,\u0006 ניכרות\u0005],\u0006 \u0003חוט של ביצים ידיע\u0004 \u0005[ידוע,\u0006 ניכר\u0005]?\u0006","עוד שנינו בברייתא כי בתחילת התפתחותו של העובר עדיין אין לו חיתוך ידים ורגלים, ועל כך \u0003אמר רב עמרם, תנא\u0004 \u0005[שנה]\u0006 החכם עוד, כי כאשר מתחילות להיווצר ידים ורגלים של עובר, \u0003שתי ירכותיו\u0004 נראות \u0003כשני חוטין של זהורית\u0004 (גזיר אריג צמר הצבוע בצבע אדום). \u0003ו\u0004עוד \u0003אמר רב עמרם\u0004 והוסיף \u0003עלה\u0004 \u0005[עליה,\u0006 על הברייתא\u0005]:\u0006 שתי ירכותיו של העובר נראות \u0003כשל\u0004 שני חוטי ה\u0003ערב\u0004 שבמסכת האריג. \u0003ושני זרועותיו\u0004 של העובר נראות \u0003כשני חוטין של זהורית, ואמר רב עמרם עלה\u0004 \u0005[עליה]:\u0006 \u0003כשל\u0004 חוטי ה\u0003שתי\u0004 שבמסכת האריג.","ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 \u0005[גדול השיניים],\u0006 \u0003לא תעביד עובדא\u0004 \u0005[אל תעשה מעשה,\u0006 אל תקבע\u0005]\u0006 בבדיקה זו שהעובר נחשב ולד, אלא \u0003עד שישעיר\u0004 (שתופענה בולד שערות בראשו). ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל\u0004 בעניינה של המפלת שפיר כי \u0003אחת\u0004 (הן) \u0003זו\u0004 שהפילה שפיר שתוכו הינו עכור \u0003ואחת\u0004 (והן) \u0003זו\u0004 שהפילה שפיר שתוכו הינו צלול — הריהי \u0003חוששת\u0004 שולד הוא שהפילה, וטמאה מספק!","ומשיבים: \u0003אמר רב אמי בר שמואל, לדידי מפרשא\u0004 \u0005[לי עצמי מתפרש]\u0006 \u0003לי מיניה\u0004 \u0005[ממנו]\u0006 \u0003דמר שמואל\u0004 בהסבר כוונת דבריו: \u0003לחוש\u0004 (לחשוש) שמא היה זה ולד — הריהי \u0003חוששת,\u0004 ואולם \u0003ימי טהרה\u0004 (כיולדת ולד) — \u0003לא יהבינן\u0004 \u0005[אין אנו נותנים]\u0006 \u0003לה,\u0004 אלא \u0003עד שישעיר.\u0004 שכן כל עוד לא השעיר הולד, אין בידינו הבקיאות כדי לקבוע שהשפיר הינו ולד.","ושואלים: \u0003למימרא דמספקא ליה\u0004 \u0005[האם לומר שמסופק היה לו]\u0006 \u0003לשמואל\u0004 בדבר זה, \u0003והא ההוא שפירא דאתאי לקמיה\u0004 \u0005[והרי\u0006 מעשה היה ב\u0005שפיר אחד שהובא לפני]\u0006 \u0003דמר שמואל\u0004 לקבוע בו אם ולד הוא אם לאו. ו\u0003אמר\u0004 שמואל בו כי \u0003הא בר ארבעין וחד יומא\u0004 \u0005[זה\u0006 העובר הינו \u0005בן ארבעים ואחד יום].\u0006 \u0003ו\u0004נמסר כי \u0003חשיב\u0004 \u0005[חישב]\u0006 שמואל את מספר הימים שעברו \u0003מיומא דאזלא\u0004 \u0005[מהיום שהלכה]\u0006 אותה אשה \u0003לטבילה עד ההוא יומא\u0004 \u0005[אותו היום],\u0006 \u0003ו\u0004נמצא כי \u0003לא הוה\u0004 \u0005[לא היה]\u0006 מספר הימים \u0003אלא ארבעין יומין\u0004 \u0005[ארבעים ימים].\u0006","\u0003ואמר להו\u0004 \u0005[להם]\u0006 שמואל: \u0003האי\u0004 \u0005[זה,\u0006 הבעל\u0005]\u0006 \u0003ב\u0004זמן שאשתו היתה \u0003נדה בעל! כפתיה\u0004 \u0005[כפתו],\u0006 \u0003ואודי\u0004 \u0005[והודה]\u0006 שכך היה. הרי שבקי היה שמואל היטב בהתפתחות העובר, וכיצד זה מסופק היה בטיבו של השפיר, שלא השעיר? ומשיבים: \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד בדבר זה\u0005]\u0006 הוא \u0003שמואל, דרב גובריה\u0004 \u0005[ש\u0006כן \u0005כוחו גדול].\u0006 והוא עצמו ידע היטב, ומה שהורה — לא היתה זו אלא הוראה לרב יהודה שלא היה בקי כמותו, שלא יקבע בטיבו של העובר עד שישעיר.","שנינו במשנתנו כי \u0003המפלת סנדל\u0004 או שליה יושבת לזכר ולנקבה. ומביאים ממה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003סנדל דומה לדג\u0004 \u0003של ים,\u0004 ששמו \"סנדל\". \u0003מתחלתו\u0004 עובר זה \u0003ולד הוא, אלא שנרצף\u0004 (נמעך). \u0003רבן שמעון בן גמליאל אומר\u0004 בתיאור צורתו של ה\u0003סנדל\u0004 כי הריהו \u0003דומה ללשון של שור הגדול.\u0004 ועוד בתיאור צורתו של הסנדל, \u0003משום\u0004 \u0005[בשם]\u0006 \u0005רבותינו העידו כי\u0006 \u0003סנדל צריך\u0004 שתתקיים בו \u0003צורת פנים.\u0004 שאם אין בו צורת פנים — אין זה סנדל הנחשב כולד.","ובדבר זה \u0003אמר רב יהודה, אמר שמואל: הלכה, סנדל צריך צורת פנים.\u0004 ועוד \u0003אמר רב אדא, אמר רב יוסף, אמר ר'\u0004 \u0003יצחק: סנדל צריך צורת פנים, ו\u0004אם יש בו צורת פנים — הריהו נחשב כסנדל, \u0003אפילו\u0004 אם הם אינם במקומם אלא \u0003מאחוריו.\u0004 וטעם הדבר: \u0003משל לאדם שסטר את חבירו, ו\u0004מכח הסטירה \u0003החזיר\u0004 הנסטר את \u0003פניו לאחוריו.\u0004 ואף הסנדל, מחמת כוח שהופעל עליו במעי אמו, זזו פניו לאחור.","ומסופר כי \u0003בימי ר'\u0004 \u0003ינאי בקשו לטהר את הסנדל שאין לו צורת פנים, אמר להם ר'\u0004 \u0003ינאי: טיהרתם את הוולדות!\u0004 שכן לדעתו הסנדל הריהו ולד, אף שאין בו צורת פנים.","ותוהים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003משום\u0004 \u0005[בשם]\u0006 \u0003רבותינו העידו\u0004 כי ה\u0003סנדל צריך\u0004 שתהיה בו \u0003צורת פנים\u0004 כדי שייחשב כולד! ומשיבים: \u0003אמר רב ביבי בר אביי, אמר ר'\u0004 \u0003יוחנן:\u0004 עדות זו משם רבותינו, \u0003מעדותו של ר'\u0004 \u0003נחוניא נשנית משנה זו,\u0004 והרי זו איפוא דעת יחיד, ואין להקשות ממנה. ומעירים כי \u0003אמר ר'\u0004 \u0003זעירא: זכה בה רב ביבי\u0004 בר אביי, שהביא את דברי ר' יוחנן הללו, \u0003בשמעתיה\u0004 \u0005[בשמועתו],\u0006 למוסרה לפני חכמים. \u0003דאנא\u0004 \u0005[ש\u0006כן \u0005אני]\u0006 \u0003והוא הוינא יתבינן קמיה\u0004 \u0005[היינו יושבים\u0006 יחד, כתלמידים \u0005לפני]\u0006 \u0003ר' יוחנן כי\u0004 \u0005[כאשר]\u0006 \u0003אמרה\u0004 ר' יוחנן \u0003להא שמעתא\u0004 \u0005[את השמועה הזו],\u0006 \u0003וקדם איהו\u0004 \u0005[הוא]\u0006 אותי \u0003ואמר, וזכה בה.\u0004","שנינו במשנתנו כי המפלת סנדל תשב עליו לזכר ולנקבה. ושואלים: \u0003למה הזכירו\u0004 במשנה \u0003סנדל,\u0004 שבשל כך הריהי יושבת עליו לזכר ולנקבה? \u0003והלא אין סנדל שאין עמו ולד,\u0004 והרי אמו טמאת לידה מחמת אותו ולד, וכיון שאין ידוע מה הפילה צריכה היא לשבת לזכר ולנקבה!","ומשיבים: \u0003אי דאתילידא\u0004 \u0005[אם\u0006 אכן מדובר כ\u0005שנולדה]\u0006 \u0003נקבה בהדיה\u0004 \u0005[אתו,\u0006 עם הסנדל\u0005],\u0006 ואז היולדת צריכה לשבת שבועיים על לידתה של זו — \u0003הכי נמי\u0004 \u0005[אכן כן],\u0006 לא היה צורך לכתוב במשנתנו סנדל. ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דאתיליד\u0004 \u0005[שנולד]\u0006 \u0003זכר בהדיה\u0004 \u0005[אתו,\u0006 עם הסנדל\u0005],\u0006 ומעתה צריכה האשה לשבת רק שבעה ימים לימי טומאת לידתה, ומעתה","\u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 היה מקום לומר\u0005]:\u0006 \u0003הואיל ואמר רב יצחק בר אמי\u0004 כי כאשר ה\u0003אשה מזרעת תחילה\u0004 בשעת התשמיש — הריהי \u0003יולדת זכר,\u0004 וכאשר ה\u0003איש\u0004 הוא ה\u0003מזריע תחלה\u0004 בשעת התשמיש — הריהי \u0003יולדת נקבה,\u0004 \u0003מדהא\u0004 \u0005[מ\u0006תוך \u0005שזה]\u0006 הנולד עם הסנדל הריהו \u0003זכר\u0004 — \u0003הא נמי\u0004 \u0005[זה,\u0006 הסנדל הריהו \u0005גם כן]\u0006 \u0003זכר,\u0004 ולא תשב אלא לזכר בלבד.","לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 תנא של משנתנו, \u0005משמיע לנו]\u0006 כי \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003שניהם הזריעו בבת אחת,\u0004 ולכך \u0003האי\u0004 \u0005[זה,\u0006 הולד שעמו\u0005]\u0006 הריהו אמנם \u0003זכר, ו\u0004אילו \u0003האי\u0004 \u0005[זה,\u0006 הסנדל\u0005]\u0006 הריהו \u0003נקבה.\u0004","\u0003דבר אחר:\u0004 טעם הדבר שכתבה המשנה סנדל, לענין \u0003שאם תלד נקבה לפני שקיעת החמה\u0004 (שהוא נחשב עדיין כיום זה), \u0003ו\u0004את ה\u0003סנדל לאחר שקיעת החמה\u0004 (שנחשב ליום הבא) — דינה הוא שתהא","\u0003מונה\u0004 את מנין שמונים הימים (ככל יולדת נקבה) מיום זה, ויום השמונים ואחד (הבא לאחר גמר מנין ימי טהרה) הריהו \u0003תחלת נדה\u0004 (תחילת הימים שאם תראה בהם דם, הריהי נחשבת לנדה וטמאה שבעת ימים), ומנין זה הריהו נספר \u0003ל\u0004לידת ה\u0003ראשון\u0004 (הנקבה). ואולם כיון שאפשר שהסנדל הריהו נקבה, והסתיימו אם כן שמונים הימים רק למחרת היום (שהרי הסנדל נולד למחרת היום שנולדה בו הנקבה שאתו), נמצא איפוא ש\u0003תחלת\u0004 ימי \u0003נדה\u0004 נמנים \u0003ל\u0004לידת ה\u0003אחרון,\u0004 הסנדל. משום כך נצרכה להשמיענו גם סנדל.","ומתוך ששאלו לענין הזכרת סנדל במשנתנו, שואלים עוד כיוצא בזה לענין הזכרת סנדל במשניות אחרות: \u0003סנדל דתנן\u0004 \u0005[ששנינו],\u0006"]]};
